        function getCanonicalModelId(idOrName) {
            if (!idOrName) return null;
            const str = String(idOrName).trim();
            const lower = str.toLowerCase();

            // 1. Direct match by exact ID
            const byId = AVAILABLE_MODELS.find(m => m.id.toLowerCase() === lower);
            if (byId) return byId.id;

            // 2. Direct match by exact Name
            const byName = AVAILABLE_MODELS.find(m => m.name.toLowerCase() === lower);
            if (byName) return byName.id;

            // 3. Known aliases & legacy mappings
            if (lower.includes('haiku') || (lower.includes('claude') && lower.includes('4.5'))) return 'claude-4-5-haiku';
            if (lower.includes('claude') && lower.includes('sonnet')) return 'claude-sonnet-5';
            if (lower.includes('claude') && lower.includes('opus')) return 'claude-opus-5.5';
            if (lower === 'o3-mini' || lower === 'gpt-4o' || lower === 'openai/gpt-4o') return 'o3-mini';
            if (lower.includes('gpt-5-mini') || lower.includes('gpt-4o-mini') || lower.includes('gpt 5-mini') || lower.includes('gpt-4o mini') || lower.includes('5 mini')) return 'gpt-5-mini';
            if (lower.includes('sol')) return 'gpt-6-sol';
            if (lower.includes('qwen') && (lower.includes('coder') || lower.includes('plus'))) return 'qwen-2.5-coder';
            if (lower.includes('qwen') && lower.includes('max')) return 'qwen-3.8-max';
            if (lower.includes('gemini') && (lower.includes('3.8') || lower.includes('3-8'))) return 'gemini-3.8-flash';
            if (lower.includes('gemini') && (lower.includes('flash') || lower.includes('2.5') || lower.includes('3.5'))) return 'gemini-2.5-flash';
            if (lower.includes('gemini') && lower.includes('pro')) return 'gemini-3.1-pro';
            if (lower.includes('deepseek') && (lower.includes('r1') || lower.includes('reasoner'))) return 'deepseek-r1';
            if (lower.includes('deepseek') && lower.includes('pro')) return 'deepseek-v4-pro';
            if (lower.includes('deepseek')) return 'deepseek-v4-flash';
            if (lower.includes('kimi')) return 'kimi-k3';
            if (lower.includes('grok') && lower.includes('7')) return 'grok-4-7';
            if (lower.includes('grok')) return 'grok-4-3';
            if (lower.includes('mahi') || lower === 'auto' || lower === 'default') return 'mahi-engine';

            return str;
        }
        window.getCanonicalModelId = getCanonicalModelId;

        function getOpenRouterModelSlug(idOrName) {
            if (!idOrName) return 'mahi-engine';
            const canonicalId = getCanonicalModelId(idOrName) || idOrName;
            const model = AVAILABLE_MODELS.find(m => m.id === canonicalId || m.name === canonicalId || m.id === idOrName || m.name === idOrName);
            if (model && model.openRouterModel) return model.openRouterModel;
            return canonicalId;
        }
        window.getOpenRouterModelSlug = getOpenRouterModelSlug;

        function getModelById(idOrName) {
            const canonicalId = getCanonicalModelId(idOrName);
            const found = AVAILABLE_MODELS.find(m => m.id === canonicalId);
            if (found) return found;

            const lower = String(idOrName || '').toLowerCase();
            const isClaude = lower.includes('claude') || lower.includes('anthropic') || lower.includes('haiku');
            const isMahi = lower.includes('mahi');
            return {
                id: canonicalId || idOrName,
                name: idOrName,
                provider: isClaude ? 'anthropic' : (isMahi ? 'custom' : 'custom'),
                icon: isClaude ? 'anthropic' : (isMahi ? 'zap' : 'custom'),
                color: isClaude ? 'bg-amber-600' : 'bg-slate-500'
            };
        }
        window.getModelById = getModelById;

