        const STORAGE_KEY = 'mestrio_platform_chats_v1';

        function escapeHtml(str) {
            if (!str) return '';
            return str.replace(/[&<>"']/g, function (m) {
                return {
                    '&': '&amp;',
                    '<': '&lt;',
                    '>': '&gt;',
                    '"': '&quot;',
                    "'": '&#039;'
                }[m];
            });
        }

        function formatChatTitle(content) {
            if (!content) return 'New conversation';
            const cleaned = content.replace(/\s+/g, ' ').trim();
            if (cleaned.length <= 32) return cleaned;
            return cleaned.substring(0, 30) + '...';
        }

        function formatTimeAgo(dateString) {
            if (!dateString) return 'Just now';
            const now = Date.now();
            const then = new Date(dateString).getTime();
            const diffSec = Math.floor((now - then) / 1000);
            if (diffSec < 60) return 'Just now';
            const diffMin = Math.floor(diffSec / 60);
            if (diffMin < 60) return diffMin + 'm';
            const diffHours = Math.floor(diffMin / 60);
            if (diffHours < 24) return diffHours + 'h';
            const diffDays = Math.floor(diffHours / 24);
            return diffDays + 'd';
        }

        function saveToLocalStorage() {
            try {
                // Filter out incognito / temporary conversations from persistent storage
                const persistentConversations = (chatState.conversations || []).filter(c => !c.isIncognito);
                const currentConv = (chatState.conversations || []).find(c => c.id === chatState.currentConversationId);
                const isCurrentIncognito = Boolean(currentConv && currentConv.isIncognito);

                const data = {
                    conversations: persistentConversations,
                    currentConversationId: isCurrentIncognito ? (persistentConversations[0] ? persistentConversations[0].id : null) : chatState.currentConversationId,
                    selectedModel: chatState.selectedModel
                };
                localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
            } catch (e) {
                console.warn('localStorage save failed:', e);
            }
        }

        function loadFromLocalStorage() {
            try {
                const raw = localStorage.getItem(STORAGE_KEY);
                if (raw) {
                    const parsed = JSON.parse(raw);
                    if (parsed && typeof parsed === 'object') {
                        return parsed;
                    }
                }
            } catch (e) {
                console.warn('localStorage load failed:', e);
            }
            return null;
        }

