        function generateResearchReport(query, depth) {
            const cleanWords = (query || '').replace(/[^\w\s]/gi, '').split(/\s+/).filter(w => w.length > 2);
            const topicPhrase = cleanWords.slice(0, 5).map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ') || (query ? query.trim() : 'Requested Topic');
            const cleanQuery = query ? query.trim() : topicPhrase;
            const base = {
                title: `${topicPhrase} — Comprehensive Technical Investigation & Market Trajectory`,
                overview: `A rigorous multi-vector investigation into "${cleanQuery}" [1]. This analytical report evaluates systemic methodologies, empirical benchmarks, core implementation architectures, and critical trade-offs shaping the domain [2].`,
                keyFindings: [
                    `Strategic Landscape & Baseline Vectors: Cross-sectional evaluation of "${topicPhrase}" indicates significant acceleration in operational maturity and methodology standardization [1].`,
                    `Technical & Architectural Trade-offs: In-depth analysis highlights critical trade-offs between rapid short-term implementation velocity and sustainable, long-term operational resilience [2].`,
                    `Empirical Indicators & Performance Benchmarks: Measurable industry benchmarks demonstrate measurable performance differentials between modern best practices and legacy approaches [3].`,
                    `Governance, Verification & Risk Controls: Industry standards increasingly necessitate robust verification protocols, end-to-end auditability, and proactive governance frameworks [1].`
                ],
                sections: [
                    {
                        title: `1. Foundational Architecture & Core Methodologies for ${topicPhrase}`,
                        content: `Initial empirical benchmarking highlights rapid evolution in baseline metrics [1]. Technical analysis reveals that structured alignment, verified methodologies, and iterative feedback loops serve as the primary determinants of successful execution.`
                    },
                    {
                        title: `2. Comparative Dynamics & Trade-off Matrix`,
                        content: `Synthesizing comparative evidence demonstrates clear trade-offs between rapid short-term scalability and robust long-term architectural stability [2]. Organizations prioritizing modular flexibility and evidence-grounded frameworks consistently outperform rigid monolithic implementations.`
                    },
                    {
                        title: `3. Strategic Implementation, Governance & Benchmarks`,
                        content: `Establishing sustainable operational frameworks requires end-to-end auditability, proactive risk modeling, and cross-functional alignment [3]. Continuous benchmarking ensures resilience against volatile market and regulatory shifts.`
                    }
                ],
                conclusion: `Advancing outcomes in ${topicPhrase} demands balanced synthesis of innovative execution and disciplined governance [1]. Long-term leadership favors entities that cultivate adaptive infrastructure and evidence-grounded decision architectures [2].`,
                sources: [
                    { name: `Global Intelligence & Analysis on ${topicPhrase}`, url: `https://en.wikipedia.org/wiki/${encodeURIComponent(topicPhrase.replace(/\s+/g, '_'))}`, type: "Authoritative Reference" },
                    { name: `Industry Benchmarks & Empirical Review: ${topicPhrase}`, url: "https://www.nature.com", type: "Peer-Reviewed Analysis" },
                    { name: `Standards, Methodologies & Technical Synthesis`, url: "https://arxiv.org", type: "Technical Architecture" }
                ]
            };

            if (depth === 'quick') {
                base.keyFindings = base.keyFindings.slice(0, 3);
                base.sections = base.sections.slice(0, 2);
            } else if (depth === 'deep') {
                base.sections.push({
                    title: `4. Quantitative Sensitivity & Risk Sensitivity Matrix for ${topicPhrase}`,
                    content: `Stress-testing key assumptions reveals that execution velocity is primarily sensitive to capital availability, cross-disciplinary talent density, and regulatory clarity. Continuous evaluation underscores the necessity of continuous recalibration.`
                });
            }

            return base;
        }

        function formatReportAsMarkdown(report) {
            if (!report) return '';
            let md = `# ${report.title || 'Deep Research Report'}\n\n`;
            if (report.overview) md += `${report.overview}\n\n`;
            if (report.keyFindings && report.keyFindings.length > 0) {
                md += `## Key Findings\n`;
                report.keyFindings.forEach((kf, idx) => {
                    md += `${idx + 1}. ${kf}\n`;
                });
                md += `\n`;
            }
            if (report.sections && report.sections.length > 0) {
                md += `## Detailed Analysis\n`;
                report.sections.forEach(sec => {
                    md += `### ${sec.title}\n${sec.content}\n\n`;
                });
            }
            if (report.conclusion) md += `## Conclusion\n${report.conclusion}\n\n`;
            if (report.sources && report.sources.length > 0) {
                md += `## Sources\n*Demo sources — real web sources will appear when research is connected.*\n`;
                report.sources.forEach((s, idx) => {
                    md += `${idx + 1}. **${s.name}** (${s.type}) — ${s.notes}\n`;
                });
            }
            return md;
        }

        function copyTextToClipboard(text, btnEl) {
            function showCopied() {
                if (!btnEl) return;
                const copyText = btnEl.querySelector('.copy-text');
                const orig = copyText ? copyText.textContent : 'Copy Report';
                if (copyText) copyText.textContent = 'Copied!';
                btnEl.classList.add('text-emerald-700', 'border-emerald-300', 'bg-emerald-50');
                setTimeout(() => {
                    if (copyText) copyText.textContent = orig;
                    btnEl.classList.remove('text-emerald-700', 'border-emerald-300', 'bg-emerald-50');
                }, 2000);
            }
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(text).then(showCopied).catch(fallback);
            } else {
                fallback();
            }
            function fallback() {
                const ta = document.createElement('textarea');
                ta.value = text;
                ta.style.position = 'fixed';
                ta.style.opacity = '0';
                document.body.appendChild(ta);
                ta.select();
                try { document.execCommand('copy'); showCopied(); } catch (e) { }
                document.body.removeChild(ta);
            }
        }

