        function renderMobileComposerRefChips() {
            const wrap = document.getElementById('mobile-image-ref-chips-wrap');
            if (!wrap) return;
            const refs = window.mobileComposerAttachedRefs || [];
            if (refs.length === 0) {
                wrap.classList.add('hidden');
                wrap.innerHTML = '';
                return;
            }
            wrap.classList.remove('hidden');
            wrap.className = 'w-full flex items-center gap-2.5 px-1 pt-1 pb-0.5 mb-2.5 flex-nowrap overflow-x-auto ideogram-custom-scroll transition-none';
            wrap.innerHTML = '';

            refs.forEach((ref, idx) => {
                const card = document.createElement('div');
                card.className = 'w-20 h-24 rounded-2xl overflow-hidden border border-slate-200/85 relative shrink-0 shadow-xs cursor-pointer group bg-slate-100 transition-transform active:scale-[0.98]';
                card.setAttribute('data-index', idx);

                const img = document.createElement('img');
                img.src = ref.dataUrl;
                img.alt = ref.name || 'Reference';
                img.className = 'w-full h-full object-cover pointer-events-none';
                card.appendChild(img);

                const removeBtn = document.createElement('button');
                removeBtn.type = 'button';
                removeBtn.className = 'w-5 h-5 rounded-full bg-black/60 hover:bg-black/80 text-white flex items-center justify-center absolute top-1.5 right-1.5 z-10 transition-transform active:scale-90 text-[10px] font-bold cursor-pointer';
                removeBtn.innerHTML = '<svg class="w-3 h-3 text-white" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>';
                removeBtn.title = 'Remove';
                removeBtn.onclick = (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    window.mobileComposerAttachedRefs.splice(idx, 1);
                    renderMobileComposerRefChips();
                    autoResizeMobileComposerTextarea();
                    syncMobileImageSendButton();
                };
                card.appendChild(removeBtn);

                // Tapping card opens fullscreen lightbox cleanly
                card.onclick = (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    openMobileComposerRefLightbox(ref.dataUrl);
                };

                wrap.appendChild(card);
            });

            // Ensure left attach button remains clean, minimal, transparent (no dark fill)
            const attachBtn = document.getElementById('mobile-image-attach-btn');
            if (attachBtn) {
                attachBtn.className = 'w-9 h-9 rounded-full bg-transparent flex items-center justify-center text-slate-600 hover:bg-slate-100/70 active:scale-95 transition-none shrink-0 cursor-pointer';
            }
        }
