        // Helper to query templates API seamlessly across port 3000 (dev server) and port 5001 (Direct Express)
        async function fetchTemplateApi(path, options = {}) {
            const cleanPath = path.startsWith('/') ? path : '/' + path;
            const base = (typeof getApiBaseUrl === 'function') ? getApiBaseUrl() : '';
            const primaryUrl = base ? `${base}${cleanPath}` : cleanPath;
            let res;
            try {
                res = await fetch(primaryUrl, options);
                if (res && res.status !== 404) {
                    return res;
                }
            } catch (_) {}
            const host = (typeof window !== 'undefined' && window.location.hostname) ? window.location.hostname : '127.0.0.1';
            const fallbackUrl = `http://${host}:5001${cleanPath}`;
            try {
                const fallbackRes = await fetch(fallbackUrl, options);
                return fallbackRes;
            } catch (err) {
                if (res) return res;
                throw err;
            }
        }
        window.fetchTemplateApi = fetchTemplateApi;

