        function getImageWorkflowTool(img) {
            if (!img) return 'generate-image';
            if (img.isRemoveBg || img.tool === 'remove-background' || img.type === 'remove-bg' || img.model === 'remove-background' || img.modelName === 'Remove Background' || img.model === 'fal-ai/birefnet' || img.modelName === 'BiRefNet Studio' || img.model === 'Transparent Cutout' || img.modelName === 'Transparent Cutout' || (img.prompt && img.prompt.includes('Transparent Cutout'))) {
                return 'remove-background';
            }
            if (img.isUpscale || img.tool === 'upscale-image' || img.type === 'upscale' || (img.title && img.title.startsWith('Upscaled ')) || img.model === 'clarity-4k-upscaler' || img.modelName === 'Clarity 4K Upscaler') {
                return 'upscale-image';
            }
            if (img.isPreciseEdit || img.tool === 'precise-edit' || img.model === 'black-forest-labs/flux-fill-pro' || img.modelName === 'Flux Fill Pro') {
                return 'precise-edit';
            }
            if (img.isVectorize || img.isVector || img.tool === 'vectorize' || img.model === 'recraft/recraft-v3' || img.model === 'recraft-ai/recraft-v3' || img.modelName === 'Recraft V3 Vectorizer' || img.model === 'svg-vectorizer' || img.modelName === 'SVG Vectorizer') {
                return 'vectorize';
            }
            return 'generate-image';
        }

