        // Helper: escape HTML for safety
        /* duplicate escapeHtml */ var _escapeHtml_dup2 = function(str) {
            if (!str) return '';
            return String(str)
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#039;');
        }

        // Robust Error String Extractor (Eliminates [object Object])
        function getErrorMessage(err) {
            if (!err) return 'An error occurred';
            if (typeof err === 'string') return err;
            if (err?.error?.message && typeof err.error.message === 'string') return err.error.message;
            if (err?.error && typeof err.error === 'string') return err.error;
            if (err?.message && typeof err.message === 'string') return err.message;
            try {
                return JSON.stringify(err);
            } catch (_) {
                return String(err);
            }
        }
        window.getErrorMessage = getErrorMessage;

        // Toast notification system
        function showStudioToast(msg, duration = 3000) {
            if (typeof window !== 'undefined' && window.innerWidth < 768) return;
            const existing = document.getElementById('studio-toast-banner');
            if (existing) existing.remove();

            const cleanMsg = getErrorMessage(msg);

            const toast = document.createElement('div');
            toast.id = 'studio-toast-banner';
            toast.className = 'fixed bottom-5 right-5 z-[99999] px-4 py-2.5 rounded-xl bg-slate-900/90 dark:bg-white/95 text-white dark:text-slate-900 text-xs font-medium shadow-2xl backdrop-blur-md border border-white/10 dark:border-black/10 flex items-center gap-2 animate-in fade-in slide-in-from-bottom-2 duration-200 select-none';
            toast.innerHTML = `
                <svg class="w-4 h-4 text-emerald-400 dark:text-emerald-600 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
                <span>${escapeHtml(cleanMsg)}</span>
            `;
            document.body.appendChild(toast);
            setTimeout(() => {
                toast.classList.add('opacity-0', 'transition-opacity');
                setTimeout(() => toast.remove(), 250);
            }, duration);
        }

        // Silent direct download helper
        async function triggerSilentImageDownload(url, filename = 'generated-image.jpg') {
            try {
                if (url && (url.startsWith('data:image/svg+xml') || url.includes('.svg'))) {
                    if (!filename.endsWith('.svg')) {
                        filename = filename.replace(/\.(jpg|jpeg|png|webp)$/, '') + '.svg';
                    }
                    const commaIdx = url.indexOf(',');
                    const raw = url.substring(commaIdx + 1);
                    const decoded = url.includes(';base64') ? atob(raw) : decodeURIComponent(raw);
                    const blob = new Blob([decoded], { type: 'image/svg+xml;charset=utf-8' });
                    const blobUrl = URL.createObjectURL(blob);
                    const a = document.createElement('a');
                    a.href = blobUrl;
                    a.download = filename;
                    document.body.appendChild(a);
                    a.click();
                    a.remove();
                    setTimeout(() => URL.revokeObjectURL(blobUrl), 1500);
                    showStudioToast('Downloaded SVG file');
                    return;
                }
                if (url && (url.startsWith('data:image/png') || url.includes('.png')) && filename.endsWith('.jpg')) {
                    filename = filename.replace(/\.jpg$/, '.png');
                }
                showStudioToast('Preparing download...');
                if (url.startsWith('data:image/')) {
                    const a = document.createElement('a');
                    a.href = url;
                    a.download = filename;
                    document.body.appendChild(a);
                    a.click();
                    a.remove();
                    showStudioToast('Download started');
                    return;
                }
                const res = await fetch(url);
                const blob = await res.blob();
                const blobUrl = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = blobUrl;
                a.download = filename;
                document.body.appendChild(a);
                a.click();
                a.remove();
                setTimeout(() => URL.revokeObjectURL(blobUrl), 1000);
                showStudioToast('Download started');
            } catch (err) {
                const a = document.createElement('a');
                a.href = url;
                a.download = filename;
                a.target = '_blank';
                document.body.appendChild(a);
                a.click();
                a.remove();
            }
        }

        // ═══════════════════════════════════════════════════════════════════
        // SVG VECTOR DOWNLOAD & CODE PREVIEW MODAL HANDLERS
        // ═══════════════════════════════════════════════════════════════════

        let currentVectorizeSvgData = {
            content: '',
            filename: 'vectorized.svg',
            meta: 'SVG Vectorizer • Detailed'
        };

        function triggerSvgDownload(svgDataOrUrl, filename = 'vectorized-image.svg') {
            if (!filename || !filename.endsWith('.svg')) {
                filename = (filename || 'vectorized-image') + '.svg';
            }
            try {
                showStudioToast('Preparing SVG download...');
                let blob;
                if (typeof svgDataOrUrl === 'string' && svgDataOrUrl.trim().startsWith('<svg')) {
                    blob = new Blob([svgDataOrUrl], { type: 'image/svg+xml;charset=utf-8' });
                } else if (typeof svgDataOrUrl === 'string' && svgDataOrUrl.startsWith('data:image/svg+xml')) {
                    const commaIdx = svgDataOrUrl.indexOf(',');
                    const raw = svgDataOrUrl.substring(commaIdx + 1);
                    const decoded = svgDataOrUrl.includes(';base64') ? atob(raw) : decodeURIComponent(raw);
                    blob = new Blob([decoded], { type: 'image/svg+xml;charset=utf-8' });
                } else if (typeof svgDataOrUrl === 'string' && (svgDataOrUrl.startsWith('blob:') || svgDataOrUrl.startsWith('http'))) {
                    const a = document.createElement('a');
                    a.href = svgDataOrUrl;
                    a.download = filename;
                    document.body.appendChild(a);
                    a.click();
                    a.remove();
                    showStudioToast('Downloaded SVG file');
                    return;
                } else {
                    blob = new Blob([String(svgDataOrUrl || '')], { type: 'image/svg+xml;charset=utf-8' });
                }
                const blobUrl = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = blobUrl;
                a.download = filename;
                document.body.appendChild(a);
                a.click();
                a.remove();
                setTimeout(() => URL.revokeObjectURL(blobUrl), 1000);
                showStudioToast('Downloaded SVG file');
            } catch (err) {
                console.error('Failed to download SVG:', err);
                showStudioToast('Failed to download SVG');
            }
        }

        function openVectorizeSvgModal(svgContent, filename = 'vectorized.svg', metaText = 'SVG Vectorizer • Detailed') {
            if (!svgContent) {
                showStudioToast('No SVG markup available');
                return;
            }

            // Normalize SVG markup vs Data URL vs Image URL
            let rawSvg = '';
            let dataUrl = '';

            if (typeof svgContent === 'string') {
                const trimmed = svgContent.trim();
                if (trimmed.startsWith('data:image/svg+xml')) {
                    dataUrl = trimmed;
                    try {
                        const commaIdx = trimmed.indexOf(',');
                        const payload = trimmed.substring(commaIdx + 1);
                        rawSvg = trimmed.includes(';base64') ? atob(payload) : decodeURIComponent(payload);
                    } catch (e) {
                        console.warn('Failed to decode data:image/svg+xml payload:', e);
                        rawSvg = trimmed;
                    }
                } else if (trimmed.startsWith('<svg') || trimmed.includes('<svg')) {
                    rawSvg = trimmed;
                    try {
                        dataUrl = 'data:image/svg+xml;utf8,' + encodeURIComponent(trimmed);
                    } catch (e) {
                        dataUrl = '';
                    }
                } else if (trimmed.startsWith('http://') || trimmed.startsWith('https://') || trimmed.startsWith('data:image/')) {
                    dataUrl = trimmed;
                    rawSvg = `<!-- Scalable Vector Graphic Reference -->\n<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024" width="100%" height="100%">\n  <image href="${trimmed}" width="100%" height="100%" preserveAspectRatio="xMidYMid meet" />\n</svg>`;
                } else {
                    rawSvg = trimmed;
                }
            }

            const exportContent = rawSvg || svgContent;
            currentVectorizeSvgData = {
                content: exportContent,
                dataUrl: dataUrl,
                filename: filename || 'vectorized.svg',
                meta: metaText || 'SVG Vectorizer • Detailed'
            };

            const modal = document.getElementById('vectorize-svg-code-modal');
            const metaEl = document.getElementById('vectorize-svg-code-meta');
            const containerEl = document.getElementById('vectorize-svg-render-container');
            const byteEl = document.getElementById('vectorize-svg-byte-count');
            const codeEl = document.getElementById('vectorize-svg-code-text');

            if (metaEl) metaEl.textContent = currentVectorizeSvgData.meta;
            if (codeEl) codeEl.textContent = exportContent;
            if (byteEl) {
                const bytes = new Blob([exportContent]).size;
                byteEl.textContent = `${bytes.toLocaleString()} bytes`;
            }
            if (containerEl) {
                containerEl.innerHTML = '';
                // Prefer clean visual rendering via SVG Data URI so the browser displays the visual graphic directly with crisp bezier curves and exact aspect ratio
                const previewUri = dataUrl || (rawSvg && rawSvg.includes('<svg') ? ('data:image/svg+xml;utf8,' + encodeURIComponent(rawSvg)) : '');
                if (previewUri) {
                    const img = document.createElement('img');
                    img.src = previewUri;
                    img.alt = 'Vector Graphic Visual Preview';
                    img.className = 'max-h-44 max-w-full w-auto h-auto object-contain drop-shadow-md rounded-lg m-auto block';
                    img.style.maxHeight = '170px';
                    img.style.maxWidth = '100%';
                    img.style.objectFit = 'contain';
                    containerEl.appendChild(img);
                } else if (rawSvg && rawSvg.includes('<svg')) {
                    containerEl.innerHTML = rawSvg;
                    const svgEl = containerEl.querySelector('svg');
                    if (svgEl) {
                        svgEl.style.maxHeight = '170px';
                        svgEl.style.maxWidth = '100%';
                        svgEl.style.display = 'block';
                        svgEl.style.margin = 'auto';
                        svgEl.classList.add('drop-shadow-md');
                    }
                } else {
                    containerEl.innerHTML = `<span class="text-xs text-neutral-400 font-mono">Vector preview ready</span>`;
                }
            }

            if (modal) {
                modal.classList.remove('hidden', 'pointer-events-none');
                modal.classList.add('flex', 'pointer-events-auto');
                modal.style.display = 'flex';
                modal.style.pointerEvents = 'auto';
                modal.style.visibility = 'visible';
                modal.style.opacity = '1';
            }
        }

        function closeVectorizeSvgModal() {
            const modal = document.getElementById('vectorize-svg-code-modal');
            if (modal) {
                modal.classList.add('hidden', 'pointer-events-none');
                modal.classList.remove('flex', 'pointer-events-auto');
                modal.style.display = 'none';
                modal.style.pointerEvents = 'none';
                modal.style.visibility = 'hidden';
            }
        }

        // SVG Modal Event Wireup
        document.addEventListener('DOMContentLoaded', () => {
            const svgModalEl = document.getElementById('vectorize-svg-code-modal');
            const svgModalCloseBtn = document.getElementById('vectorize-close-svg-modal');
            const svgModalCopyBtn = document.getElementById('vectorize-copy-svg-btn');
            const svgModalDownloadBtn = document.getElementById('vectorize-download-svg-btn');

            if (svgModalCloseBtn) svgModalCloseBtn.addEventListener('click', closeVectorizeSvgModal);
            if (svgModalEl) {
                svgModalEl.addEventListener('click', (e) => {
                    if (e.target === svgModalEl) closeVectorizeSvgModal();
                });
            }
            if (svgModalCopyBtn) {
                svgModalCopyBtn.addEventListener('click', () => {
                    if (currentVectorizeSvgData.content) {
                        navigator.clipboard.writeText(currentVectorizeSvgData.content).then(() => {
                            const textSpan = document.getElementById('vectorize-copy-svg-text');
                            if (textSpan) {
                                const orig = textSpan.textContent;
                                textSpan.textContent = 'Copied!';
                                setTimeout(() => { textSpan.textContent = orig; }, 1800);
                            }
                            showStudioToast('SVG code copied to clipboard');
                        }).catch(() => {
                            showStudioToast('Failed to copy SVG code');
                        });
                    }
                });
            }
            if (svgModalDownloadBtn) {
                svgModalDownloadBtn.addEventListener('click', () => {
                    if (currentVectorizeSvgData.content) {
                        triggerSvgDownload(currentVectorizeSvgData.content, currentVectorizeSvgData.filename);
                    }
                });
            }

            window.addEventListener('keydown', (e) => {
                if (e.key === 'Escape') {
                    const m = document.getElementById('vectorize-svg-code-modal');
                    if (m && !m.classList.contains('hidden')) {
                        closeVectorizeSvgModal();
                    }
                }
            });
        });

