        // ═══════════════════════════════════════════════════════════════════
        // IDEOGRAM-STYLE DESIGN TEMPLATES & STYLES (MASONRY & WORKFLOW ROUTING)
        // ═══════════════════════════════════════════════════════════════════
        let activeTemplateCategory = 'All';
        let activeTemplateSearchQuery = '';
        let isDesignTemplatesInitialized = false;

        
        // Silent download helper
        function triggerSilentTemplateDownload(imgUrl, title) {
            if (!imgUrl) return;
            const cleanTitle = (title || 'template').toLowerCase().replace(/[^a-z0-9_-]+/g, '-');
            const a = document.createElement('a');
            a.href = imgUrl;
            a.download = `${cleanTitle}.jpg`;
            a.target = '_blank';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
        }

        // White-Theme Template Preview Modal Logic
        let activePreviewModalTemplate = null;
        window.selectedTemplate = null;

        window.activeMobileTemplate = null;

        function openMobileTemplateCardModal(tmpl) {
            const modal = document.getElementById('mobile-template-card-modal');
            if (!modal || !tmpl) return;
            window.activeMobileTemplate = tmpl;

            if (typeof setIsMobileDrawerOpen === 'function') {
                setIsMobileDrawerOpen(false);
            }
            if (typeof closeMobileWorkspaceDrawer === 'function') {
                closeMobileWorkspaceDrawer();
            }

            const imgEl = document.getElementById('mobile-tmpl-card-img');
            const fallbackEl = document.getElementById('mobile-tmpl-card-fallback');
            const fallbackTitleEl = document.getElementById('mobile-tmpl-card-fallback-title');
            const titleEl = document.getElementById('mobile-tmpl-card-title');
            const promptEl = document.getElementById('mobile-tmpl-card-prompt-text');
            const ctaBtn = document.getElementById('mobile-tmpl-card-cta-btn');
            const ctaText = document.getElementById('mobile-tmpl-card-cta-text');
            const dlBtn = document.getElementById('mobile-tmpl-card-download-btn');
            const copyBtn = document.getElementById('mobile-tmpl-card-copy-btn');

            const title = tmpl.title || 'Template';
            const imgUrl = tmpl.imageUrl || tmpl.img || '';
            const promptText = tmpl.prompt || '';
            const isPreciseEdit = tmpl.targetWorkflow === 'precise-edit';

            if (titleEl) titleEl.textContent = title;
            if (fallbackTitleEl) fallbackTitleEl.textContent = title;
            if (promptEl) promptEl.textContent = promptText;
            if (ctaText) ctaText.textContent = isPreciseEdit ? 'Try with Photo' : 'Use Prompt';

            if (imgEl) {
                imgEl.style.display = 'block';
                if (fallbackEl) fallbackEl.classList.add('hidden');
                imgEl.onload = () => {
                    imgEl.style.display = 'block';
                    if (fallbackEl) fallbackEl.classList.add('hidden');
                };
                imgEl.onerror = function () {
                    if (!this.dataset.triedPublic && imgUrl && !this.src.includes('/public/')) {
                        this.dataset.triedPublic = '1';
                        this.src = '/public' + (imgUrl.startsWith('/') ? imgUrl : '/' + imgUrl);
                    } else {
                        this.style.display = 'none';
                        if (fallbackEl) fallbackEl.classList.remove('hidden');
                    }
                };
                imgEl.dataset.triedPublic = '';
                imgEl.src = imgUrl;
            }

            // Copy handler (inline feedback, zero toasts)
            if (copyBtn) {
                copyBtn.onclick = (e) => {
                    e.stopPropagation();
                    navigator.clipboard.writeText(promptText).then(() => {
                        const copyIcon = copyBtn.querySelector('.copy-icon');
                        const checkIcon = copyBtn.querySelector('.check-icon');
                        const copyLabel = copyBtn.querySelector('.copy-label');
                        if (copyIcon && checkIcon) {
                            copyIcon.classList.add('hidden');
                            checkIcon.classList.remove('hidden');
                            if (copyLabel) copyLabel.textContent = 'Copied!';
                            setTimeout(() => {
                                copyIcon.classList.remove('hidden');
                                checkIcon.classList.add('hidden');
                                if (copyLabel) copyLabel.textContent = 'Copy';
                            }, 1800);
                        }
                    }).catch(() => {});
                };
            }

            // CTA button: Use Prompt
            if (ctaBtn) {
                ctaBtn.onclick = (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    closeMobileTemplateCardModal();

                    const targetTool = isPreciseEdit ? 'precise-edit' : 'generate-image';
                    if (typeof openMobileWorkspaceDrawer === 'function') {
                        openMobileWorkspaceDrawer(targetTool, {
                            prompt: promptText,
                            aspectRatio: tmpl.aspectRatio,
                            stylePreset: tmpl.stylePreset
                        });
                    }

                    const genInput = document.getElementById('mobile-gen-prompt-input');
                    if (genInput) {
                        genInput.value = promptText;
                        genInput.dispatchEvent(new Event('input', { bubbles: true }));
                    }
                    const homeInput = document.getElementById('image-home-prompt-input');
                    if (homeInput) {
                        homeInput.value = promptText;
                        homeInput.dispatchEvent(new Event('input', { bubbles: true }));
                    }
                    if (tmpl.stylePreset && typeof selectMobileStylePreset === 'function') {
                        selectMobileStylePreset(tmpl.stylePreset);
                    }
                };
            }

            // Download button
            if (dlBtn) {
                dlBtn.onclick = (e) => {
                    e.stopPropagation();
                    if (typeof triggerSilentTemplateDownload === 'function') {
                        triggerSilentTemplateDownload(imgUrl, title);
                    }
                };
            }

            modal.classList.remove('hidden');
        }
        window.openMobileTemplateCardModal = openMobileTemplateCardModal;

        function closeMobileTemplateCardModal() {
            const modal = document.getElementById('mobile-template-card-modal');
            if (modal) modal.classList.add('hidden');
            window.activeMobileTemplate = null;
        }
        window.closeMobileTemplateCardModal = closeMobileTemplateCardModal;

        function setSelectedTemplate(tmpl) {
            window.selectedTemplate = tmpl || null;
            const isMobile = typeof window !== 'undefined' && window.innerWidth < 768;
            if (tmpl) {
                if (isMobile && !tmpl.isFeedResult && !tmpl.isResultItem && typeof openMobileTemplateCardModal === 'function') {
                    openMobileTemplateCardModal(tmpl);
                } else {
                    openTemplateWhitePreviewModal(tmpl);
                }
            } else {
                if (typeof closeMobileTemplateCardModal === 'function') {
                    closeMobileTemplateCardModal();
                }
                closeTemplateWhitePreviewModal();
            }
        }
        window.setSelectedTemplate = setSelectedTemplate;

        let activePreviewModalImageUrl = '';
        let activePreviewModalBatchImages = [];
        let activePreviewModalBatchIndex = 0;

        function openTemplateWhitePreviewModal(tmpl, onPreciseEdit, onGenerate) {
            const isMobile = typeof window !== 'undefined' && window.innerWidth < 768;
            if (isMobile && !tmpl.isFeedResult && !tmpl.isResultItem && typeof openMobileTemplateCardModal === 'function') {
                openMobileTemplateCardModal(tmpl);
                return;
            }

            const modal = document.getElementById('template-white-preview-modal');
            if (!modal) return;
            activePreviewModalTemplate = tmpl;
            window.selectedTemplate = tmpl;

            // Ensure floating bottom sheet drawer is closed whenever template preview opens
            if (typeof setIsMobileDrawerOpen === 'function') {
                setIsMobileDrawerOpen(false);
            }

            const modalImg = document.getElementById('tmpl-modal-img');
            const modalFallback = document.getElementById('tmpl-modal-fallback');
            const modalFallbackTitle = document.getElementById('tmpl-modal-fallback-title');
            const promptTextEl = document.getElementById('tmpl-modal-prompt-text');
            const ctaBtn = document.getElementById('tmpl-modal-cta-btn');
            const ctaText = document.getElementById('tmpl-modal-cta-text');
            const downloadBtn = document.getElementById('tmpl-modal-download-btn');
            const copyBtn = document.getElementById('tmpl-modal-copy-prompt-btn');
            const modalTitleEl = document.getElementById('tmpl-modal-title');
            const promptSection = document.getElementById('tmpl-modal-prompt-section');
            const scaleSection = document.getElementById('tmpl-modal-scale-section');
            const scaleBadge = document.getElementById('tmpl-modal-scale-badge');
            const rembgSection = document.getElementById('tmpl-modal-rembg-section');
            const feedActions = document.getElementById('tmpl-modal-feed-actions');
            const editBtn = document.getElementById('tmpl-modal-edit-btn');
            const upscaleBtn = document.getElementById('tmpl-modal-upscale-btn');
            const prevBtn = document.getElementById('tmpl-modal-prev-btn');
            const nextBtn = document.getElementById('tmpl-modal-next-btn');

            const isPreciseEdit = tmpl.targetWorkflow === 'precise-edit';
            const imgUrl = tmpl.imageUrl || tmpl.img || '';
            const promptText = tmpl.prompt || '';
            const title = tmpl.title || 'Template';

            activePreviewModalImageUrl = imgUrl;

            // Resolve Batch Images
            const rawBatch = (tmpl.images || tmpl.batchImages || (tmpl.originalItem && (tmpl.originalItem.images || tmpl.originalItem.batchImages || tmpl.originalItem.outputs)) || []);
            let resolvedBatch = [];
            if (Array.isArray(rawBatch) && rawBatch.length > 0) {
                resolvedBatch = rawBatch.map(e => (typeof e === 'string' ? e : (e?.url || e?.img || e?.src || ''))).filter(Boolean);
            }
            if (resolvedBatch.length === 0 && imgUrl) {
                resolvedBatch = [imgUrl];
            }
            activePreviewModalBatchImages = resolvedBatch;
            const initIdx = resolvedBatch.findIndex(u => u === imgUrl);
            activePreviewModalBatchIndex = initIdx >= 0 ? initIdx : 0;

            function applyActivePreviewImage(url) {
                if (!url) return;
                activePreviewModalImageUrl = url;
                if (modalImg) {
                    modalImg.style.display = 'block';
                    if (modalFallback) modalFallback.classList.add('hidden');
                    modalImg.src = url;
                }
            }

            // Wire Navigation Arrows (< and >) for multi-image batches
            const hasMultipleImages = isMobile && resolvedBatch.length > 1;
            if (prevBtn && nextBtn) {
                if (hasMultipleImages) {
                    prevBtn.classList.remove('hidden');
                    nextBtn.classList.remove('hidden');
                    prevBtn.onclick = (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        activePreviewModalBatchIndex = (activePreviewModalBatchIndex - 1 + activePreviewModalBatchImages.length) % activePreviewModalBatchImages.length;
                        applyActivePreviewImage(activePreviewModalBatchImages[activePreviewModalBatchIndex]);
                    };
                    nextBtn.onclick = (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        activePreviewModalBatchIndex = (activePreviewModalBatchIndex + 1) % activePreviewModalBatchImages.length;
                        applyActivePreviewImage(activePreviewModalBatchImages[activePreviewModalBatchIndex]);
                    };
                } else {
                    prevBtn.classList.add('hidden');
                    nextBtn.classList.add('hidden');
                }
            }

            if (modalFallbackTitle) modalFallbackTitle.textContent = title;
            if (promptTextEl) promptTextEl.textContent = promptText;

            // Image loading with graceful fallback and /public resolution
            if (modalImg) {
                modalImg.style.display = 'block';
                if (modalFallback) modalFallback.classList.add('hidden');

                modalImg.onload = () => {
                    modalImg.style.display = 'block';
                    if (modalFallback) modalFallback.classList.add('hidden');
                };
                modalImg.onerror = function () {
                    const currentSrc = activePreviewModalImageUrl || imgUrl;
                    if (!this.dataset.triedPublic && currentSrc && !this.src.includes('/public/')) {
                        this.dataset.triedPublic = '1';
                        this.src = '/public' + (currentSrc.startsWith('/') ? currentSrc : '/' + currentSrc);
                    } else {
                        this.style.display = 'none';
                        if (modalFallback) modalFallback.classList.remove('hidden');
                    }
                };
                modalImg.dataset.triedPublic = '';
                modalImg.src = imgUrl;
            }

            // Copy prompt button (clean inline Copied! feedback, ZERO toasts)
            if (copyBtn) {
                copyBtn.onclick = (e) => {
                    e.stopPropagation();
                    navigator.clipboard.writeText(promptText).then(() => {
                        const copyIcon = copyBtn.querySelector('.copy-icon');
                        const checkIcon = copyBtn.querySelector('.check-icon');
                        const copyLabel = copyBtn.querySelector('.copy-label');
                        if (copyIcon && checkIcon) {
                            copyIcon.classList.add('hidden');
                            checkIcon.classList.remove('hidden');
                            if (copyLabel) copyLabel.textContent = 'Copied!';
                            setTimeout(() => {
                                copyIcon.classList.remove('hidden');
                                checkIcon.classList.add('hidden');
                                if (copyLabel) copyLabel.textContent = 'Copy';
                            }, 1800);
                        }
                    }).catch(() => {});
                };
            }

            // Context-Aware Tailoring by Workspace Type for Result Feed items
            if (tmpl.isFeedResult || tmpl.isResultItem) {
                // Rule: Remove "Use Prompt" / "Try with Photo" CTA button completely on feed results
                if (ctaBtn) ctaBtn.classList.add('hidden');

                // Reveal Two-Tier Feed Actions: Edit + Upscale side-by-side directly above Download
                if (feedActions) feedActions.classList.remove('hidden');

                // Wire Edit button
                if (editBtn) {
                    editBtn.onclick = (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        const curUrl = activePreviewModalImageUrl || imgUrl;
                        const srcItem = { ...(tmpl.originalItem || tmpl), url: curUrl, img: curUrl };
                        closeTemplateWhitePreviewModal();
                        const setEdit = (typeof setMobilePreciseEditSource === 'function')
                            ? setMobilePreciseEditSource
                            : (typeof window !== 'undefined' ? window.setMobilePreciseEditSource : null);
                        if (setEdit) setEdit(srcItem);
                        const openDrawer = (typeof openMobileWorkspaceDrawer === 'function')
                            ? openMobileWorkspaceDrawer
                            : (typeof window !== 'undefined' ? window.openMobileWorkspaceDrawer : null);
                        if (openDrawer) openDrawer('precise-edit');
                    };
                }

                // Wire Upscale button
                if (upscaleBtn) {
                    upscaleBtn.onclick = (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        const curUrl = activePreviewModalImageUrl || imgUrl;
                        const srcItem = { ...(tmpl.originalItem || tmpl), url: curUrl, img: curUrl };
                        closeTemplateWhitePreviewModal();
                        const setUpscale = (typeof setMobileUpscaleSource === 'function')
                            ? setMobileUpscaleSource
                            : (typeof window !== 'undefined' ? window.setMobileUpscaleSource : null);
                        if (setUpscale) setUpscale(srcItem);
                        const openDrawer = (typeof openMobileWorkspaceDrawer === 'function')
                            ? openMobileWorkspaceDrawer
                            : (typeof window !== 'undefined' ? window.openMobileWorkspaceDrawer : null);
                        if (openDrawer) openDrawer('upscale-image');
                    };
                }

                // Single Full-Width Download Button directly below Edit & Upscale
                if (downloadBtn) {
                    downloadBtn.className = 'w-full h-11 px-5 rounded-xl bg-neutral-900 hover:bg-black text-white text-sm font-semibold flex items-center justify-center cursor-pointer shadow-sm active:scale-[0.99] transition-all';
                    downloadBtn.innerHTML = 'Download';
                    downloadBtn.onclick = (e) => {
                        e.stopPropagation();
                        const curUrl = activePreviewModalImageUrl || imgUrl;
                        const dlTitle = tmpl.title || 'image';
                        const dlName = dlTitle.toLowerCase().replace(/\s+/g, '-') + '-' + Date.now() + '.png';
                        triggerSilentTemplateDownload(curUrl, dlName);
                    };
                }

                const ws = tmpl.workspaceType || (tmpl.isRemoveBg ? 'remove-background' : (tmpl.isUpscale ? 'upscale-image' : (tmpl.isPreciseEdit ? 'precise-edit' : 'generate-image')));

                if (ws === 'generate-image') {
                    // 1. Generate Image: Top Heading "Generate Image" + Prompt Section + Dual-Row Actions
                    if (modalTitleEl) {
                        modalTitleEl.textContent = 'Generate Image';
                        modalTitleEl.classList.remove('hidden');
                    }
                    if (promptSection) promptSection.classList.remove('hidden');
                    if (scaleSection) scaleSection.classList.add('hidden');
                    if (rembgSection) rembgSection.classList.add('hidden');
                } else if (ws === 'precise-edit') {
                    // 2. Precise Edit: Top Heading "Precise Edit" + Prompt Section + Dual-Row Actions
                    if (modalTitleEl) {
                        modalTitleEl.textContent = 'Precise Edit';
                        modalTitleEl.classList.remove('hidden');
                    }
                    if (promptSection) promptSection.classList.remove('hidden');
                    if (scaleSection) scaleSection.classList.add('hidden');
                    if (rembgSection) rembgSection.classList.add('hidden');
                } else if (ws === 'upscale-image') {
                    // 3. Upscale Image: Top Heading "Upscale Image" + Scale Section ONLY (No prompt) + Dual-Row Actions
                    if (modalTitleEl) {
                        modalTitleEl.textContent = 'Upscale Image';
                        modalTitleEl.classList.remove('hidden');
                    }
                    if (promptSection) promptSection.classList.add('hidden');
                    if (scaleSection) {
                        scaleSection.classList.remove('hidden');
                        if (scaleBadge) {
                            const sc = (tmpl.scale || '4×').replace(/x/i, '×');
                            scaleBadge.textContent = sc;
                        }
                    }
                    if (rembgSection) rembgSection.classList.add('hidden');
                } else if (ws === 'remove-background') {
                    // 4. Remove Background: Top Heading "Remove Background" + "Background: Transparent" Badge + Dual-Row Actions
                    if (modalTitleEl) {
                        modalTitleEl.textContent = 'Remove Background';
                        modalTitleEl.classList.remove('hidden');
                    }
                    if (promptSection) promptSection.classList.add('hidden');
                    if (scaleSection) scaleSection.classList.add('hidden');
                    if (rembgSection) rembgSection.classList.remove('hidden');
                }
            } else {
                // Regular Landing Page Template Preview (Desktop): Hide Two-Tier Feed Actions, Restore Standard Template Details & Dual Buttons
                if (feedActions) feedActions.classList.add('hidden');
                if (prevBtn) prevBtn.classList.add('hidden');
                if (nextBtn) nextBtn.classList.add('hidden');

                if (modalTitleEl) {
                    modalTitleEl.textContent = title;
                    modalTitleEl.classList.remove('hidden');
                }
                if (promptSection) promptSection.classList.remove('hidden');
                if (scaleSection) scaleSection.classList.add('hidden');
                if (rembgSection) rembgSection.classList.add('hidden');

                if (ctaBtn) {
                    ctaBtn.classList.remove('hidden');
                    if (ctaText) ctaText.textContent = isPreciseEdit ? 'Try with Photo' : 'Use Prompt';
                    ctaBtn.onclick = (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        closeTemplateWhitePreviewModal();

                        const targetTool = isPreciseEdit ? 'precise-edit' : 'generate-image';

                        if (isMobile) {
                            if (typeof openMobileWorkspaceDrawer === 'function') {
                                openMobileWorkspaceDrawer(targetTool, {
                                    prompt: promptText,
                                    aspectRatio: tmpl.aspectRatio,
                                    stylePreset: tmpl.stylePreset
                                });
                            }
                            return;
                        }

                        // Desktop
                        if (isPreciseEdit) {
                            if (typeof onPreciseEdit === 'function') onPreciseEdit();
                            else if (typeof setImageStudioMode === 'function') setImageStudioMode('workspace', { tool: 'precise-edit' });
                        } else {
                            if (typeof onGenerate === 'function') onGenerate();
                            else if (typeof setImageStudioMode === 'function') setImageStudioMode('workspace', { tool: 'generate' });
                        }
                    };
                }

                if (downloadBtn) {
                    downloadBtn.className = 'h-10 px-4 rounded-lg border border-neutral-200 hover:bg-neutral-100 text-neutral-800 text-sm font-medium inline-flex items-center justify-center gap-2 shrink-0 transition-all cursor-pointer';
                    downloadBtn.innerHTML = '<svg class="w-4 h-4 text-neutral-600" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg><span>Download</span>';
                    downloadBtn.onclick = (e) => {
                        e.stopPropagation();
                        triggerSilentTemplateDownload(imgUrl, title);
                    };
                }
            }

            modal.classList.remove('hidden');
        }

        function closeTemplateWhitePreviewModal() {
            const modal = document.getElementById('template-white-preview-modal');
            if (modal) modal.classList.add('hidden');
            activePreviewModalTemplate = null;
            activePreviewModalImageUrl = '';
            activePreviewModalBatchImages = [];
            activePreviewModalBatchIndex = 0;
            window.selectedTemplate = null;

            if (typeof closeMobileTemplateCardModal === 'function') {
                closeMobileTemplateCardModal();
            }

            // Reset modal sections to default
            document.getElementById('tmpl-modal-feed-actions')?.classList.add('hidden');
            document.getElementById('tmpl-modal-prev-btn')?.classList.add('hidden');
            document.getElementById('tmpl-modal-next-btn')?.classList.add('hidden');
            document.getElementById('tmpl-modal-title')?.classList.remove('hidden');
            document.getElementById('tmpl-modal-prompt-section')?.classList.remove('hidden');
            document.getElementById('tmpl-modal-scale-section')?.classList.add('hidden');
            document.getElementById('tmpl-modal-rembg-section')?.classList.add('hidden');
            document.getElementById('tmpl-modal-cta-btn')?.classList.remove('hidden');
            const downloadBtn = document.getElementById('tmpl-modal-download-btn');
            if (downloadBtn) {
                downloadBtn.className = 'h-10 px-4 rounded-lg border border-neutral-200 hover:bg-neutral-100 text-neutral-800 text-sm font-medium inline-flex items-center justify-center gap-2 shrink-0 transition-all cursor-pointer';
                downloadBtn.innerHTML = '<svg class="w-4 h-4 text-neutral-600" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg><span>Download</span>';
            }
        }

        function renderImageHomeTemplates() {
            const grid = document.getElementById('image-home-templates-grid');
            const emptyState = document.getElementById('tmpl-empty-state');
            if (!grid) return;

            grid.innerHTML = '';

            const data = (typeof getAllDesignTemplates === 'function')
                ? getAllDesignTemplates()
                : (Array.isArray(BASE_DESIGN_TEMPLATES) ? BASE_DESIGN_TEMPLATES : []);
            const allTemplates = Array.isArray(data) ? data : (Array.isArray(data?.templates) ? data.templates : (Array.isArray(data?.data) ? data.data : []));

            const query = (activeTemplateSearchQuery || '').toLowerCase().trim();

            const filteredTemplates = allTemplates.filter((tmpl) => {
                if (activeTemplateCategory && activeTemplateCategory !== 'All') {
                    if (tmpl.category !== activeTemplateCategory) {
                        return false;
                    }
                }
                if (query) {
                    const matchTitle = (tmpl.title || '').toLowerCase().includes(query);
                    const matchPrompt = (tmpl.prompt || '').toLowerCase().includes(query);
                    const matchStyle = (tmpl.stylePreset || '').toLowerCase().includes(query);
                    if (!matchTitle && !matchPrompt && !matchStyle) {
                        return false;
                    }
                }
                return true;
            });

            if (filteredTemplates.length === 0) {
                if (emptyState) emptyState.classList.remove('hidden');
                grid.classList.add('hidden');
                return;
            } else {
                if (emptyState) emptyState.classList.add('hidden');
                grid.classList.remove('hidden');
            }

            filteredTemplates.forEach((tmpl) => {
                const card = document.createElement('div');
                const ratioStr = tmpl.aspectRatio || '1:1';
                const ratioCss = ratioStr.replace(':', '/');

                // Ideogram-Style Multi-Aspect Masonry Card
                card.className = "group relative rounded-md overflow-hidden break-inside-avoid mb-1 bg-neutral-100 dark:bg-neutral-900 border border-neutral-200/60 dark:border-white/5 shadow-2xs hover:shadow-md transition-all duration-300 cursor-pointer select-none";
                card.style.aspectRatio = ratioCss;

                const title = tmpl.title || 'Template';
                const displayTitle = escapeHtml(title);
                const promptText = tmpl.prompt || '';
                const displayPrompt = escapeHtml(promptText);
                const imgUrl = tmpl.imageUrl || tmpl.img || '';
                const isPreciseEdit = tmpl.targetWorkflow === 'precise-edit';

                // Ideogram Natural Multi-Aspect Card:
                // Normal: 100% clean unobstructed artwork (zero permanent scrim / zero permanent text)
                // Hover: Subtle image zoom (scale 1.03) + bottom dark gradient & title appear seamlessly
                // Click: Opens #template-white-preview-modal
                card.innerHTML = `
                    <div class="relative w-full h-full bg-neutral-100 dark:bg-neutral-800 flex items-center justify-center overflow-hidden">
                        <!-- Clean subtle neutral placeholder that shows if local image is not yet placed -->
                        <div class="tmpl-card-placeholder absolute inset-0 flex flex-col items-center justify-center p-3 text-neutral-400 dark:text-neutral-500 bg-neutral-100 dark:bg-neutral-800 select-none">
                            <svg class="w-6 h-6 mb-1.5 opacity-40 text-neutral-500" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
                                <rect width="18" height="18" x="3" y="3" rx="2" ry="2"/>
                                <circle cx="9" cy="9" r="2"/>
                                <path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/>
                            </svg>
                            <span class="text-[11px] font-medium text-neutral-500 dark:text-neutral-400 text-center line-clamp-1 px-2">${displayTitle}</span>
                        </div>
                        <!-- Template image with clean subtle hover zoom (scale 1.03) -->
                        ${imgUrl ? `
                        <img src="${imgUrl}"
                             alt="${displayTitle}"
                             loading="lazy"
                             class="absolute inset-0 w-full h-full object-cover block group-hover:scale-[1.03] transition-transform duration-300 z-[1]"
                             onload="this.previousElementSibling?.classList.add('hidden');"
                             onerror="this.style.display='none';" />
                        ` : ''}
                    </div>

                    <!-- Ideogram Hover-Only Scrim & Title Overlay (100% clean unobstructed artwork by default) -->
                    <div class="pointer-events-none absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-200 z-[2]">
                        <div class="absolute inset-x-0 bottom-0 h-20 bg-gradient-to-t from-black/80 via-black/35 to-transparent"></div>
                        <div class="absolute bottom-2.5 left-3 right-3 z-[3]">
                            <span class="text-white text-[12.5px] font-semibold leading-snug tracking-tight drop-shadow-[0_1px_2px_rgba(0,0,0,0.85)] line-clamp-1">${displayTitle}</span>
                        </div>
                    </div>
                `;

                // Smart Workflow Routing Handlers
                // STATIC UPLOAD BOX: Completely steady and static dropzone without any pulsing or border animation
                const executePreciseEdit = () => {
                    setImageStudioMode('workspace', { tool: 'precise-edit' });
                    if (typeof studioPreciseEditState !== 'undefined') {
                        studioPreciseEditState.sourceItem = null;
                    }
                    const dropzone = document.getElementById("studio-precise-edit-dropzone");
                    const previewWrap = document.getElementById("studio-precise-edit-preview-wrap");
                    if (dropzone) dropzone.classList.remove("hidden");
                    if (previewWrap) previewWrap.classList.add("hidden");
                    if (typeof updatePreciseEditButtonState === 'function') updatePreciseEditButtonState();

                    const editInput = document.getElementById("studio-precise-edit-input");
                    if (editInput) {
                        editInput.value = promptText;
                        editInput.dispatchEvent(new Event('input', { bubbles: true }));
                    }

                    if (dropzone) {
                        // Steady scroll, zero pulse / ring / blinking
                        dropzone.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    }
                    showStudioToast('Loaded into Precise Edit — upload photo to begin');
                };

                const executeGenerate = () => {
                    setImageStudioMode('workspace', {
                        tool: 'generate-image',
                        prompt: promptText,
                        aspectRatio: tmpl.aspectRatio,
                        stylePreset: tmpl.stylePreset
                    });

                    // Pre-fill prompt input
                    const studioPrompt = document.getElementById('studio-prompt-input');
                    if (studioPrompt) {
                        studioPrompt.value = promptText;
                        studioPrompt.dispatchEvent(new Event('input', { bubbles: true }));
                        setTimeout(() => studioPrompt.focus(), 60);
                    }

                    // Pre-fill style preset in ideogram-style-tags
                    if (tmpl.stylePreset) {
                        if (typeof syncStudioStylePills === 'function') {
                            syncStudioStylePills(tmpl.stylePreset);
                        }
                        if (typeof imageStudioState !== 'undefined') {
                            imageStudioState.activeStyle = tmpl.stylePreset;
                        }
                    }

                    showStudioToast(`Loaded "${title}" template`);
                };

                // CLICKING THE CARD OPENS THE WHITE-THEME PREVIEW MODAL
                // (All overlay buttons btn-tmpl-download, btn-tmpl-copy, btn-tmpl-primary removed for distraction-free aesthetic)
                card.addEventListener('click', () => {
                    openTemplateWhitePreviewModal(tmpl, executePreciseEdit, executeGenerate);
                });

                grid.appendChild(card);
            });

            if (typeof renderMobileImageHomeTemplates === 'function') {
                renderMobileImageHomeTemplates();
            }
        }


        function initDesignTemplatesSection() {
            if (isDesignTemplatesInitialized) return;
            isDesignTemplatesInitialized = true;

            // 1. Ideogram-style boxy category filter tabs
            const pills = document.querySelectorAll('#tmpl-category-filter-bar .tmpl-filter-pill');
            pills.forEach((pill) => {
                pill.addEventListener('click', () => {
                    const cat = pill.getAttribute('data-category') || 'All';
                    activeTemplateCategory = cat;

                    pills.forEach((p) => {
                        p.classList.remove('active', 'bg-slate-900/[0.08]', 'text-neutral-900', 'dark:bg-white/10', 'dark:text-white', 'font-medium');
                        p.classList.add('text-neutral-500', 'hover:text-neutral-900', 'hover:bg-slate-900/[0.04]', 'dark:text-neutral-400', 'dark:hover:text-white', 'dark:hover:bg-white/5', 'font-normal');
                    });

                    pill.classList.add('active', 'bg-slate-900/[0.08]', 'text-neutral-900', 'dark:bg-white/10', 'dark:text-white', 'font-medium');
                    pill.classList.remove('text-neutral-500', 'hover:text-neutral-900', 'hover:bg-slate-900/[0.04]', 'dark:text-neutral-400', 'dark:hover:text-white', 'dark:hover:bg-white/5', 'font-normal');

                    renderImageHomeTemplates();
                });
            });

            // 2. Compact Search Input (if present)
            const searchInput = document.getElementById('tmpl-search-input');
            const searchClear = document.getElementById('tmpl-search-clear');
            if (searchInput) {
                searchInput.addEventListener('input', () => {
                    activeTemplateSearchQuery = searchInput.value || '';
                    if (searchClear) {
                        searchClear.classList.toggle('hidden', activeTemplateSearchQuery.length === 0);
                    }
                    renderImageHomeTemplates();
                });
            }

            if (searchClear && searchInput) {
                searchClear.addEventListener('click', () => {
                    searchInput.value = '';
                    activeTemplateSearchQuery = '';
                    searchClear.classList.add('hidden');
                    searchInput.focus();
                    renderImageHomeTemplates();
                });
            }

            // 3. Reset filters button in empty state
            const resetBtn = document.getElementById('tmpl-reset-filters-btn');
            if (resetBtn) {
                resetBtn.addEventListener('click', () => {
                    activeTemplateCategory = 'All';
                    activeTemplateSearchQuery = '';
                    if (searchInput) searchInput.value = '';
                    if (searchClear) searchClear.classList.add('hidden');

                    pills.forEach((p) => {
                        const isAll = (p.getAttribute('data-category') || '') === 'All';
                        if (isAll) {
                            p.classList.add('active', 'bg-slate-900/[0.08]', 'text-neutral-900', 'dark:bg-white/10', 'dark:text-white', 'font-medium');
                            p.classList.remove('text-neutral-500', 'hover:text-neutral-900', 'hover:bg-slate-900/[0.04]', 'dark:text-neutral-400', 'dark:hover:text-white', 'dark:hover:bg-white/5', 'font-normal');
                        } else {
                            p.classList.remove('active', 'bg-slate-900/[0.08]', 'text-neutral-900', 'dark:bg-white/10', 'dark:text-white', 'font-medium');
                            p.classList.add('text-neutral-500', 'hover:text-neutral-900', 'hover:bg-slate-900/[0.04]', 'dark:text-neutral-400', 'dark:hover:text-white', 'dark:hover:bg-white/5', 'font-normal');
                        }
                    });

                    renderImageHomeTemplates();
                });
            }

            // 4. Live event synchronization for dynamic admin templates
            window.addEventListener('mestrio-templates-updated', () => {
                if (typeof renderImageHomeTemplates === 'function') renderImageHomeTemplates();
                if (typeof renderMobileImageHomeTemplates === 'function') renderMobileImageHomeTemplates();
            });

            // Initial render
            renderImageHomeTemplates();
        }

        function setImageStudioMode(mode, options = {}) {
            imageStudioMode = mode || 'home';
            if (imageStudioMode === 'home' && !options.skipUrlSync && isVectorizePath(window.location.pathname)) {
                syncRoute('/', { mode: 'home', workspace: 'image-studio' });
            }
            const homeView = document.getElementById('image-home-view');
            const workspaceView = document.getElementById('image-studio-workspace');
            const heroSection = document.getElementById('hero-section');
            const headerBackBtn = document.getElementById('header-back-to-chat');
            const topNavHeader = document.getElementById('top-nav-header');

            if (typeof currentWorkspace !== 'undefined' && currentWorkspace !== 'image-studio') {
                console.log('[DEBUG TRACE setImageStudioMode stack]:', new Error().stack);
                currentWorkspace = 'image-studio';
                if (typeof updateSidebarNavActiveStates === 'function') {
                    updateSidebarNavActiveStates('image-studio');
                }
            }

            if (heroSection) heroSection.classList.add('hidden');
            if (headerBackBtn) { headerBackBtn.classList.add('hidden'); headerBackBtn.classList.remove('inline-flex'); }
            if (topNavHeader) topNavHeader.classList.add('hidden');
            const chatPlanHeader = document.getElementById('chat-free-plan-header');
            if (chatPlanHeader) {
                chatPlanHeader.classList.add('hidden');
                chatPlanHeader.style.display = 'none';
            }

            if (window.innerWidth < 768) {
                if (workspaceView) workspaceView.classList.add('hidden');
                if (imageStudioMode === 'home') {
                    document.body.classList.add('image-home-active');
                    if (homeView) {
                        homeView.classList.remove('hidden');
                        homeView.scrollTop = 0;
                    }
                    if (typeof setMobileWorkspaceView === 'function') {
                        setMobileWorkspaceView('landing');
                    }
                    if (typeof setIsMobileDrawerOpen === 'function') {
                        setIsMobileDrawerOpen(false);
                    }
                    renderImageHomeCreations();
                    renderImageHomeTemplates();
                    if (typeof renderMobileImageHomeTemplates === "function") renderMobileImageHomeTemplates();
                    return;
                } else {
                    // Mobile workspace mode: open dedicated Ideogram-style bottom sheet drawer or trigger auto-generate
                    const tool = (typeof normalizeToolName === 'function')
                        ? normalizeToolName(options.tool || 'generate-image')
                        : (options.tool || 'generate-image');
                    if (options.autoGenerate) {
                        if (typeof activeMobileTool !== 'undefined') activeMobileTool = tool;
                        if (typeof setMobileWorkspaceView === 'function') setMobileWorkspaceView('results');
                        if (typeof setIsMobileDrawerOpen === 'function') setIsMobileDrawerOpen(false);
                        if (options.prompt) {
                            const studioPrompt = document.getElementById('studio-prompt-input');
                            if (studioPrompt) studioPrompt.value = options.prompt;
                            imageStudioState.prompt = options.prompt;
                        }
                        if (typeof isMobileProcessing !== 'undefined') {
                            isMobileProcessing = true;
                            mobileProcessingStatus = 'Generating your image...';
                        }
                        if (typeof renderMobileResultFeed === 'function') renderMobileResultFeed();
                        setTimeout(() => {
                            generateStudioImages(options.prompt, options.aspectRatio, options.referenceImage);
                        }, 50);
                        return;
                    }

                    if (typeof openMobileWorkspaceDrawer === 'function') {
                        openMobileWorkspaceDrawer(tool, options);
                    }
                    return;
                }
            }

            if (imageStudioMode === 'home') {
                document.body.classList.add('image-home-active');
                if (workspaceView) workspaceView.classList.add('hidden');
                if (homeView) {
                    homeView.classList.remove('hidden');
                    homeView.scrollTop = 0;
                }
                renderImageHomeCreations();
                renderImageHomeTemplates();
                if (typeof renderMobileImageHomeTemplates === "function") renderMobileImageHomeTemplates();
                if (typeof startPlaceholderRotation === 'function') {
                    startPlaceholderRotation();
                }
                const homeInput = document.getElementById('image-home-prompt-input');
                // Stay unfocused/idle on page load without active blinking cursor
                if (options.focus && homeInput) {
                    setTimeout(() => homeInput.focus(), 80);
                }
            } else {
                // workspace mode
                document.body.classList.remove('image-home-active');
                if (typeof stopPlaceholderRotation === 'function') {
                    stopPlaceholderRotation();
                }
                if (homeView) homeView.classList.add('hidden');
                if (workspaceView) workspaceView.classList.remove('hidden');

                if (options.tool && typeof switchWorkflowTool === 'function') {
                    switchWorkflowTool(options.tool, options);
                }

                if (options.prompt) {
                    const studioPrompt = document.getElementById('studio-prompt-input');
                    if (studioPrompt) {
                        studioPrompt.value = options.prompt;
                        studioPrompt.dispatchEvent(new Event('input', { bubbles: true }));
                    }
                    imageStudioState.prompt = options.prompt;
                    imageStudioState.currentPrompt = options.prompt;
                }

                if (options.referenceImage) {
                    imageStudioState.referenceImages = [{
                        dataUrl: options.referenceImage,
                        name: options.referenceImageName || 'reference.png'
                    }];
                    imageStudioState.referenceImage = options.referenceImage;
                    if (typeof renderStudioReferenceSlots === 'function') renderStudioReferenceSlots();
                }

                if (options.model) {
                    imageStudioState.model = options.model;
                    const modelLabel = document.getElementById('ideogram-model-select-label');
                    const studioModelLabel = document.getElementById('studio-model-label');
                    const foundModel = IMAGE_MODELS.find(m => m.id === options.model);
                    const displayName = foundModel ? foundModel.name : (options.model === 'auto' ? 'Auto' : options.model);
                    if (modelLabel) modelLabel.textContent = displayName;
                    if (studioModelLabel) studioModelLabel.textContent = displayName;
                    if (typeof syncStudioModelDropdown === 'function') syncStudioModelDropdown(options.model);
                }

                if (options.count || options.imageCount) {
                    const c = parseInt(options.count || options.imageCount, 10) || 1;
                    imageStudioState.imageCount = c;
                    const countLabel = document.getElementById('studio-count-label');
                    if (countLabel) countLabel.textContent = String(c);
                    if (typeof syncStudioCountDropdown === 'function') syncStudioCountDropdown(c);
                    if (typeof syncCountGridSelection === 'function') syncCountGridSelection(c);
                }

                if (options.aspectRatio) {
                    imageStudioState.aspectRatio = options.aspectRatio;
                    const ratioLabel = document.getElementById('ideogram-ratio-select-label');
                    const studioRatioLabel = document.getElementById('studio-ratio-label');
                    const studioRatioIcon = document.getElementById('studio-ratio-icon');
                    const displayRatio = options.aspectRatio === 'auto' ? 'Auto' : options.aspectRatio;
                    if (ratioLabel) ratioLabel.textContent = displayRatio;
                    if (studioRatioLabel) studioRatioLabel.textContent = displayRatio;
                    if (studioRatioIcon && typeof getStudioRatioWireframeHtml === 'function') {
                        studioRatioIcon.innerHTML = getStudioRatioWireframeHtml(options.aspectRatio);
                    }
                    if (typeof syncRatioGridSelection === 'function') syncRatioGridSelection(options.aspectRatio);
                    if (typeof syncStudioRatioDropdown === 'function') syncStudioRatioDropdown(options.aspectRatio);
                }

                if (options.stylePreset) {
                    imageStudioState.activeStyle = options.stylePreset;
                    if (typeof syncStudioStylePills === 'function') {
                        syncStudioStylePills(options.stylePreset);
                    }
                }

                if (typeof updateStudioGenerateButtonState === 'function') updateStudioGenerateButtonState();
                if (typeof renderStudioAssetsGallery === 'function') renderStudioAssetsGallery();
                if (typeof renderStudioReferenceSlots === 'function') renderStudioReferenceSlots();

                if (options.autoGenerate && options.prompt) {
                    setTimeout(() => {
                        generateStudioImages(options.prompt, options.aspectRatio, options.referenceImage);
                    }, 100);
                } else if (options.editItem) {
                    setTimeout(() => {
                        enterStudioPreciseEdit(options.editItem);
                    }, 60);
                }
            }

            if (window.lucide) window.lucide.createIcons();
        }

        const IDEOGRAM_ROTATING_PLACEHOLDERS = [
            "An origami crane made of world-map paper, clean studio lighting.",
            "A cartoon mascot of a hot chili pepper wearing a chef hat.",
            "Packaging for organic granola in kraft paper box with botanical illustration.",
            "A 35mm film photo of friends laughing around a campfire at dusk.",
            "A simple infographic showing the water cycle with labeled arrows.",
            "Retro-futuristic sci-fi cityscape with floating monorails, sunset glow.",
            "A cozy ceramic mug of matcha latte with delicate leaf foam art.",
            "Minimalist line-art poster of a Bauhaus architectural chair."
        ];

        let currentPlaceholderIndex = 0;
        let placeholderTypewriterTimer = null;
        let placeholderHoldTimer = null;
        let isStreamingWords = false;
        let isHomePromptFocused = false;

        function stopTypewriterStreaming() {
            if (placeholderTypewriterTimer) {
                clearTimeout(placeholderTypewriterTimer);
                placeholderTypewriterTimer = null;
            }
            if (placeholderHoldTimer) {
                clearTimeout(placeholderHoldTimer);
                placeholderHoldTimer = null;
            }
            isStreamingWords = false;
        }

        function updatePlaceholderVisibility() {
            const overlay = document.getElementById('image-home-placeholder-overlay');
            const homePrompt = document.getElementById('image-home-prompt-input');
            if (!overlay || !homePrompt) return;

            const hasText = homePrompt.value.trim().length > 0;
            if (hasText) {
                overlay.classList.add('opacity-0', 'pointer-events-none');
                overlay.style.opacity = '0';
                stopTypewriterStreaming();
            } else {
                overlay.classList.remove('opacity-0', 'pointer-events-none');
                overlay.style.opacity = '1';
                // If user cleared text and rotation is not currently running, resume smoothly
                if (!isStreamingWords && !placeholderHoldTimer && !placeholderTypewriterTimer) {
                    streamCurrentPrompt();
                }
            }
        }

        function streamCurrentPrompt() {
            stopTypewriterStreaming();
            const homePrompt = document.getElementById('image-home-prompt-input');
            const overlay = document.getElementById('image-home-placeholder-overlay');
            const placeholderEl = document.getElementById('image-home-placeholder-text');
            const tabBadge = document.getElementById('image-home-tab-badge');

            if (!placeholderEl || !overlay) return;

            // ONLY hide or pause rotation when the input contains user-entered text
            if (homePrompt && homePrompt.value.trim().length > 0) {
                overlay.classList.add('opacity-0', 'pointer-events-none');
                overlay.style.opacity = '0';
                return;
            }

            // Input is empty - ensure overlay is visible and continue rotating smoothly (never pause on focus)
            overlay.classList.remove('opacity-0', 'pointer-events-none');
            overlay.style.opacity = '1';
            if (tabBadge) {
                tabBadge.classList.add('opacity-0');
                tabBadge.style.opacity = '0';
            }

            const phrase = IDEOGRAM_ROTATING_PLACEHOLDERS[currentPlaceholderIndex] || '';
            const words = phrase.split(' ');
            let wordIdx = 0;
            placeholderEl.textContent = '';
            isStreamingWords = true;

            function streamNextWord() {
                if (!isStreamingWords) return;

                // Stop if user typed text
                if (homePrompt && homePrompt.value.trim().length > 0) {
                    stopTypewriterStreaming();
                    overlay.classList.add('opacity-0', 'pointer-events-none');
                    overlay.style.opacity = '0';
                    return;
                }

                if (wordIdx < words.length) {
                    wordIdx++;
                    placeholderEl.textContent = words.slice(0, wordIdx).join(' ');
                    // Smooth, rapid cadence per word (48ms)
                    placeholderTypewriterTimer = setTimeout(streamNextWord, 48);
                } else {
                    isStreamingWords = false;
                    if (tabBadge) {
                        tabBadge.classList.remove('opacity-0');
                        tabBadge.style.opacity = '1';
                    }

                    // Hold for ~4 seconds before cleanly fading out and advancing to next prompt
                    placeholderHoldTimer = setTimeout(() => {
                        if (homePrompt && homePrompt.value.trim().length > 0) return;

                        overlay.style.opacity = '0';
                        setTimeout(() => {
                            if (homePrompt && homePrompt.value.trim().length > 0) return;
                            currentPlaceholderIndex = (currentPlaceholderIndex + 1) % IDEOGRAM_ROTATING_PLACEHOLDERS.length;
                            streamCurrentPrompt();
                        }, 260);
                    }, 4000);
                }
            }

            streamNextWord();
        }

        function startPlaceholderRotation() {
            streamCurrentPrompt();
        }

        function stopPlaceholderRotation() {
            stopTypewriterStreaming();
        }

        // ============================================================
        // GLOBAL IMAGE STUDIO MODEL ICON HELPER
        // ============================================================
