        function goToModalSlide(index) {
            if (!slidesModalState.currentTmpl) return;
            slidesModalState.currentSlideIndex = Math.max(0, Math.min(index, slidesModalState.totalSlides - 1));
            const canvas = document.getElementById('slides-modal-canvas');
            const counter = document.getElementById('slides-modal-counter');
            const prevBtn = document.getElementById('slides-modal-prev-btn');
            const nextBtn = document.getElementById('slides-modal-next-btn');

            if (canvas) {
                canvas.innerHTML = getTemplateSlideHTML(slidesModalState.currentTmpl, slidesModalState.currentSlideIndex);
            }
            if (counter) {
                counter.textContent = `${slidesModalState.currentSlideIndex + 1} / ${slidesModalState.totalSlides}`;
            }
            if (prevBtn) {
                prevBtn.disabled = slidesModalState.currentSlideIndex === 0;
            }
            if (nextBtn) {
                nextBtn.disabled = slidesModalState.currentSlideIndex === slidesModalState.totalSlides - 1;
            }
        }

        function openSlidesTemplateModal(tmpl) {
            if (!tmpl) return;
            slidesModalState.currentTmpl = tmpl;
            slidesModalState.currentSlideIndex = 0;

            const modal = document.getElementById('slides-template-modal');
            const titleEl = document.getElementById('slides-modal-title');
            const descEl = document.getElementById('slides-modal-desc');
            const badgeEl = document.getElementById('slides-modal-badge');

            if (titleEl) titleEl.textContent = tmpl.title;
            if (descEl) descEl.textContent = tmpl.description;
            if (badgeEl) {
                badgeEl.textContent = tmpl.isPro ? 'PRO' : 'FREE';
                badgeEl.className = tmpl.isPro
                    ? 'px-2 py-0.5 rounded-md bg-amber-50 text-amber-700 border border-amber-200/80 text-[10px] font-bold uppercase tracking-wider shrink-0'
                    : 'px-2 py-0.5 rounded-md bg-emerald-50 text-emerald-700 border border-emerald-200/80 text-[10px] font-bold uppercase tracking-wider shrink-0';
            }

            goToModalSlide(0);

            if (modal) {
                modal.classList.remove('hidden', 'pointer-events-none');
                modal.classList.add('flex', 'pointer-events-auto');
                modal.style.display = 'flex';
                modal.style.pointerEvents = 'auto';
            }
        }

        function closeSlidesTemplateModal() {
            const modal = document.getElementById('slides-template-modal');
            if (modal) {
                modal.classList.add('hidden', 'pointer-events-none');
                modal.classList.remove('flex', 'pointer-events-auto');
                modal.style.display = 'none';
                modal.style.pointerEvents = 'none';
            }
            document.body.style.overflow = '';
            document.body.style.pointerEvents = '';
            document.documentElement.style.overflow = '';
            document.documentElement.style.pointerEvents = '';
            slidesModalState.currentTmpl = null;
        }

        function closeAllSlidesDropdowns() {
            const dropdowns = [
                'slides-mode-dropdown',
                'slides-tone-dropdown',
                'slides-style-dropdown',
                'slides-visual-dropdown',
                'slides-count-dropdown'
            ];
            dropdowns.forEach(id => {
                const el = document.getElementById(id);
                if (el) el.classList.add('hidden');
            });
        }

        function renderSlidesTemplates(filterQuery = '') {
            const grid = document.getElementById('slides-templates-grid');
            const emptyState = document.getElementById('slides-templates-empty');
            if (!grid) return;

            const q = (filterQuery || '').trim().toLowerCase();
            const filtered = SLIDES_TEMPLATES.filter(t => {
                if (!q) return true;
                return t.title.toLowerCase().includes(q) ||
                    t.category.toLowerCase().includes(q) ||
                    t.description.toLowerCase().includes(q);
            });

            if (filtered.length === 0) {
                grid.innerHTML = '';
                if (emptyState) emptyState.classList.remove('hidden');
                return;
            }

            if (emptyState) emptyState.classList.add('hidden');
            grid.innerHTML = '';

            filtered.forEach(tmpl => {
                const isSelected = slidesStudioState.selectedTemplate && slidesStudioState.selectedTemplate.id === tmpl.id;
                const card = document.createElement('div');
                card.className = `group relative rounded-2xl border ${isSelected ? 'border-blue-500 ring-2 ring-blue-500/30' : 'border-slate-200/90'} bg-white overflow-hidden shadow-2xs hover:border-slate-300 hover:shadow-md transition-all duration-200 cursor-pointer flex flex-col justify-between`;

                const proBadge = tmpl.isPro
                    ? '<span class="px-2 py-0.5 rounded-md bg-amber-500/95 text-[10px] font-bold text-white shadow-2xs">PRO</span>'
                    : '<span class="px-2 py-0.5 rounded-md bg-emerald-500/95 text-[10px] font-bold text-white shadow-2xs">FREE</span>';

                card.innerHTML = `
                    <div class="h-36 sm:h-40 w-full overflow-hidden bg-slate-900 relative">
                        <img src="${tmpl.img}" alt="${escapeHtml(tmpl.title)}" class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300 opacity-90" loading="lazy">
                        <div class="absolute inset-0 bg-gradient-to-t from-slate-950/75 via-transparent to-transparent"></div>
                        <span class="absolute top-2.5 left-2.5 px-2 py-0.5 rounded-md bg-black/60 backdrop-blur-xs text-[10px] font-semibold text-white tracking-wide uppercase">${escapeHtml(tmpl.category)}</span>
                        <div class="absolute top-2.5 right-2.5 flex items-center gap-1.5">
                            ${isSelected ? '<span class="px-2 py-0.5 rounded-md bg-blue-600 text-[10px] font-bold text-white flex items-center gap-1 shadow-xs">Selected</span>' : ''}
                            ${proBadge}
                        </div>
                    </div>
                    <div class="p-3.5 sm:p-4 flex-1 flex flex-col justify-between">
                        <div>
                            <div class="flex items-center justify-between">
                                <h3 class="text-sm font-bold text-slate-800 group-hover:text-blue-600 transition-colors truncate">${escapeHtml(tmpl.title)}</h3>
                            </div>
                            <p class="text-xs text-slate-500 mt-1 line-clamp-1 leading-relaxed">${escapeHtml(tmpl.description)}</p>
                        </div>
                        <div class="mt-3 pt-2.5 border-t border-slate-100 flex items-center justify-between">
                            <span class="text-[11px] text-slate-400 font-medium">8 Slides</span>
                            <button type="button" class="slides-card-use-btn inline-flex items-center gap-1 px-2.5 py-1 rounded-lg bg-blue-50 text-blue-600 hover:bg-blue-600 hover:text-white text-xs font-semibold transition-colors cursor-pointer shadow-2xs" title="Preview and use template">
                                <span>Use</span>
                                <svg class="w-3 h-3" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="m9 18 6-6-6-6"/></svg>
                            </button>
                        </div>
                    </div>
                `;

                // Clicking anywhere on the card opens the preview modal
                card.addEventListener('click', () => {
                    openSlidesTemplateModal(tmpl);
                });

                // Clicking the small "Use" button also opens preview modal
                const cardUseBtn = card.querySelector('.slides-card-use-btn');
                if (cardUseBtn) {
                    cardUseBtn.addEventListener('click', (e) => {
                        e.stopPropagation();
                        openSlidesTemplateModal(tmpl);
                    });
                }

                grid.appendChild(card);
            });
        }

        function updateSlidesGenerateButtonState() {
            const promptInput = document.getElementById('slides-prompt-input');
            const generateBtn = document.getElementById('slides-generate-btn');
            if (!generateBtn) return;

            if (slidesStudioState.isGenerating) {
                generateBtn.disabled = true;
                generateBtn.classList.add('opacity-50', 'cursor-not-allowed');
                generateBtn.classList.remove('cursor-pointer');
                return;
            }

            const promptText = (promptInput?.value || '').trim();
            const attachedTemplate = slidesStudioState.selectedTemplate;
            const hasAttachments = (slidesStudioState.attachedFiles && slidesStudioState.attachedFiles.length > 0);
            // Active when user types something, attaches a template, or attaches files
            const canGenerate = !!(promptText || attachedTemplate || hasAttachments);

            generateBtn.disabled = !canGenerate;
            if (canGenerate) {
                generateBtn.classList.remove('opacity-50', 'cursor-not-allowed');
                generateBtn.classList.add('cursor-pointer');
            } else {
                generateBtn.classList.add('opacity-50', 'cursor-not-allowed');
                generateBtn.classList.remove('cursor-pointer');
            }
        }

        function applySlidesTemplate(tmpl) {
            slidesStudioState.selectedTemplate = tmpl;
            const promptInput = document.getElementById('slides-prompt-input');
            const badge = document.getElementById('slides-selected-template-badge');
            const thumb = document.getElementById('slides-template-thumb');
            const catLabel = document.getElementById('slides-template-cat-label');
            const nameLabel = document.getElementById('slides-template-name-label');
            const errorMsg = document.getElementById('slides-prompt-error');

            // Requirement 1: Do NOT auto-prompt! Main textarea remains as is (or empty) with placeholder
            if (promptInput) {
                promptInput.focus();
            }

            // Populate and show attachment chip (Requirement 1)
            if (thumb) {
                thumb.src = tmpl.img;
                thumb.alt = tmpl.title;
            }
            if (catLabel) {
                catLabel.textContent = tmpl.category || 'TEMPLATE';
            }
            if (nameLabel) {
                nameLabel.textContent = tmpl.title;
            }
            if (badge) {
                badge.classList.remove('hidden');
                badge.classList.add('inline-flex');
            }
            if (errorMsg) {
                errorMsg.classList.add('hidden');
            }

            if (tmpl.defaultTone) {
                slidesStudioState.tone = tmpl.defaultTone;
                const toneLabel = document.getElementById('slides-tone-label');
                if (toneLabel) toneLabel.textContent = tmpl.defaultTone;
                updateToneDropdownChecks(tmpl.defaultTone);
            }
            if (tmpl.defaultMode) {
                slidesStudioState.mode = tmpl.defaultMode;
                const modeLabel = document.getElementById('slides-mode-label');
                if (modeLabel) modeLabel.textContent = tmpl.defaultMode;
            }

            // Re-render templates to update visual selection badge
            renderSlidesTemplates(document.getElementById('slides-template-search')?.value || '');

            // Update generate button state (Requirement 2)
            updateSlidesGenerateButtonState();

            // Smooth scroll up to composer
            const composerBox = document.getElementById('slides-composer-box');
            if (composerBox) {
                composerBox.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
            showStudioToast(`Template "${tmpl.title}" attached`);
        }

        function clearSelectedSlidesTemplate() {
            slidesStudioState.selectedTemplate = null;
            const badge = document.getElementById('slides-selected-template-badge');
            if (badge) {
                badge.classList.add('hidden');
                badge.classList.remove('inline-flex');
            }
            const thumb = document.getElementById('slides-template-thumb');
            if (thumb) thumb.src = '';
            renderSlidesTemplates(document.getElementById('slides-template-search')?.value || '');
            updateSlidesGenerateButtonState();
        }

        // ─── SLIDES ATTACHED FILES HANDLING (MOCK UPLOAD & CHIPS) ────────────

        function formatSlidesFileSize(bytes) {
            if (!bytes || bytes === 0) return '0 B';
            const k = 1024;
            const sizes = ['B', 'KB', 'MB', 'GB'];
            const i = Math.floor(Math.log(bytes) / Math.log(k));
            return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
        }

        function handleSlidesFilesSelected(files) {
            if (!slidesStudioState.attachedFiles) slidesStudioState.attachedFiles = [];

            files.forEach(file => {
                const fileId = 'sfile_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7);
                let previewUrl = null;
                if (file.type && file.type.startsWith('image/')) {
                    try { previewUrl = URL.createObjectURL(file); } catch (e) { }
                }

                const fileObj = {
                    id: fileId,
                    name: file.name,
                    size: file.size,
                    formattedSize: formatSlidesFileSize(file.size),
                    type: file.type || file.name.split('.').pop().toLowerCase(),
                    previewUrl: previewUrl,
                    status: 'uploading'
                };

                slidesStudioState.attachedFiles.push(fileObj);
                renderSlidesAttachedFiles();
                updateSlidesGenerateButtonState();

                // Requirement 3: Simulated upload progress for 1 second, then marked ready
                setTimeout(() => {
                    const item = (slidesStudioState.attachedFiles || []).find(f => f.id === fileId);
                    if (item && item.status === 'uploading') {
                        item.status = 'ready';
                        renderSlidesAttachedFiles();
                        updateSlidesGenerateButtonState();
                        showStudioToast(`"${file.name}" ready`);
                    }
                }, 1000);
            });
        }

        function renderSlidesAttachedFiles() {
            const container = document.getElementById('slides-attached-files-list');
            if (!container) return;

            const files = slidesStudioState.attachedFiles || [];
            container.innerHTML = '';

            files.forEach(file => {
                const chip = document.createElement('div');
                const isUploading = file.status === 'uploading';

                chip.className = isUploading
                    ? 'inline-flex items-center gap-2 pl-2.5 pr-2 py-1 bg-blue-50/80 border border-blue-200 rounded-xl text-xs text-blue-700 w-fit shadow-2xs transition-all animate-pulse'
                    : 'inline-flex items-center gap-2 pl-2 pr-2 py-1 bg-slate-50 hover:bg-slate-100/70 border border-slate-200 rounded-xl text-xs text-slate-700 w-fit shadow-2xs group transition-all';

                const ext = (file.name.split('.').pop() || '').toLowerCase();
                let iconHtml = '';
                if (file.previewUrl) {
                    iconHtml = `<div class="w-5 h-5 rounded-md overflow-hidden bg-slate-200 shrink-0 border border-slate-200/80"><img src="${file.previewUrl}" class="w-full h-full object-cover"></div>`;
                } else if (ext === 'pdf') {
                    iconHtml = `<span class="w-5 h-5 rounded-md bg-rose-50 text-rose-600 border border-rose-200/70 flex items-center justify-center text-[9px] font-bold shrink-0">PDF</span>`;
                } else if (ext === 'ppt' || ext === 'pptx') {
                    iconHtml = `<span class="w-5 h-5 rounded-md bg-amber-50 text-amber-600 border border-amber-200/70 flex items-center justify-center text-[8px] font-bold shrink-0">PPT</span>`;
                } else if (ext === 'doc' || ext === 'docx') {
                    iconHtml = `<span class="w-5 h-5 rounded-md bg-blue-50 text-blue-600 border border-blue-200/70 flex items-center justify-center text-[8px] font-bold shrink-0">DOC</span>`;
                } else {
                    iconHtml = `<svg class="w-3.5 h-3.5 text-slate-500 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>`;
                }

                const statusHtml = isUploading
                    ? `<span class="inline-flex items-center gap-1 text-[10px] text-blue-600 font-semibold shrink-0"><svg class="w-3 h-3 animate-spin" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><circle class="opacity-25" cx="12" cy="12" r="10"/><path class="opacity-75" d="M4 12a8 8 0 018-8v8H4z"/></svg>Uploading...</span>`
                    : `<span class="w-3.5 h-3.5 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center text-[8px] font-bold shrink-0" title="Ready">✓</span>`;

                chip.innerHTML = `
                    ${iconHtml}
                    <span class="font-medium text-slate-800 truncate max-w-[140px] sm:max-w-[200px]" title="${escapeHtml(file.name)}">${escapeHtml(file.name)}</span>
                    ${statusHtml}
                    <button type="button" class="slides-remove-file-btn w-4 h-4 rounded-full flex items-center justify-center text-slate-400 hover:text-rose-600 hover:bg-rose-50 transition-colors ml-0.5 cursor-pointer shrink-0" title="Remove file" aria-label="Remove file">
                        <svg class="w-3 h-3" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
                            <line x1="18" y1="6" x2="6" y2="18"></line>
                            <line x1="6" y1="6" x2="18" y2="18"></line>
                        </svg>
                    </button>
                `;

                const removeBtn = chip.querySelector('.slides-remove-file-btn');
                if (removeBtn) {
                    removeBtn.addEventListener('click', (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        removeSlidesAttachedFile(file.id);
                    });
                }

                container.appendChild(chip);
            });
        }

        function removeSlidesAttachedFile(fileId) {
            if (!slidesStudioState.attachedFiles) return;
            const file = slidesStudioState.attachedFiles.find(f => f.id === fileId);
            if (file && file.previewUrl) {
                try { URL.revokeObjectURL(file.previewUrl); } catch (e) { }
            }
            slidesStudioState.attachedFiles = slidesStudioState.attachedFiles.filter(f => f.id !== fileId);
            renderSlidesAttachedFiles();
            updateSlidesGenerateButtonState();
        }

        function clearAttachedSlidesFiles() {
            if (slidesStudioState.attachedFiles) {
                slidesStudioState.attachedFiles.forEach(f => {
                    if (f.previewUrl) {
                        try { URL.revokeObjectURL(f.previewUrl); } catch (e) { }
                    }
                });
            }
            slidesStudioState.attachedFiles = [];
            const fileInput = document.getElementById('slides-file-input');
            if (fileInput) fileInput.value = '';
            renderSlidesAttachedFiles();
            updateSlidesGenerateButtonState();
        }

        function updateToneDropdownChecks(selectedTone) {
            document.querySelectorAll('.slides-tone-option').forEach(btn => {
                const tone = btn.getAttribute('data-tone');
                const check = btn.querySelector('.slides-tone-check');
                if (check) {
                    if (tone === selectedTone) {
                        check.classList.remove('hidden');
                    } else {
                        check.classList.add('hidden');
                    }
                }
            });
        }

