        function generateSlides() {
            const promptInput = document.getElementById('slides-prompt-input');
            const errorMsg = document.getElementById('slides-prompt-error');
            const generateBtn = document.getElementById('slides-generate-btn');
            const loadingState = document.getElementById('slides-loading-state');
            const loadingStepTitle = document.getElementById('slides-loading-title');
            const loadingProgress = document.getElementById('slides-progress-bar');
            const deckSection = document.getElementById('slides-presentation-deck');

            const promptText = (promptInput?.value || '').trim();
            const attachedTemplate = slidesStudioState.selectedTemplate;
            const hasAttachments = (slidesStudioState.attachedFiles && slidesStudioState.attachedFiles.length > 0);

            // Must have either typed prompt OR attached template OR attached files
            if (!promptText && !attachedTemplate && !hasAttachments) {
                if (errorMsg) errorMsg.classList.remove('hidden');
                const composerBox = document.getElementById('slides-composer-box');
                if (composerBox) {
                    composerBox.classList.add('border-rose-400', 'ring-2', 'ring-rose-100');
                    setTimeout(() => {
                        composerBox.classList.remove('border-rose-400', 'ring-2', 'ring-rose-100');
                    }, 2000);
                }
                if (promptInput) promptInput.focus();
                return;
            }

            if (errorMsg) errorMsg.classList.add('hidden');
            // If user typed notes, use them; if empty, use attached template or files summary
            slidesStudioState.prompt = promptText || (attachedTemplate ? `${attachedTemplate.title}: ${attachedTemplate.description}` : (hasAttachments ? `Presentation based on ${slidesStudioState.attachedFiles.map(f => f.name).join(', ')}` : 'Presentation Topic'));
            slidesStudioState.isGenerating = true;
            updateSlidesGenerateButtonState();

            // Set loading text & spinner on button
            if (generateBtn) {
                const genText = document.getElementById('slides-generate-text');
                if (genText) genText.textContent = 'Generating...';
                const genIcon = document.getElementById('slides-generate-icon');
                if (genIcon) {
                    genIcon.innerHTML = `<path d="M21 12a9 9 0 1 1-6.219-8.56" class="animate-spin origin-center"/>`;
                }
            }

            // Hide old deck if any
            if (deckSection) deckSection.classList.add('hidden');

            // Show loading state and scroll
            if (loadingState) {
                loadingState.classList.remove('hidden');
                loadingState.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }

            // Sequence of loading steps (Requirement 10)
            const percentEl = document.getElementById('slides-loading-percent');
            const subtitleEl = document.getElementById('slides-loading-subtitle');
            if (loadingStepTitle) loadingStepTitle.textContent = 'Understanding your topic & audience...';
            if (subtitleEl) subtitleEl.textContent = 'Extracting narrative structure and target audience...';
            if (loadingProgress) loadingProgress.style.width = '28%';
            if (percentEl) percentEl.textContent = '28%';

            setTimeout(() => {
                if (loadingStepTitle) loadingStepTitle.textContent = 'Planning your presentation structure...';
                if (subtitleEl) subtitleEl.textContent = 'Designing slides layout and content hierarchy...';
                if (loadingProgress) loadingProgress.style.width = '64%';
                if (percentEl) percentEl.textContent = '64%';
            }, 600);

            setTimeout(() => {
                if (loadingStepTitle) loadingStepTitle.textContent = 'Designing your slides & visuals...';
                if (subtitleEl) subtitleEl.textContent = 'Applying visual styling, typography, and transitions...';
                if (loadingProgress) loadingProgress.style.width = '92%';
                if (percentEl) percentEl.textContent = '92%';
            }, 1200);

            setTimeout(() => {
                if (loadingProgress) loadingProgress.style.width = '100%';

                // Build slide deck
                const deck = buildDemoDeck(
                    slidesStudioState.prompt,
                    slidesStudioState.mode,
                    slidesStudioState.tone,
                    slidesStudioState.slideCount
                );
                slidesStudioState.currentDeck = deck;
                slidesStudioState.activeSlideIndex = 0;
                slidesStudioState.isGenerating = false;

                // Hide loading, show deck
                if (loadingState) loadingState.classList.add('hidden');
                if (deckSection) {
                    deckSection.classList.remove('hidden');
                    deckSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }

                // Restore generate button with premium AI icon & text
                if (generateBtn) {
                    const genText = document.getElementById('slides-generate-text');
                    if (genText) genText.textContent = 'Create Slides';
                    const genIcon = document.getElementById('slides-generate-icon');
                    if (genIcon) {
                        genIcon.innerHTML = `
                            <path d="m21.64 3.64-1.28-1.28a1.21 1.21 0 0 0-1.72 0L2.36 18.64a1.21 1.21 0 0 0 0 1.72l1.28 1.28a1.2 1.2 0 0 0 1.72 0L21.64 5.36a1.2 1.2 0 0 0 0-1.72Z"/>
                            <path d="m14 7 3 3"/>
                            <path d="M5 6v4"/>
                            <path d="M19 14v4"/>
                            <path d="M10 2v2"/>
                            <path d="M7 8H3"/>
                            <path d="M21 16h-4"/>
                            <path d="M11 3H9"/>
                        `;
                    }
                }
                updateSlidesGenerateButtonState();

                renderActiveSlide();
                showStudioToast('Presentation generated successfully!');
            }, 1800);
        }

        function initSlidesStudio() {
            // Slides Action badge on homepage
            const btnActionSlides = document.getElementById('btn-action-slides');
            if (btnActionSlides) {
                btnActionSlides.addEventListener('click', () => {
                    switchWorkspace('slides-studio');
                });
            }

            // Slides link in sidebar
            const sidebarNavSlides = document.getElementById('sidebar-nav-slides');
            if (sidebarNavSlides) {
                sidebarNavSlides.addEventListener('click', (e) => {
                    e.preventDefault();
                    switchWorkspace('slides-studio');
                });
            }

            // Prompt textarea input listener (clears error and updates button state)
            const promptInput = document.getElementById('slides-prompt-input');
            if (promptInput) {
                promptInput.addEventListener('input', () => {
                    const errorMsg = document.getElementById('slides-prompt-error');
                    if (errorMsg && promptInput.value.trim().length > 0) {
                        errorMsg.classList.add('hidden');
                    }
                    updateSlidesGenerateButtonState();
                });
                promptInput.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
                        e.preventDefault();
                        const canGenerate = promptInput.value.trim().length > 0 || !!slidesStudioState.selectedTemplate;
                        if (canGenerate) {
                            generateSlides();
                        }
                    }
                });
            }

            // Create Slides Button
            const genBtn = document.getElementById('slides-generate-btn');
            if (genBtn) {
                genBtn.addEventListener('click', (e) => {
                    e.preventDefault();
                    generateSlides();
                });
            }

            // Add / Attach Button inside composer (Requirement 1 & 2)
            const addBtn = document.getElementById('slides-add-btn');
            const fileInput = document.getElementById('slides-file-input');
            if (addBtn && fileInput) {
                addBtn.addEventListener('click', (e) => {
                    e.preventDefault();
                    fileInput.click();
                });
                fileInput.addEventListener('change', (e) => {
                    const files = Array.from(e.target.files || []);
                    if (!files.length) return;
                    handleSlidesFilesSelected(files);
                    fileInput.value = '';
                });
            }

            // Mode Selector
            const modeBtn = document.getElementById('slides-mode-btn');
            const modeDropdown = document.getElementById('slides-mode-dropdown');
            const modeLabel = document.getElementById('slides-mode-label');
            if (modeBtn && modeDropdown) {
                modeBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const willOpen = modeDropdown.classList.contains('hidden');
                    closeAllSlidesDropdowns();
                    if (willOpen) modeDropdown.classList.remove('hidden');
                });

                document.querySelectorAll('.slides-mode-option').forEach(opt => {
                    opt.addEventListener('click', (e) => {
                        e.stopPropagation();
                        const selectedMode = opt.getAttribute('data-mode');
                        slidesStudioState.mode = selectedMode;
                        if (modeLabel) modeLabel.textContent = selectedMode;

                        document.querySelectorAll('.slides-mode-option').forEach(btn => {
                            const check = btn.querySelector('.slides-mode-check');
                            if (check) check.classList.toggle('hidden', btn.getAttribute('data-mode') !== selectedMode);
                        });
                        modeDropdown.classList.add('hidden');
                    });
                });
            }

            // Tone Selector (Requirement 8)
            const toneBtn = document.getElementById('slides-tone-btn');
            const toneDropdown = document.getElementById('slides-tone-dropdown');
            const toneLabel = document.getElementById('slides-tone-label');
            if (toneBtn && toneDropdown) {
                toneBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const willOpen = toneDropdown.classList.contains('hidden');
                    closeAllSlidesDropdowns();
                    if (willOpen) toneDropdown.classList.remove('hidden');
                });

                document.querySelectorAll('.slides-tone-option').forEach(opt => {
                    opt.addEventListener('click', (e) => {
                        e.stopPropagation();
                        const selectedTone = opt.getAttribute('data-tone');
                        slidesStudioState.tone = selectedTone;
                        if (toneLabel) toneLabel.textContent = selectedTone;
                        updateToneDropdownChecks(selectedTone);
                        toneDropdown.classList.add('hidden');
                    });
                });
            }

            // Style Selector
            const styleBtn = document.getElementById('slides-style-btn');
            const styleDropdown = document.getElementById('slides-style-dropdown');
            const styleLabel = document.getElementById('slides-style-label');
            if (styleBtn && styleDropdown) {
                styleBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const willOpen = styleDropdown.classList.contains('hidden');
                    closeAllSlidesDropdowns();
                    if (willOpen) styleDropdown.classList.remove('hidden');
                });

                document.querySelectorAll('.slides-style-option').forEach(opt => {
                    opt.addEventListener('click', (e) => {
                        e.stopPropagation();
                        const selectedStyle = opt.getAttribute('data-style');
                        slidesStudioState.style = selectedStyle;
                        if (styleLabel) styleLabel.textContent = selectedStyle;

                        document.querySelectorAll('.slides-style-option').forEach(btn => {
                            const check = btn.querySelector('.slides-style-check');
                            if (check) check.classList.toggle('hidden', btn.getAttribute('data-style') !== selectedStyle);
                        });
                        styleDropdown.classList.add('hidden');
                    });
                });
            }

            // Visual Source Selector
            const visualBtn = document.getElementById('slides-visual-btn');
            const visualDropdown = document.getElementById('slides-visual-dropdown');
            const visualLabel = document.getElementById('slides-visual-label');
            if (visualBtn && visualDropdown) {
                visualBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const willOpen = visualDropdown.classList.contains('hidden');
                    closeAllSlidesDropdowns();
                    if (willOpen) visualDropdown.classList.remove('hidden');
                });

                document.querySelectorAll('.slides-visual-option').forEach(opt => {
                    opt.addEventListener('click', (e) => {
                        e.stopPropagation();
                        const selectedVisual = opt.getAttribute('data-visual');
                        slidesStudioState.visuals = selectedVisual;
                        if (visualLabel) visualLabel.textContent = selectedVisual;

                        document.querySelectorAll('.slides-visual-option').forEach(btn => {
                            const check = btn.querySelector('.slides-visual-check');
                            if (check) check.classList.toggle('hidden', btn.getAttribute('data-visual') !== selectedVisual);
                        });
                        visualDropdown.classList.add('hidden');
                    });
                });
            }

            // Slide Count Selector
            const countBtn = document.getElementById('slides-count-btn');
            const countDropdown = document.getElementById('slides-count-dropdown');
            const countLabel = document.getElementById('slides-count-label');
            if (countBtn && countDropdown) {
                countBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const willOpen = countDropdown.classList.contains('hidden');
                    closeAllSlidesDropdowns();
                    if (willOpen) countDropdown.classList.remove('hidden');
                });

                document.querySelectorAll('.slides-count-option').forEach(opt => {
                    opt.addEventListener('click', (e) => {
                        e.stopPropagation();
                        const rawCount = opt.getAttribute('data-count');
                        if (rawCount === 'Auto') {
                            slidesStudioState.slideCount = 'Auto';
                            if (countLabel) countLabel.textContent = 'Auto';
                        } else {
                            const countVal = parseInt(rawCount, 10);
                            slidesStudioState.slideCount = countVal;
                            if (countLabel) countLabel.textContent = `${countVal} Slides`;
                        }

                        document.querySelectorAll('.slides-count-option').forEach(btn => {
                            const check = btn.querySelector('.slides-count-check');
                            if (check) check.classList.toggle('hidden', btn.getAttribute('data-count') !== rawCount);
                        });
                        countDropdown.classList.add('hidden');
                    });
                });
            }

            // Clear Template Badge Button
            const clearTemplateBtn = document.getElementById('slides-template-clear-btn');
            if (clearTemplateBtn) {
                clearTemplateBtn.addEventListener('click', (e) => {
                    e.preventDefault();
                    clearSelectedSlidesTemplate();
                });
            }

            // Slide Deck Navigation Controls (Prev / Next)
            const prevBtn = document.getElementById('slides-deck-prev');
            const nextBtn = document.getElementById('slides-deck-next');
            if (prevBtn) {
                prevBtn.addEventListener('click', (e) => {
                    e.preventDefault();
                    if (slidesStudioState.activeSlideIndex > 0) {
                        slidesStudioState.activeSlideIndex--;
                        renderActiveSlide();
                    }
                });
            }
            if (nextBtn) {
                nextBtn.addEventListener('click', (e) => {
                    e.preventDefault();
                    if (slidesStudioState.currentDeck && slidesStudioState.activeSlideIndex < slidesStudioState.currentDeck.length - 1) {
                        slidesStudioState.activeSlideIndex++;
                        renderActiveSlide();
                    }
                });
            }

            // New Presentation Button
            const newPresBtn = document.getElementById('slides-new-deck-btn');
            if (newPresBtn) {
                newPresBtn.addEventListener('click', (e) => {
                    e.preventDefault();
                    const promptEl = document.getElementById('slides-prompt-input');
                    if (promptEl) {
                        promptEl.value = '';
                        promptEl.focus();
                    }
                    clearSelectedSlidesTemplate();
                    clearAttachedSlidesFiles();
                    const deckSection = document.getElementById('slides-presentation-deck');
                    if (deckSection) deckSection.classList.add('hidden');
                    const composerBox = document.getElementById('slides-composer-box');
                    if (composerBox) composerBox.scrollIntoView({ behavior: 'smooth', block: 'center' });
                });
            }

            // Download Deck Button (Silent direct file download)
            function downloadSlidesDeck() {
                const deck = slidesStudioState.currentDeck || [];
                const promptTitle = (slidesStudioState.prompt || 'Presentation').trim();
                const safeName = promptTitle.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'presentation-deck';

                // Format presentation content cleanly
                let content = `# ${promptTitle || 'Presentation Deck'}\n\n`;
                content += `Export Date: ${new Date().toLocaleDateString()}\n`;
                content += `Tone: ${slidesStudioState.tone || 'Professional'} | Slides: ${deck.length || 6}\n\n`;
                content += `============================================================\n\n`;

                deck.forEach((slide, idx) => {
                    content += `SLIDE ${idx + 1}: ${slide.title || 'Untitled Slide'}\n`;
                    if (slide.pill) content += `[${slide.pill}]\n`;
                    if (slide.subtitle) content += `${slide.subtitle}\n\n`;

                    if (slide.points && Array.isArray(slide.points)) {
                        slide.points.forEach(pt => {
                            content += `• ${pt.label}: ${pt.desc}\n`;
                        });
                        content += '\n';
                    }

                    if (slide.cards && Array.isArray(slide.cards)) {
                        slide.cards.forEach(c => {
                            content += `• ${c.title}: ${c.desc}\n`;
                        });
                        content += '\n';
                    }

                    if (slide.phases && Array.isArray(slide.phases)) {
                        slide.phases.forEach(ph => {
                            content += `Phase ${ph.step} - ${ph.title}: ${ph.detail}\n`;
                        });
                        content += '\n';
                    }

                    if (slide.stats && Array.isArray(slide.stats)) {
                        slide.stats.forEach(st => {
                            content += `• ${st.value} ${st.label} (${st.sub})\n`;
                        });
                        content += '\n';
                    }

                    if (slide.actions && Array.isArray(slide.actions)) {
                        slide.actions.forEach(act => {
                            content += `✓ ${act}\n`;
                        });
                        content += '\n';
                    }

                    if (slide.meta) content += `Meta: ${slide.meta}\n`;
                    if (slide.footerNote) content += `Note: ${slide.footerNote}\n`;
                    if (slide.contact) content += `Contact: ${slide.contact}\n`;

                    content += `\n------------------------------------------------------------\n\n`;
                });

                const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `${safeName}.txt`;
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                setTimeout(() => URL.revokeObjectURL(url), 1000);
            }

            const exportBtn = document.getElementById('slides-export-btn');
            if (exportBtn) {
                exportBtn.addEventListener('click', (e) => {
                    e.preventDefault();
                    downloadSlidesDeck();
                });
            }

            // Template Search Input (Requirement 13 & 16)
            const searchInput = document.getElementById('slides-template-search');
            const searchClear = document.getElementById('slides-search-clear');
            const emptyResetBtn = document.getElementById('slides-empty-reset-btn');

            if (searchInput) {
                searchInput.addEventListener('input', (e) => {
                    const val = e.target.value;
                    if (searchClear) {
                        searchClear.classList.toggle('hidden', val.length === 0);
                    }
                    renderSlidesTemplates(val);
                });
            }

            if (searchClear) {
                searchClear.addEventListener('click', (e) => {
                    e.preventDefault();
                    if (searchInput) {
                        searchInput.value = '';
                        searchInput.focus();
                    }
                    searchClear.classList.add('hidden');
                    renderSlidesTemplates('');
                });
            }

            if (emptyResetBtn) {
                emptyResetBtn.addEventListener('click', (e) => {
                    e.preventDefault();
                    if (searchInput) {
                        searchInput.value = '';
                    }
                    if (searchClear) {
                        searchClear.classList.add('hidden');
                    }
                    renderSlidesTemplates('');
                });
            }

            // Global click outside to dismiss all slides dropdowns
            document.addEventListener('click', (e) => {
                const wrappers = [
                    'slides-mode-wrapper',
                    'slides-tone-wrapper',
                    'slides-style-wrapper',
                    'slides-visual-wrapper',
                    'slides-count-wrapper'
                ];
                const clickedInside = wrappers.some(id => {
                    const el = document.getElementById(id);
                    return el && el.contains(e.target);
                });
                if (!clickedInside) {
                    closeAllSlidesDropdowns();
                }
            });

            // Template Preview Modal Listeners
            const modalCloseBtn = document.getElementById('slides-modal-close-btn');
            const modalCancelBtn = document.getElementById('slides-modal-cancel-btn');
            const modalPrevBtn = document.getElementById('slides-modal-prev-btn');
            const modalNextBtn = document.getElementById('slides-modal-next-btn');
            const modalUseBtn = document.getElementById('slides-modal-use-btn');
            const templateModal = document.getElementById('slides-template-modal');
            const modalDialog = document.getElementById('slides-template-modal-dialog');

            if (modalCloseBtn) modalCloseBtn.addEventListener('click', closeSlidesTemplateModal);
            if (modalCancelBtn) modalCancelBtn.addEventListener('click', closeSlidesTemplateModal);
            if (modalPrevBtn) {
                modalPrevBtn.addEventListener('click', () => {
                    if (slidesModalState.currentSlideIndex > 0) {
                        goToModalSlide(slidesModalState.currentSlideIndex - 1);
                    }
                });
            }
            if (modalNextBtn) {
                modalNextBtn.addEventListener('click', () => {
                    if (slidesModalState.currentSlideIndex < slidesModalState.totalSlides - 1) {
                        goToModalSlide(slidesModalState.currentSlideIndex + 1);
                    }
                });
            }
            if (modalUseBtn) {
                modalUseBtn.addEventListener('click', () => {
                    if (slidesModalState.currentTmpl) {
                        applySlidesTemplate(slidesModalState.currentTmpl);
                        closeSlidesTemplateModal();
                    }
                });
            }

            // Click outside dialog to close
            if (templateModal && modalDialog) {
                templateModal.addEventListener('click', (e) => {
                    if (!modalDialog.contains(e.target)) {
                        closeSlidesTemplateModal();
                    }
                });
            }

            // Keyboard navigation (Escape to close, Left/Right arrow to browse slides)
            document.addEventListener('keydown', (e) => {
                if (!templateModal || templateModal.classList.contains('hidden')) return;
                if (e.key === 'Escape') {
                    closeSlidesTemplateModal();
                } else if (e.key === 'ArrowLeft') {
                    if (slidesModalState.currentSlideIndex > 0) {
                        goToModalSlide(slidesModalState.currentSlideIndex - 1);
                    }
                } else if (e.key === 'ArrowRight') {
                    if (slidesModalState.currentSlideIndex < slidesModalState.totalSlides - 1) {
                        goToModalSlide(slidesModalState.currentSlideIndex + 1);
                    }
                }
            });

            // Initial render of templates & attached files
            renderSlidesTemplates('');
            renderSlidesAttachedFiles();

            // Initial button state (Requirement 2: Disabled when empty)
            updateSlidesGenerateButtonState();
        }

        // Initialize Slides Studio
        initSlidesStudio();

        // Expose Slides Studio on window for verification/testing
        window.slidesStudioState = slidesStudioState;
        window.slidesModalState = slidesModalState;
        window.openSlidesTemplateModal = openSlidesTemplateModal;
        window.closeSlidesTemplateModal = closeSlidesTemplateModal;
        window.generateSlides = generateSlides;
        window.applySlidesTemplate = applySlidesTemplate;
        window.clearSelectedSlidesTemplate = clearSelectedSlidesTemplate;
        window.handleSlidesFilesSelected = handleSlidesFilesSelected;
        window.renderSlidesAttachedFiles = renderSlidesAttachedFiles;
        window.removeSlidesAttachedFile = removeSlidesAttachedFile;
        window.clearAttachedSlidesFiles = clearAttachedSlidesFiles;
        window.updateSlidesGenerateButtonState = updateSlidesGenerateButtonState;
        window.renderSlidesTemplates = renderSlidesTemplates;

        // Safe stub if legacy code calls initCodeWorkspace
        window.initCodeWorkspace = function () { if (typeof switchWorkspace === 'function') switchWorkspace('chat'); };

        // HTML escape helper
        /* duplicate escapeHtml */ var _escapeHtml_dup3 = function(str) {
            if (!str) return '';
            return String(str)
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#39;');
        }

        // ─── Sidebar Collapse & Mobile Drawer ─────────────────────────────
        (function () {
            const sidebar = document.getElementById('sidebar');
            const overlay = document.getElementById('sidebar-overlay');
            const toggleBtn = document.getElementById('sidebar-toggle-btn');
            const mobileBtn = document.getElementById('mobile-menu-btn');

            if (!sidebar) return;

            const STORAGE_KEY = 'mestrio_sidebar_collapsed';
            const isMobile = () => window.innerWidth < 768;

            // ── Sync conditional border classes with collapsed/open state ──
            function syncSidebarBorder() {
                if (sidebar.classList.contains('sidebar-collapsed')) {
                    sidebar.classList.remove('border-neutral-200/50', 'dark:border-neutral-800/50');
                    sidebar.classList.add('border-transparent');
                } else {
                    sidebar.classList.remove('border-transparent');
                    sidebar.classList.add('border-neutral-200/50', 'dark:border-neutral-800/50');
                }
            }

            // ── Restore desktop collapsed state ──────────────────────────
            if (!isMobile() && localStorage.getItem(STORAGE_KEY) === '1') {
                sidebar.classList.add('sidebar-collapsed');
            }
            syncSidebarBorder();

            // ── Desktop: toggle collapsed/expanded ───────────────────────
            function toggleDesktopSidebar() {
                if (isMobile()) {
                    closeMobileDrawer();
                    return;
                }
                const isNowCollapsed = sidebar.classList.toggle('sidebar-collapsed');
                try { localStorage.setItem(STORAGE_KEY, isNowCollapsed ? '1' : '0'); } catch (_) {}
                syncSidebarBorder();
                try { window.dispatchEvent(new Event('resize')); } catch (_) {}
            }
            window.toggleDesktopSidebar = toggleDesktopSidebar;

            // ── Mobile: open drawer ───────────────────────────────────────
            function openMobileDrawer() {
                sidebar.classList.add('mobile-open');
                overlay.classList.remove('hidden');
                document.body.style.overflow = 'hidden';
            }

            // ── Mobile: close drawer ──────────────────────────────────────
            function closeMobileDrawer() {
                sidebar.classList.remove('mobile-open');
                overlay.classList.add('hidden');
                document.body.style.overflow = '';
            }

            // ── Desktop toggle button ─────────────────────────────────────
            if (toggleBtn) {
                toggleBtn.onclick = function (e) {
                    if (e) {
                        e.preventDefault();
                        e.stopPropagation();
                    }
                    if (isMobile()) {
                        closeMobileDrawer();
                    } else {
                        toggleDesktopSidebar();
                    }
                };
            }

            // ── Brand logo & Collapsed Rail Logo Hover Toggle ────────────
            function handleBrandLogoClick(e) {
                if (e) {
                    e.preventDefault();
                    e.stopPropagation();
                }
                if (sidebar.classList.contains('sidebar-collapsed')) {
                    toggleDesktopSidebar();
                    return;
                }
                if (isMobile()) closeMobileDrawer();
                if (typeof createNewChat === 'function') createNewChat();
                else if (typeof switchWorkspace === 'function') switchWorkspace('chat');
            }

            const brandLogo = document.getElementById('sidebar-brand-logo');
            if (brandLogo) {
                brandLogo.onclick = handleBrandLogoClick;
            }

            // ── Mobile hamburger ──────────────────────────────────────────
            if (mobileBtn) {
                mobileBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    openMobileDrawer();
                });
            }

            // ── Overlay click closes drawer ───────────────────────────────
            if (overlay) {
                overlay.addEventListener('click', closeMobileDrawer);
            }

            // ── Centralized Sidebar Navigation Delegation (Guarantees zero /# navigation traps) ──
            sidebar.addEventListener('click', (e) => {
                if (e.target.closest('#sidebar-toggle-btn')) {
                    return; // Cleanly handled by toggleBtn.onclick
                }
                const brandLogoEl = e.target.closest('#sidebar-brand-logo');
                if (brandLogoEl) {
                    handleBrandLogoClick(e);
                    return;
                }

                const navItem = e.target.closest('#new-chat-btn, #sidebar-nav-images, #sidebar-nav-slides, #sidebar-nav-projects, #sidebar-nav-library, #sidebar-nav-compare');
                if (!navItem) return;

                e.preventDefault();
                e.stopPropagation();
                if (isMobile()) closeMobileDrawer();

                const id = navItem.id;
                if (id === 'new-chat-btn') {
                    if (typeof createNewChat === 'function') createNewChat();
                    else if (typeof switchWorkspace === 'function') switchWorkspace('chat');
                } else if (id === 'sidebar-nav-images') {
                    if (typeof imageStudioMode !== 'undefined') imageStudioMode = 'home';
                    if (typeof switchWorkspace === 'function') switchWorkspace('image-studio');
                } else if (id === 'sidebar-nav-slides') {
                    if (typeof switchWorkspace === 'function') switchWorkspace('slides-studio');
                } else if (id === 'sidebar-nav-projects') {
                    if (typeof switchWorkspace === 'function') switchWorkspace('projects');
                } else if (id === 'sidebar-nav-library') {
                    if (typeof switchWorkspace === 'function') switchWorkspace('library');
                } else if (id === 'sidebar-nav-compare') {
                    if (typeof switchWorkspace === 'function') switchWorkspace('compare');
                }
            });

            // ── Close drawer when clicking recent chats on mobile ──
            sidebar.addEventListener('click', (e) => {
                if (!isMobile()) return;
                const interactive = e.target.closest('a, button#new-chat-btn');
                if (interactive && interactive.id !== 'sidebar-toggle-btn') {
                    closeMobileDrawer();
                }
            });

            // ── ESC closes drawer ─────────────────────────────────────────
            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape' && isMobile()) {
                    closeMobileDrawer();
                }
            });

            // ── On resize: clean up mobile state when switching to desktop ─
            window.addEventListener('resize', () => {
                if (!isMobile()) {
                    closeMobileDrawer();
                    // Re-apply stored collapsed state
                    if (localStorage.getItem(STORAGE_KEY) === '1') {
                        sidebar.classList.add('sidebar-collapsed');
                    } else {
                        sidebar.classList.remove('sidebar-collapsed');
                    }
                    syncSidebarBorder();
                }
            });

            // Expose for testing
            window.toggleDesktopSidebar = toggleDesktopSidebar;
            window.openMobileDrawer = openMobileDrawer;
            window.closeMobileDrawer = closeMobileDrawer;
        })();

        // ─── ACTION CHIPS CLICK TO AUTO-FILL PROMPT ─────────────────────────
        function initActionChips() {
            const chips = [
                { id: 'btn-action-images', prompt: 'Generate a photorealistic portrait of an astronaut floating near Saturn with dramatic golden lighting' },
                { id: 'btn-action-slides', prompt: 'Create a 6-slide executive pitch deck presentation for an enterprise AI workspace' },
                { id: 'btn-action-deep-research', prompt: 'Conduct a deep research analysis on next-generation solid-state battery technology and timelines' }
            ];

            chips.forEach(chip => {
                const btn = document.getElementById(chip.id);
                if (btn) {
                    btn.addEventListener('click', (e) => {
                        e.preventDefault();
                        if (typeof switchWorkspace === 'function' && currentWorkspace !== 'chat') {
                            switchWorkspace('chat');
                        }
                        const input = document.getElementById('chat-input');
                        const send = document.getElementById('send-btn');
                        if (input) {
                            input.value = chip.prompt;
                            if (typeof adjustTextareaHeight === 'function') adjustTextareaHeight();
                            if (send) {
                                send.classList.remove('hidden');
                                send.classList.add('flex');
                            }
                            input.focus();
                        }
                    });
                }
            });
        }

        // ─── FREE PLAN PROGRESS BAR & UPGRADE BUTTON MODULE ──────────────────
        function initFreePlanModule() {
            const STORAGE_KEY = 'mestrio_free_plan_used';

            function getUsage() {
                const raw = localStorage.getItem(STORAGE_KEY);
                return raw !== null ? parseInt(raw, 10) : 4;
            }

            function setUsage(val) {
                const clamped = Math.min(10, Math.max(0, val));
                localStorage.setItem(STORAGE_KEY, clamped.toString());
                updateUI();
            }

            function updateUI() {
                const used = getUsage();
                const counter = document.getElementById('free-plan-counter');
                const bar = document.getElementById('free-plan-bar');
                if (counter) counter.textContent = `${used}/10 msgs used`;
                if (bar) bar.style.width = `${(used / 10) * 100}%`;
            }

            window.incrementFreePlanUsage = function () {
                const used = getUsage();
                if (used < 10) {
                    setUsage(used + 1);
                }
            };

            const upgradeBtn = document.getElementById('btn-upgrade-plan');
            if (upgradeBtn) {
                upgradeBtn.addEventListener('click', (e) => {
                    e.preventDefault();
                    if (typeof showStudioToast === 'function') {
                        showStudioToast('Upgrade feature coming soon!');
                    } else {
                        alert('Upgrade feature coming soon!');
                    }
                });
            }

            updateUI();
        }

        // ─── PROJECTS MODULE (CRUD WITH LOCALSTORAGE & PROJECT DETAIL CHAT) ───
        const PROJECTS_STORAGE_KEY = 'mestrio_projects_v1';

        function getProjectModelStorageKey(projectId) {
            return 'project_model_' + projectId;
        }

        function getProjectSelectedModel(projectId) {
            if (!projectId) return (typeof chatState !== 'undefined' && chatState.selectedModel) ? chatState.selectedModel : 'mahi-engine';
            try {
                const val = localStorage.getItem(getProjectModelStorageKey(projectId));
                if (!val || val === 'Auto') return 'mahi-engine';
                const isPro = typeof window.isUserPro === 'function' ? window.isUserPro() : false;
                const target = AVAILABLE_MODELS.find(m => m.id === val || m.name === val);
                if (!isPro && target && target.id !== 'mahi-engine' && !target.isDefault) {
                    return 'mahi-engine';
                }
                return target ? target.id : val;
            } catch (e) {
                return 'mahi-engine';
            }
        }

        function setProjectSelectedModel(projectId, modelId) {
            if (!projectId) return;
            const isPro = typeof window.isUserPro === 'function' ? window.isUserPro() : false;
            const target = AVAILABLE_MODELS.find(m => m.id === modelId || m.name === modelId);
            if (!isPro && target && target.id !== 'mahi-engine' && !target.isDefault) {
                return;
            }
            try {
                localStorage.setItem(getProjectModelStorageKey(projectId), modelId);
            } catch (e) {
                console.warn('Failed to save project model to localStorage', e);
            }
        }

        function updateProjectModelUI(projectId) {
            const pid = projectId || currentActiveProjectId;
            const activeModelId = getProjectSelectedModel(pid);
            const model = AVAILABLE_MODELS.find(m =>
                m.id === activeModelId ||
                m.name === activeModelId ||
                ((activeModelId === 'mahi-engine' || activeModelId === 'Auto' || activeModelId === 'Mahi Engine (Standard)' || !activeModelId) && (m.id === 'mahi-engine' || m.isDefault))
            ) || AVAILABLE_MODELS[0];

            const isDefault = !model || model.id === 'mahi-engine' || model.name === 'Mahi Engine (Standard)' || Boolean(model.isDefault);

            const nameEl = document.getElementById('project-model-name');
            const iconEl = document.getElementById('project-model-icon');
            if (nameEl) {
                if (isDefault) {
                    nameEl.textContent = 'Model';
                    if (iconEl) {
                        iconEl.classList.add('hidden');
                        iconEl.classList.remove('flex', 'inline-flex');
                        iconEl.innerHTML = '';
                    }
                } else {
                    nameEl.textContent = model.name;
                    if (iconEl) {
                        iconEl.classList.remove('hidden');
                        iconEl.classList.add('flex', 'items-center', 'justify-center');
                        iconEl.innerHTML = getProviderIconSvg(model.provider, true, 'w-3.5 h-3.5', model.icon);
                    }
                }
            }

            renderProjectModelOptions(pid);
        }

        function renderProjectModelOptions(projectId) {
            const listEl = document.getElementById('project-model-options-list');
            if (!listEl) return;
            const pid = projectId || currentActiveProjectId;
            const currentSelected = getProjectSelectedModel(pid);

            const proBanner = document.getElementById('project-model-dropdown-pro-banner');
            if (proBanner) {
                const innerBanner = proBanner.querySelector('div') || proBanner;
                innerBanner.onclick = (e) => {
                    e.stopPropagation();
                    if (typeof window.onOpenUpgradeModal === 'function') window.onOpenUpgradeModal();
                    else if (typeof window.openUpgradeModal === 'function') window.openUpgradeModal();
                };
            }

            renderUnifiedModelOptionsList(listEl, currentSelected, (model, isSelected) => {
                const defaultModel = AVAILABLE_MODELS.find(m => m.isDefault || m.id === 'mahi-engine') || AVAILABLE_MODELS[0];
                if (isSelected) {
                    setProjectSelectedModel(pid, defaultModel.id);
                } else {
                    setProjectSelectedModel(pid, model.id);
                }
                updateProjectModelUI(pid);
                closeProjectModelDropdown();
            });
        }

