        // -- Landing search-pill state (mirrors Main Chat dropup state logic) --
        let projectLandingSearchMode = 'search'; // 'search' | 'deepResearch' | 'webSearch' | 'compare'

        function setProjectLandingSearchMode(modeKey) {
            projectLandingSearchMode = modeKey || 'search';
            const labelEl = document.getElementById('project-landing-search-pill-label');
            const iconEl = document.getElementById('project-landing-search-pill-icon');
            const chevron = document.getElementById('project-landing-search-chevron');
            const searchSvg = '<svg class="w-3.5 h-3.5 text-zinc-500 dark:text-zinc-400" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>';
            const webSvg = '<svg class="w-3.5 h-3.5 text-blue-500" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>';
            const researchSvg = '<svg class="w-3.5 h-3.5 text-indigo-500" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m10.065 12.493-6.18 1.318a.934.934 0 0 1-1.108-.702l-.537-2.15a1.07 1.07 0 0 1 .691-1.265l13.504-4.44"/><path d="m13.56 11.747 4.332-.924"/><path d="m16 21-3.105-6.21"/><path d="M16.485 5.94a2 2 0 0 1 1.455-2.425l1.09-.272a1 1 0 0 1 1.212.727l1.515 6.06a1 1 0 0 1-.727 1.213l-1.09.272a2 2 0 0 1-2.425-1.455z"/><path d="m6.158 8.633 1.114 4.456"/><path d="m8 21 3.105-6.21"/><circle cx="12" cy="13" r="2"/></svg>';
            const compareSvg = '<svg class="w-3.5 h-3.5 text-zinc-600 dark:text-zinc-300" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M12 3v18"/></svg>';
            const labels = { search: 'Search', deepResearch: 'Deep Research', webSearch: 'Web Search', compare: 'Compare' };
            const icons = { search: searchSvg, deepResearch: researchSvg, webSearch: webSvg, compare: compareSvg };

            if (labelEl) {
                labelEl.textContent = labels[projectLandingSearchMode] || 'Search';
                labelEl.className = 'text-zinc-800 dark:text-zinc-100 font-medium';
            }
            if (iconEl) {
                iconEl.innerHTML = icons[projectLandingSearchMode] || searchSvg;
                iconEl.className = 'flex items-center';
            }
            document.querySelectorAll('.project-landing-search-opt').forEach(function (btn) {
                const check = btn.querySelector('.project-landing-search-check');
                if (!check) return;
                const mode = btn.getAttribute('data-plmode');
                check.classList.toggle('hidden', mode !== projectLandingSearchMode);
            });
            const pill = document.getElementById('project-landing-search-pill');
            if (pill) {
                pill.className = 'inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border border-gray-200/90 dark:border-zinc-700 bg-white dark:bg-zinc-800 hover:bg-gray-50 dark:hover:bg-zinc-700/60 text-xs font-medium text-zinc-700 dark:text-zinc-200 shadow-2xs transition-colors cursor-pointer select-none focus:outline-none';
            }
            const input = document.getElementById('project-chat-input');
            if (input) {
                const placeholders = {
                    search: 'Ask anything in this project workspace...',
                    deepResearch: 'What would you like me to research in this workspace...',
                    webSearch: 'Search the web with AI in this workspace...',
                    compare: 'Ask multiple models in this workspace...'
                };
                input.placeholder = placeholders[projectLandingSearchMode] || 'Ask anything in this project workspace...';
            }
            // Sync legacy toggle state for sendProjectMessage
            if (currentActiveProjectId) {
                const toggles = getProjectToggles(currentActiveProjectId);
                toggles.webSearch = (projectLandingSearchMode === 'webSearch');
                toggles.deepResearch = (projectLandingSearchMode === 'deepResearch');
                saveProjectToggles(currentActiveProjectId, toggles);
            }
            // Compare mode toggle & right-hand model selector switch
            const modelWrapper = document.getElementById('project-model-selector-wrapper');
            const compareWrapper = document.getElementById('project-landing-compare-dropdown-wrapper');
            if (projectLandingSearchMode === 'compare') {
                if (modelWrapper) modelWrapper.classList.add('hidden');
                if (compareWrapper) compareWrapper.classList.remove('hidden');
                if (!chatState.compareModels || chatState.compareModels.length < 2) {
                    const currentModel = (typeof getProjectSelectedModel === 'function' && currentActiveProjectId)
                        ? getProjectSelectedModel(currentActiveProjectId)
                        : (chatState.selectedModel || 'mahi-engine');
                    const canonicalCurrent = getCanonicalModelId(currentModel) || 'mahi-engine';
                    const partner = (canonicalCurrent === 'claude-4-5-haiku') ? 'gpt-4o-mini' : 'claude-4-5-haiku';
                    chatState.compareModels = Array.from(new Set([canonicalCurrent, partner]));
                } else {
                    chatState.compareModels = Array.from(new Set(chatState.compareModels.map(getCanonicalModelId).filter(Boolean)));
                }
                renderCompareModelChips();
                if (typeof setChatMode === 'function') {
                    setChatMode('compare');
                }
                const landingCountBtn = document.getElementById('project-landing-compare-count-btn');
                if (typeof toggleCompareModelsPopover === 'function') {
                    toggleCompareModelsPopover(landingCountBtn);
                }
            } else {
                if (compareWrapper) compareWrapper.classList.add('hidden');
                if (modelWrapper) modelWrapper.classList.remove('hidden');
                if (typeof closeCompareModelsPopover === 'function') {
                    closeCompareModelsPopover();
                }
            }
            const dd = document.getElementById('project-landing-search-dropdown');
            if (dd) dd.classList.add('hidden');
            if (chevron) chevron.style.transform = '';
        }

