        // Project Landing submit button & voice recognition helpers
        function updateProjectLandingSendBtn() {
            if (window.isGeneratingChatResponse) return;
            const input = document.getElementById('project-chat-input');
            const sendBtn = document.getElementById('project-chat-send-btn');
            if (!sendBtn) return;
            const hasText = input && input.value.trim().length > 0;
            const hasAtt = projectLandingAttachments && projectLandingAttachments.length > 0;
            if (hasText || hasAtt) {
                sendBtn.classList.remove('hidden');
                sendBtn.classList.add('flex');
            } else {
                sendBtn.classList.add('hidden');
                sendBtn.classList.remove('flex');
            }
        }

        let projectLandingVoiceRecording = false;
        let projectLandingRecognitionInstance = null;

        function updateProjectLandingMicUI(listening) {
            const micBtn = document.getElementById('project-mic-btn');
            const voiceControls = document.getElementById('project-voice-active-controls');
            const sendBtn = document.getElementById('project-chat-send-btn');
            const chatInput = document.getElementById('project-chat-input');

            if (listening) {
                if (micBtn) micBtn.classList.add('hidden');
                if (voiceControls) {
                    voiceControls.classList.remove('hidden');
                    voiceControls.classList.add('flex');
                }
                if (sendBtn) {
                    sendBtn.classList.add('hidden');
                    sendBtn.classList.remove('flex');
                }
                if (chatInput) {
                    chatInput.placeholder = 'Listening...';
                }
            } else {
                if (voiceControls) {
                    voiceControls.classList.add('hidden');
                    voiceControls.classList.remove('flex');
                }
                if (micBtn) {
                    micBtn.classList.remove('hidden');
                }
                if (chatInput) {
                    const placeholders = {
                        search: 'Ask anything in this project workspace...',
                        deepResearch: 'What would you like me to research in this workspace...',
                        webSearch: 'Search the web with AI in this workspace...',
                        compare: 'Ask multiple models in this workspace...'
                    };
                    chatInput.placeholder = placeholders[projectLandingSearchMode] || 'Ask anything in this project workspace...';
                }
                updateProjectLandingSendBtn();
            }
        }

        function toggleProjectSpeechRecognition() {
            if (projectLandingVoiceRecording) {
                stopProjectSpeechRecognition();
            } else {
                startProjectSpeechRecognition();
            }
        }

        function startProjectSpeechRecognition() {
            const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
            if (!SpeechRecognition) {
                const toast = document.getElementById('project-mic-toast');
                if (toast) {
                    toast.classList.remove('hidden');
                    setTimeout(() => toast.classList.add('hidden'), 2500);
                } else if (typeof showStudioToast === 'function') {
                    showStudioToast('Voice input is not supported in this browser');
                }
                return;
            }

            try {
                if (!projectLandingRecognitionInstance) {
                    projectLandingRecognitionInstance = new SpeechRecognition();
                    projectLandingRecognitionInstance.continuous = true;
                    projectLandingRecognitionInstance.interimResults = true;
                    projectLandingRecognitionInstance.lang = navigator.language || 'en-US';

                    projectLandingRecognitionInstance.onstart = () => {
                        projectLandingVoiceRecording = true;
                        updateProjectLandingMicUI(true);
                    };

                    projectLandingRecognitionInstance.onresult = (event) => {
                        let finalTranscript = '';
                        let interimTranscript = '';
                        for (let i = 0; i < event.results.length; ++i) {
                            if (event.results[i].isFinal) finalTranscript += event.results[i][0].transcript;
                            else interimTranscript += event.results[i][0].transcript;
                        }
                        const input = document.getElementById('project-chat-input');
                        if (input) {
                            input.value = finalTranscript || interimTranscript;
                            updateProjectLandingSendBtn();
                        }
                    };

                    projectLandingRecognitionInstance.onerror = () => {
                        stopProjectSpeechRecognition();
                    };

                    projectLandingRecognitionInstance.onend = () => {
                        projectLandingVoiceRecording = false;
                        updateProjectLandingMicUI(false);
                    };
                }
                projectLandingRecognitionInstance.start();
            } catch (e) {
                stopProjectSpeechRecognition();
            }
        }

        function stopProjectSpeechRecognition() {
            if (projectLandingRecognitionInstance) {
                try {
                    projectLandingRecognitionInstance.stop();
                } catch (e) { }
            }
            projectLandingVoiceRecording = false;
            updateProjectLandingMicUI(false);
        }

        function cancelProjectVoiceSearch() {
            stopProjectSpeechRecognition();
            const input = document.getElementById('project-chat-input');
            if (input) {
                input.value = '';
                updateProjectLandingSendBtn();
            }
        }

        function confirmProjectVoiceSearch() {
            stopProjectSpeechRecognition();
            const input = document.getElementById('project-chat-input');
            if (input && input.value.trim().length > 0) {
                sendProjectMessage();
            }
        }

        window.setProjectLandingSearchMode = setProjectLandingSearchMode;
        window.closeProjectLandingSearchDropdown = closeProjectLandingSearchDropdown;
        window.toggleProjectLandingSearchDropdown = toggleProjectLandingSearchDropdown;
        window.updateProjectLandingSendBtn = updateProjectLandingSendBtn;

        window.setProjectLandingSearchMode = setProjectLandingSearchMode;
        window.closeProjectLandingSearchDropdown = closeProjectLandingSearchDropdown;

        // ============================================================
        // PROJECT INSTRUCTIONS PANEL MODULE (Website Theme Colors)
        // ============================================================
        const PROJECT_FILES_PREFIX = 'project_files_';
        const PROJECT_MEMORY_PREFIX = 'project_memory_';

        function getProjectFiles(projectId) {
            if (!projectId) return [];
            try {
                const raw = localStorage.getItem(PROJECT_FILES_PREFIX + projectId);
                if (raw) {
                    const parsed = JSON.parse(raw);
                    if (Array.isArray(parsed)) return parsed;
                }
            } catch (e) {
                console.warn('Failed to parse project files', e);
            }
            return [];
        }

        function saveProjectFiles(projectId, files) {
            if (!projectId) return;
            try {
                localStorage.setItem(PROJECT_FILES_PREFIX + projectId, JSON.stringify(files));
            } catch (e) {
                console.warn('Failed to save project files', e);
            }
        }

        function formatProjectFileSize(bytes) {
            if (!bytes || bytes === 0) return '0 B';
            const k = 1024;
            const sizes = ['B', 'KB', 'MB', 'GB'];
            const i = Math.floor(Math.log(bytes) / Math.log(k));
            return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
        }

        // In-memory file blob store for uploaded project files
        const projectFileBlobStore = new Map();

        function getMimeTypeForFile(file) {
            if (!file) return 'application/octet-stream';
            if (file.type && file.type !== 'file' && file.type !== 'application/octet-stream') {
                return file.type;
            }
            const name = (file.name || '').toLowerCase();
            if (name.endsWith('.pdf')) return 'application/pdf';
            if (name.endsWith('.txt')) return 'text/plain;charset=utf-8';
            if (name.endsWith('.md')) return 'text/plain;charset=utf-8';
            if (name.endsWith('.json')) return 'application/json';
            if (name.endsWith('.js') || name.endsWith('.ts')) return 'text/plain;charset=utf-8';
            if (name.endsWith('.html') || name.endsWith('.htm')) return 'text/html;charset=utf-8';
            if (name.endsWith('.css')) return 'text/css;charset=utf-8';
            if (name.endsWith('.csv')) return 'text/csv;charset=utf-8';
            if (name.endsWith('.png')) return 'image/png';
            if (name.endsWith('.jpg') || name.endsWith('.jpeg')) return 'image/jpeg';
            if (name.endsWith('.gif')) return 'image/gif';
            if (name.endsWith('.svg')) return 'image/svg+xml';
            if (name.endsWith('.webp')) return 'image/webp';
            if (name.endsWith('.doc')) return 'application/msword';
            if (name.endsWith('.docx')) return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
            if (name.endsWith('.zip')) return 'application/zip';
            return file.type || 'application/octet-stream';
        }

        function dataUrlToBlob(dataUrl, mimeType) {
            try {
                if (!dataUrl || typeof dataUrl !== 'string' || !dataUrl.includes(',')) return null;
                const parts = dataUrl.split(',');
                const mimeMatch = parts[0].match(/:(.*?);/);
                const mime = mimeType || (mimeMatch ? mimeMatch[1] : 'application/octet-stream');
                const bstr = atob(parts[1]);
                let n = bstr.length;
                const u8arr = new Uint8Array(n);
                while (n--) {
                    u8arr[n] = bstr.charCodeAt(n);
                }
                return new Blob([u8arr], { type: mime });
            } catch (e) {
                console.warn('Error converting dataUrl to Blob:', e);
                return null;
            }
        }

        function getBlobForProjectFile(file) {
            if (!file) return null;
            if (projectFileBlobStore.has(file.id)) {
                return projectFileBlobStore.get(file.id);
            }
            if (file.file instanceof Blob) {
                return file.file;
            }
            const mime = getMimeTypeForFile(file);
            if (file.dataUrl) {
                const blob = dataUrlToBlob(file.dataUrl, mime);
                if (blob) {
                    projectFileBlobStore.set(file.id, blob);
                    return blob;
                }
            }
            const fallbackText = file.content || `[Project File: ${file.name}]\nSize: ${file.sizeStr || formatProjectFileSize(file.size)}\nUploaded: ${file.uploadedAt || 'N/A'}`;
            return new Blob([fallbackText], { type: 'text/plain;charset=utf-8' });
        }

        let currentlyPreviewedProjectFile = null;
        let activeProjectPreviewBlobUrl = null;

        function closeProjectFilePreview() {
            const modal = document.getElementById('project-file-preview-modal');
            if (modal) modal.classList.add('hidden');
            if (activeProjectPreviewBlobUrl) {
                URL.revokeObjectURL(activeProjectPreviewBlobUrl);
                activeProjectPreviewBlobUrl = null;
            }
            currentlyPreviewedProjectFile = null;
        }

        function initProjectFilePreviewModal() {
            const modal = document.getElementById('project-file-preview-modal');
            const closeBtn = document.getElementById('proj-preview-close-btn');
            const downloadBtn = document.getElementById('proj-preview-download-btn');

            closeBtn?.addEventListener('click', (e) => {
                e.stopPropagation();
                closeProjectFilePreview();
            });

            modal?.addEventListener('click', (e) => {
                if (e.target === modal) {
                    closeProjectFilePreview();
                }
            });

            downloadBtn?.addEventListener('click', (e) => {
                e.stopPropagation();
                if (currentlyPreviewedProjectFile) {
                    downloadProjectFile(currentlyPreviewedProjectFile);
                }
            });
        }

        function openProjectFilePreview(file) {
            if (!file) return;
            currentlyPreviewedProjectFile = file;

            if (activeProjectPreviewBlobUrl) {
                URL.revokeObjectURL(activeProjectPreviewBlobUrl);
                activeProjectPreviewBlobUrl = null;
            }

            const modal = document.getElementById('project-file-preview-modal');
            const titleEl = document.getElementById('proj-preview-title');
            const badgeEl = document.getElementById('proj-preview-badge');
            const metaEl = document.getElementById('proj-preview-meta');
            const iconEl = document.getElementById('proj-preview-icon');
            const bodyEl = document.getElementById('proj-preview-body');

            if (!modal || !bodyEl) return;

            const name = file.name || 'Untitled File';
            const ext = (name.split('.').pop() || 'FILE').toUpperCase();
            const mime = getMimeTypeForFile(file);

            if (titleEl) titleEl.textContent = name;
            if (badgeEl) badgeEl.textContent = ext;
            if (metaEl) {
                const sizeStr = file.sizeStr || formatProjectFileSize(file.size);
                const dateStr = file.uploadedAt ? formatLibraryDate(file.uploadedAt) : 'Project File';
                metaEl.textContent = [sizeStr, dateStr].filter(Boolean).join(' • ');
            }

            const isImage = ['PNG', 'JPG', 'JPEG', 'WEBP', 'GIF', 'SVG', 'AVIF'].includes(ext) || (mime && mime.startsWith('image/'));
            const isPdf = ext === 'PDF' || mime === 'application/pdf';
            const isTextOrCode = ['TXT', 'MD', 'JS', 'TS', 'JSON', 'CSS', 'HTML', 'PY', 'CSV', 'XML', 'YAML', 'YML', 'SQL', 'SH'].includes(ext) || (mime && mime.startsWith('text/')) || file.content;

            if (iconEl) {
                if (isImage) {
                    iconEl.innerHTML = '<i data-lucide="image" class="w-5 h-5 text-emerald-600"></i>';
                    iconEl.className = 'w-10 h-10 rounded-xl bg-emerald-50 flex items-center justify-center shrink-0';
                } else if (isPdf) {
                    iconEl.innerHTML = '<i data-lucide="file-text" class="w-5 h-5 text-red-600"></i>';
                    iconEl.className = 'w-10 h-10 rounded-xl bg-red-50 flex items-center justify-center shrink-0';
                } else if (isTextOrCode) {
                    iconEl.innerHTML = '<i data-lucide="code-2" class="w-5 h-5 text-purple-600"></i>';
                    iconEl.className = 'w-10 h-10 rounded-xl bg-purple-50 flex items-center justify-center shrink-0';
                } else {
                    iconEl.innerHTML = '<i data-lucide="file-text" class="w-5 h-5 text-blue-600"></i>';
                    iconEl.className = 'w-10 h-10 rounded-xl bg-blue-50 flex items-center justify-center shrink-0';
                }
            }

            if (isImage) {
                let imgUrl = file.dataUrl || file.url;
                if (!imgUrl) {
                    const blob = getBlobForProjectFile(file);
                    if (blob) {
                        activeProjectPreviewBlobUrl = URL.createObjectURL(blob);
                        imgUrl = activeProjectPreviewBlobUrl;
                    }
                }
                bodyEl.innerHTML = `
                    <div class="w-full flex items-center justify-center py-2">
                        <img src="${imgUrl || ''}" alt="${escapeHtml(name)}" class="max-h-[65vh] object-contain rounded-lg mx-auto shadow-md" />
                    </div>
                `;
            } else if (isPdf) {
                let pdfUrl = file.url;
                if (!pdfUrl) {
                    const blob = getBlobForProjectFile(file);
                    if (blob) {
                        const pdfBlob = new Blob([blob], { type: 'application/pdf' });
                        activeProjectPreviewBlobUrl = URL.createObjectURL(pdfBlob);
                        pdfUrl = activeProjectPreviewBlobUrl;
                    } else if (file.dataUrl) {
                        pdfUrl = file.dataUrl;
                    }
                }
                bodyEl.innerHTML = `
                    <div class="w-full h-full flex flex-col items-center justify-center">
                        <iframe src="${pdfUrl || ''}" class="w-full h-[65vh] rounded-lg border border-neutral-100 bg-white" title="${escapeHtml(name)}"></iframe>
                    </div>
                `;
            } else if (isTextOrCode) {
                if (file.content) {
                    bodyEl.innerHTML = `
                        <div class="w-full max-h-[65vh] flex flex-col">
                            <pre class="bg-neutral-50 p-4 rounded-xl font-mono text-sm text-neutral-800 overflow-y-auto max-h-[60vh] whitespace-pre-wrap leading-relaxed border border-neutral-200/80 shadow-2xs">${escapeHtml(file.content)}</pre>
                        </div>
                    `;
                } else {
                    bodyEl.innerHTML = `<div class="w-full flex items-center justify-center p-8"><span class="text-xs text-slate-400">Loading document preview...</span></div>`;
                    const blob = getBlobForProjectFile(file);
                    if (blob) {
                        const reader = new FileReader();
                        reader.onload = (e) => {
                            const text = e.target.result || '';
                            bodyEl.innerHTML = `
                                <div class="w-full max-h-[65vh] flex flex-col">
                                    <pre class="bg-neutral-50 p-4 rounded-xl font-mono text-sm text-neutral-800 overflow-y-auto max-h-[60vh] whitespace-pre-wrap leading-relaxed border border-neutral-200/80 shadow-2xs">${escapeHtml(text)}</pre>
                                </div>
                            `;
                        };
                        reader.onerror = () => {
                            bodyEl.innerHTML = `
                                <div class="w-full max-h-[65vh] flex flex-col">
                                    <pre class="bg-neutral-50 p-4 rounded-xl font-mono text-sm text-neutral-800 overflow-y-auto max-h-[60vh] whitespace-pre-wrap leading-relaxed border border-neutral-200/80 shadow-2xs">[Text preview could not be loaded]</pre>
                                </div>
                            `;
                        };
                        reader.readAsText(blob);
                    } else {
                        bodyEl.innerHTML = `
                            <div class="w-full max-h-[65vh] flex flex-col">
                                <pre class="bg-neutral-50 p-4 rounded-xl font-mono text-sm text-neutral-800 overflow-y-auto max-h-[60vh] whitespace-pre-wrap leading-relaxed border border-neutral-200/80 shadow-2xs">[No text content available]</pre>
                            </div>
                        `;
                    }
                }
            } else {
                // DOCX / Other Formats
                bodyEl.innerHTML = `
                    <div class="flex flex-col items-center justify-center text-center p-8 max-w-md mx-auto">
                        <div class="w-20 h-20 rounded-2xl bg-blue-50 text-blue-600 flex items-center justify-center mb-4 shadow-2xs">
                            <i data-lucide="file-text" class="w-10 h-10"></i>
                        </div>
                        <h4 class="text-base font-semibold text-slate-800 break-all mb-1">${escapeHtml(name)}</h4>
                        <p class="text-xs text-slate-400 mb-6">${file.sizeStr || formatProjectFileSize(file.size)} • ${ext} Document</p>
                        <button type="button" class="proj-preview-cta-download flex items-center gap-2 px-5 py-2.5 rounded-xl bg-slate-900 hover:bg-slate-800 text-white text-xs font-semibold shadow-xs transition-all cursor-pointer">
                            <i data-lucide="download" class="w-4 h-4"></i>
                            <span>Download & Open Document</span>
                        </button>
                    </div>
                `;
                bodyEl.querySelector('.proj-preview-cta-download')?.addEventListener('click', (e) => {
                    e.stopPropagation();
                    downloadProjectFile(file);
                });
            }

            modal.classList.remove('hidden');
            if (window.lucide) window.lucide.createIcons();
        }

        function downloadProjectFile(file) {
            if (!file) return;

            if (file.url) {
                const a = document.createElement('a');
                a.href = file.url;
                a.download = file.name || 'document';
                a.target = '_blank';
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                return;
            }

            const blob = getBlobForProjectFile(file);
            const fileUrl = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = fileUrl;
            a.download = file.name || 'document';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            setTimeout(() => URL.revokeObjectURL(fileUrl), 10000);
        }

        function renderProjectFiles(projectId) {
            const listEl = document.getElementById('project-uploaded-files-list');
            if (!listEl) return;
            listEl.innerHTML = '';
            const files = getProjectFiles(projectId);

            if (files.length === 0) {
                return;
            }

            files.forEach(file => {
                const chip = document.createElement('div');
                chip.className = 'flex items-center justify-between p-2 rounded-xl bg-slate-50/70 border border-slate-200/80 hover:border-blue-300 hover:bg-blue-50/30 transition-all text-xs text-slate-800 shadow-2xs group cursor-pointer';
                chip.innerHTML = `
                    <div class="btn-preview-project-file flex items-center gap-2 min-w-0 pr-2 cursor-pointer flex-1" title="Click to preview ${escapeHtml(file.name)}">
                        <i data-lucide="file-text" class="w-3.5 h-3.5 text-blue-500 shrink-0"></i>
                        <span class="truncate font-medium text-[11px] text-slate-800 group-hover:text-blue-600 transition-colors">${escapeHtml(file.name)}</span>
                        <span class="text-[10px] text-slate-400 shrink-0">(${escapeHtml(file.sizeStr || formatProjectFileSize(file.size))})</span>
                    </div>
                    <div class="flex items-center gap-0.5 shrink-0">
                        <button type="button" class="btn-download-project-file p-1 rounded-md text-slate-400 hover:text-blue-600 hover:bg-blue-50 transition-colors cursor-pointer" title="Download file" data-file-id="${escapeHtml(file.id)}">
                            <i data-lucide="download" class="w-3.5 h-3.5 pointer-events-none"></i>
                        </button>
                        <button type="button" class="btn-delete-project-file p-1 rounded-md text-slate-400 hover:text-red-500 hover:bg-red-50 transition-colors cursor-pointer" title="Delete file" data-file-id="${escapeHtml(file.id)}">
                            <i data-lucide="x" class="w-3.5 h-3.5 pointer-events-none"></i>
                        </button>
                    </div>
                `;

                chip.addEventListener('click', (e) => {
                    if (e.target.closest('.btn-download-project-file, .btn-delete-project-file')) return;
                    openProjectFilePreview(file);
                });

                chip.querySelector('.btn-preview-project-file')?.addEventListener('click', (e) => {
                    e.stopPropagation();
                    openProjectFilePreview(file);
                });

                chip.querySelector('.btn-download-project-file')?.addEventListener('click', (e) => {
                    e.stopPropagation();
                    downloadProjectFile(file);
                });

                chip.querySelector('.btn-delete-project-file')?.addEventListener('click', (e) => {
                    e.stopPropagation();
                    deleteProjectFile(projectId, file.id);
                });

                listEl.appendChild(chip);
            });

            if (window.lucide) window.lucide.createIcons();
        }

        function handleAddProjectFiles(projectId, fileList) {
            if (!projectId || !fileList || fileList.length === 0) return;
            const currentFiles = getProjectFiles(projectId);
            const filesArr = Array.from(fileList);
            let pending = filesArr.length;

            filesArr.forEach(f => {
                const fileId = 'pfile_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7);
                const mime = f.type || getMimeTypeForFile(f);

                // Keep actual File / Blob reference in state
                projectFileBlobStore.set(fileId, f);

                const fileObj = {
                    id: fileId,
                    name: f.name,
                    size: f.size,
                    sizeStr: formatProjectFileSize(f.size),
                    type: mime,
                    uploadedAt: new Date().toISOString(),
                    dataUrl: ''
                };

                if (f.size <= 4 * 1024 * 1024) {
                    const reader = new FileReader();
                    reader.onload = (e) => {
                        fileObj.dataUrl = e.target.result;
                        currentFiles.push(fileObj);
                        pending--;
                        if (pending === 0) {
                            saveProjectFiles(projectId, currentFiles);
                            renderProjectFiles(projectId);
                            if (typeof showStudioToast === 'function') {
                                showStudioToast(`${filesArr.length} file(s) attached to project`);
                            }
                        }
                    };
                    reader.onerror = () => {
                        currentFiles.push(fileObj);
                        pending--;
                        if (pending === 0) {
                            saveProjectFiles(projectId, currentFiles);
                            renderProjectFiles(projectId);
                            if (typeof showStudioToast === 'function') {
                                showStudioToast(`${filesArr.length} file(s) attached to project`);
                            }
                        }
                    };
                    reader.readAsDataURL(f);
                } else {
                    currentFiles.push(fileObj);
                    pending--;
                    if (pending === 0) {
                        saveProjectFiles(projectId, currentFiles);
                        renderProjectFiles(projectId);
                        if (typeof showStudioToast === 'function') {
                            showStudioToast(`${filesArr.length} file(s) attached to project`);
                        }
                    }
                }
            });
        }

        function deleteProjectFile(projectId, fileId) {
            if (!projectId || !fileId) return;
            if (currentlyPreviewedProjectFile && currentlyPreviewedProjectFile.id === fileId) {
                closeProjectFilePreview();
            }
            projectFileBlobStore.delete(fileId);
            let files = getProjectFiles(projectId);
            files = files.filter(f => f.id !== fileId);
            saveProjectFiles(projectId, files);
            renderProjectFiles(projectId);
            if (typeof showStudioToast === 'function') {
                showStudioToast('File removed');
            }
        }

        function initProjectFilesDropzone() {
            const dropzone = document.getElementById('project-files-dropzone');
            const fileInput = document.getElementById('project-panel-file-input');

            if (!dropzone || !fileInput) return;

            dropzone.addEventListener('click', () => {
                fileInput.click();
            });

            fileInput.addEventListener('change', (e) => {
                const files = e.target.files;
                if (files && files.length > 0 && currentActiveProjectId) {
                    handleAddProjectFiles(currentActiveProjectId, files);
                }
                e.target.value = '';
            });

            ['dragenter', 'dragover'].forEach(eventName => {
                dropzone.addEventListener(eventName, (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    dropzone.classList.remove('border-[#E5E7EB]', 'bg-[#F9FAFB]');
                    dropzone.classList.add('border-[#2563EB]', 'bg-[#EFF6FF]');
                });
            });

            ['dragleave', 'drop'].forEach(eventName => {
                dropzone.addEventListener(eventName, (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    dropzone.classList.remove('border-[#2563EB]', 'bg-[#EFF6FF]');
                    dropzone.classList.add('border-[#E5E7EB]', 'bg-[#F9FAFB]');
                });
            });

            dropzone.addEventListener('drop', (e) => {
                const dt = e.dataTransfer;
                const files = dt?.files;
                if (files && files.length > 0 && currentActiveProjectId) {
                    handleAddProjectFiles(currentActiveProjectId, files);
                }
            });
        }

        function getProjectMemory(projectId) {
            if (!projectId) return false;
            try {
                return localStorage.getItem(PROJECT_MEMORY_PREFIX + projectId) === 'true';
            } catch (e) {
                return false;
            }
        }

        function setProjectMemory(projectId, isEnabled) {
            if (!projectId) return;
            try {
                localStorage.setItem(PROJECT_MEMORY_PREFIX + projectId, isEnabled ? 'true' : 'false');
            } catch (e) {
                console.warn('Failed to save project memory state', e);
            }
        }

        function updateProjectMemoryUI(projectId) {
            const isEnabled = getProjectMemory(projectId);
            const toggleBtn = document.getElementById('project-account-memory-toggle');
            const dot = document.getElementById('project-memory-toggle-dot');
            const subtext = document.getElementById('project-account-memory-subtext');

            if (toggleBtn) {
                toggleBtn.setAttribute('aria-checked', isEnabled ? 'true' : 'false');
                if (isEnabled) {
                    toggleBtn.className = 'relative inline-flex h-5 w-9 shrink-0 cursor-pointer rounded-full border-2 border-transparent bg-[#2563EB] transition-colors duration-200 ease-in-out focus:outline-none';
                } else {
                    toggleBtn.className = 'relative inline-flex h-5 w-9 shrink-0 cursor-pointer rounded-full border-2 border-transparent bg-[#E5E7EB] transition-colors duration-200 ease-in-out focus:outline-none';
                }
            }
            if (dot) {
                if (isEnabled) {
                    dot.className = 'pointer-events-none inline-block h-4 w-4 transform rounded-full bg-white shadow-xs ring-0 transition duration-200 ease-in-out translate-x-4';
                } else {
                    dot.className = 'pointer-events-none inline-block h-4 w-4 transform rounded-full bg-white shadow-xs ring-0 transition duration-200 ease-in-out translate-x-0';
                }
            }
            if (subtext) {
                subtext.textContent = isEnabled
                    ? 'Account memory is on — this project will remember context across chats.'
                    : 'Account memory is off — turning this on enables it for your account too.';
            }
        }

        // Requirement 5: Silent Account Memory Toggle (toast removed)
        function toggleProjectMemory() {
            if (!currentActiveProjectId) return;
            const current = getProjectMemory(currentActiveProjectId);
            const next = !current;
            setProjectMemory(currentActiveProjectId, next);
            updateProjectMemoryUI(currentActiveProjectId);
        }

        function initProjectMemoryUI() {
            const memoryToggle = document.getElementById('project-account-memory-toggle');
            memoryToggle?.addEventListener('click', (e) => {
                e.stopPropagation();
                toggleProjectMemory();
            });
        }

        function initProjectGuidelinesUI() {
            const editBtn = document.getElementById('btn-edit-instructions');
            const saveBtn = document.getElementById('btn-save-instructions');
            const textarea = document.getElementById('project-instructions-textarea');

            editBtn?.addEventListener('click', (e) => {
                e.stopPropagation();
                if (!textarea) return;
                textarea.removeAttribute('readonly');
                textarea.focus();
                editBtn.classList.add('hidden');
                saveBtn?.classList.remove('hidden');
            });

            saveBtn?.addEventListener('click', (e) => {
                e.stopPropagation();
                if (!textarea || !currentActiveProjectId) return;
                const newInstructions = textarea.value.trim();
                textarea.setAttribute('readonly', 'true');
                saveBtn.classList.add('hidden');
                editBtn?.classList.remove('hidden');

                // Persist to project object in localStorage
                const projects = loadProjectsFromStorage();
                const project = projects.find(p => p.id === currentActiveProjectId);
                if (project) {
                    project.instructions = newInstructions;
                    saveProjectsToStorage(projects);
                    if (typeof showStudioToast === 'function') {
                        showStudioToast('Project guidelines saved');
                    }
                }
            });
        }

        window.getProjectFiles = getProjectFiles;
        window.saveProjectFiles = saveProjectFiles;
        window.renderProjectFiles = renderProjectFiles;
        window.getProjectMemory = getProjectMemory;
        window.setProjectMemory = setProjectMemory;
        window.updateProjectMemoryUI = updateProjectMemoryUI;

        let projectLandingAttachments = [];
        let projectActiveAttachments = [];

        function renderProjectComposerChips(targetType) {
            const isLanding = targetType === 'landing';
            const containerId = isLanding ? 'project-composer-chips' : 'project-active-composer-chips';
            const container = document.getElementById(containerId);
            if (!container) return;

            const attachments = isLanding ? projectLandingAttachments : projectActiveAttachments;
            container.innerHTML = '';

            if (!attachments || attachments.length === 0) {
                container.classList.add('hidden');
                if (isLanding && typeof updateProjectLandingSendBtn === 'function') {
                    updateProjectLandingSendBtn();
                }
                return;
            }

            container.classList.remove('hidden');

            attachments.forEach(att => {
                const card = createGeminiAttachmentCard(att, {
                    onRemove: (id) => removeProjectAttachment(targetType, id),
                    onSave: () => renderProjectComposerChips(targetType)
                });
                container.appendChild(card);
            });

            if (isLanding && typeof updateProjectLandingSendBtn === 'function') {
                updateProjectLandingSendBtn();
            }
        }

        function removeProjectAttachment(targetType, attId) {
            if (targetType === 'landing') {
                projectLandingAttachments = projectLandingAttachments.filter(a => a.id !== attId);
            } else {
                projectActiveAttachments = projectActiveAttachments.filter(a => a.id !== attId);
            }
            renderProjectComposerChips(targetType);
        }

        function processProjectFileInput(targetType, fileList, forceImage = false) {
            if (!fileList || fileList.length === 0) return;
            const files = Array.from(fileList);

            files.forEach(file => {
                const ext = file.name && file.name.includes('.') ? file.name.split('.').pop().toLowerCase() : '';
                const isImg = forceImage || (file.type && file.type.startsWith('image/')) || ['png', 'jpg', 'jpeg', 'webp', 'gif', 'svg', 'bmp', 'ico'].includes(ext);
                const attId = 'att_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7);
                const attObj = {
                    id: attId,
                    name: file.name,
                    size: file.size,
                    sizeStr: formatProjectFileSize(file.size),
                    type: file.type || (isImg ? 'image/png' : ext),
                    extension: ext,
                    isImage: isImg,
                    dataUrl: '',
                    preview: '',
                    extractedContent: null,
                    _loading: true
                };

                // Push with skeleton loader
                if (targetType === 'landing') {
                    projectLandingAttachments.push(attObj);
                } else {
                    projectActiveAttachments.push(attObj);
                }
                renderProjectComposerChips(targetType);

                attObj._extractPromise = extractUniversalFile(file, attObj).then(() => {
                    attObj._loading = false;
                    renderProjectComposerChips(targetType);
                }).catch(err => {
                    console.warn('Project file extraction failed:', err);
                    attObj._loading = false;
                    renderProjectComposerChips(targetType);
                });
            });
        }

        function addProjectComposerChip(type, label, containerId = 'project-composer-chips') {
            const isLanding = containerId.indexOf('active') === -1;
            const targetType = isLanding ? 'landing' : 'active';
            const attId = 'att_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7);
            const attObj = {
                id: attId,
                name: label,
                size: 0,
                sizeStr: 'attached',
                type: type === 'image' ? 'image/png' : 'application/octet-stream',
                isImage: type === 'image',
                dataUrl: ''
            };
            if (targetType === 'landing') {
                projectLandingAttachments.push(attObj);
            } else {
                projectActiveAttachments.push(attObj);
            }
            renderProjectComposerChips(targetType);
        }

        function loadProjectsFromStorage() {
            try {
                const raw = localStorage.getItem(PROJECTS_STORAGE_KEY);
                if (raw !== null) {
                    const parsed = JSON.parse(raw);
                    if (Array.isArray(parsed) && parsed.length > 0) return parsed;
                }
            } catch (e) {
                console.warn('Failed to load projects from storage', e);
            }
            const initialProjects = [
                {
                    id: 'proj-demo-1',
                    name: 'Mahi Testing',
                    instructions: 'Test project for validating AI chat workflows and knowledge assets.',
                    createdAt: new Date(Date.now() - 3600000 * 48).toISOString(),
                    isPinned: true
                },
                {
                    id: 'proj-demo-2',
                    name: 'dfdf',
                    instructions: '',
                    createdAt: new Date(Date.now() - 3600000 * 72).toISOString(),
                    isPinned: false
                },
                {
                    id: 'proj-demo-3',
                    name: 'efds',
                    instructions: '',
                    createdAt: new Date(Date.now() - 3600000 * 96).toISOString(),
                    isPinned: false
                }
            ];
            try {
                localStorage.setItem(PROJECTS_STORAGE_KEY, JSON.stringify(initialProjects));
            } catch (e) { }
            return initialProjects;
        }

        function saveProjectsToStorage(projects) {
            try {
                localStorage.setItem(PROJECTS_STORAGE_KEY, JSON.stringify(projects));
            } catch (e) {
                console.warn('Failed to save projects to storage', e);
            }
        }

        // (currentActiveProjectId declared at top-level state declarations block)

        // Project Pinning Functions (Requirement 1)
        function updateProjectPinUI(projectId) {
            const pinBtn = document.getElementById('btn-project-pin');
            const pinIcon = document.getElementById('project-pin-icon');
            if (!pinBtn || !projectId) return;

            const projects = loadProjectsFromStorage();
            const project = projects.find(p => p.id === projectId);
            const isPinned = !!(project && project.isPinned);

            if (isPinned) {
                pinBtn.className = 'p-2 rounded-xl text-blue-600 bg-blue-50/80 border border-blue-200 shadow-2xs transition-colors cursor-pointer';
                pinBtn.setAttribute('title', 'Unpin project');
                if (pinIcon) pinIcon.classList.add('fill-blue-600');
            } else {
                pinBtn.className = 'p-2 rounded-xl text-slate-400 hover:text-blue-600 hover:bg-blue-50 transition-colors cursor-pointer border border-transparent hover:border-blue-100';
                pinBtn.setAttribute('title', 'Pin project');
                if (pinIcon) pinIcon.classList.remove('fill-blue-600');
            }
        }

        function toggleProjectPin(projectId) {
            if (!projectId) return;
            const projects = loadProjectsFromStorage();
            const project = projects.find(p => p.id === projectId);
            if (!project) return;
            project.isPinned = !project.isPinned;
            saveProjectsToStorage(projects);
            updateProjectPinUI(projectId);
            renderProjectsList();
            if (typeof showStudioToast === 'function') {
                showStudioToast(project.isPinned ? 'Project pinned' : 'Project unpinned');
            }
        }

        // Project Header 3-Dots Dropdown (Requirement 2)
        function toggleProjectHeaderDropdown() {
            const dropdown = document.getElementById('project-header-dropdown');
            if (!dropdown) return;
            dropdown.classList.toggle('hidden');
        }

        function closeProjectHeaderDropdown() {
            const dropdown = document.getElementById('project-header-dropdown');
            if (dropdown && !dropdown.classList.contains('hidden')) {
                dropdown.classList.add('hidden');
            }
        }

        function openEditProjectModal(projectId) {
            if (!projectId) return;
            const projects = loadProjectsFromStorage();
            const project = projects.find(p => p.id === projectId);
            if (!project) return;

            const modal = document.getElementById('project-edit-modal');
            const nameInput = document.getElementById('project-edit-name');
            const instructionsInput = document.getElementById('project-edit-instructions');

            if (nameInput) nameInput.value = project.name || '';
            if (instructionsInput) instructionsInput.value = project.instructions || '';

            if (modal) {
                modal.classList.remove('hidden');
                setTimeout(() => nameInput?.focus(), 60);
            }
            if (window.lucide) window.lucide.createIcons();
        }

        function closeEditProjectModal() {
            const modal = document.getElementById('project-edit-modal');
            if (modal) modal.classList.add('hidden');
        }

        function handleEditProjectSubmit(e) {
            e.preventDefault();
            if (!currentActiveProjectId) return;
            const nameInput = document.getElementById('project-edit-name');
            const instructionsInput = document.getElementById('project-edit-instructions');
            const newName = nameInput ? nameInput.value.trim() : '';
            const newInstructions = instructionsInput ? instructionsInput.value.trim() : '';
            if (!newName) return;

            const projects = loadProjectsFromStorage();
            const project = projects.find(p => p.id === currentActiveProjectId);
            if (!project) return;

            project.name = newName;
            project.instructions = newInstructions;
            saveProjectsToStorage(projects);

            const titleEl = document.getElementById('project-detail-title');
            if (titleEl) titleEl.textContent = newName;
            const bcProject = document.getElementById('breadcrumb-project-name');
            if (bcProject) bcProject.textContent = newName;

            const textarea = document.getElementById('project-instructions-textarea');
            if (textarea) textarea.value = newInstructions;

            closeEditProjectModal();
            if (typeof showStudioToast === 'function') {
                showStudioToast('Project updated');
            }
            renderProjectsList();
        }

        function renderProjectsList() {
            const projects = loadProjectsFromStorage();
            const emptyState = document.getElementById('projects-empty-state');
            const gridContainer = document.getElementById('projects-grid-container');
            const cardsGrid = document.getElementById('projects-cards-grid');
            const countBadge = document.getElementById('projects-count-badge');
            const listView = document.getElementById('projects-list-view');
            const detailView = document.getElementById('project-detail-view');
            const btnCreateHeader = document.getElementById('btn-create-project-header');

            if (listView) listView.classList.remove('hidden');
            if (detailView) detailView.classList.add('hidden');

            if (countBadge) countBadge.textContent = projects.length;

            if (!projects || projects.length === 0) {
                if (emptyState) emptyState.classList.remove('hidden');
                if (gridContainer) gridContainer.classList.add('hidden');
                if (cardsGrid) cardsGrid.innerHTML = '';
                if (btnCreateHeader) btnCreateHeader.classList.add('hidden');
                if (window.lucide) window.lucide.createIcons();
                return;
            }

            if (emptyState) emptyState.classList.add('hidden');
            if (gridContainer) gridContainer.classList.remove('hidden');
            if (btnCreateHeader) btnCreateHeader.classList.remove('hidden');

            if (!cardsGrid) return;
            cardsGrid.innerHTML = '';

            // Sort: pinned projects first, then by date descending
            const sortedProjects = [...projects].sort((a, b) => {
                if (!!a.isPinned !== !!b.isPinned) {
                    return a.isPinned ? -1 : 1;
                }
                return new Date(b.createdAt || 0) - new Date(a.createdAt || 0);
            });

            sortedProjects.forEach(project => {
                const card = document.createElement('div');
                card.className = 'group relative flex flex-col justify-between p-5 bg-white border border-neutral-200/90 shadow-xs hover:border-neutral-300 hover:shadow-sm focus:outline-none focus:ring-0 rounded-2xl transition-all duration-200 cursor-pointer';
                card.setAttribute('data-project-id', project.id);

                const msgCount = (project.messages && Array.isArray(project.messages)) ? project.messages.length : 0;
                const timeStr = formatTimeAgo(project.createdAt);
                const instructionsPreview = project.instructions
                    ? escapeHtml(project.instructions)
                    : '<span class="italic text-slate-400">No custom instructions specified.</span>';

                card.innerHTML = `
                    <div>
                        <div class="flex items-start justify-between gap-3 mb-3">
                            <div class="flex items-center gap-2.5 min-w-0">
                                <div class="w-9 h-9 rounded-xl ${project.isPinned ? 'bg-blue-100 text-blue-700 border border-blue-200' : 'bg-blue-50 text-blue-600'} flex items-center justify-center shrink-0 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                                    <i data-lucide="${project.isPinned ? 'pin' : 'folder'}" class="w-4 h-4 ${project.isPinned ? 'fill-blue-700' : ''}"></i>
                                </div>
                                <div class="min-w-0">
                                    <div class="flex items-center gap-1.5">
                                        <h3 class="text-sm font-semibold text-slate-900 truncate group-hover:text-blue-600 transition-colors">${escapeHtml(project.name)}</h3>
                                        ${project.isPinned ? '<span class="inline-flex items-center gap-0.5 px-1.5 py-0.2 rounded text-[10px] font-semibold bg-blue-50 text-blue-600 border border-blue-100/80 shrink-0">Pinned</span>' : ''}
                                    </div>
                                    <span class="text-[11px] text-slate-400">${timeStr}</span>
                                </div>
                            </div>
                            <button type="button" class="btn-delete-project p-1.5 rounded-lg text-slate-400 hover:text-red-600 hover:bg-red-50 transition-colors cursor-pointer shrink-0" title="Delete Project" data-delete-id="${escapeHtml(project.id)}">
                                <i data-lucide="trash-2" class="w-3.5 h-3.5 pointer-events-none"></i>
                            </button>
                        </div>
                        <div class="text-xs text-slate-600 bg-slate-50/80 p-2.5 rounded-xl border border-slate-100 line-clamp-2 leading-relaxed mb-4">
                            ${instructionsPreview}
                        </div>
                    </div>
                    <div class="flex items-center justify-between pt-3 border-t border-slate-100 text-xs text-slate-400">
                        <span class="inline-flex items-center gap-1">
                            <i data-lucide="message-square" class="w-3.5 h-3.5 text-slate-400"></i>
                            <span>${msgCount} message${msgCount === 1 ? '' : 's'}</span>
                        </span>
                        <span class="inline-flex items-center gap-1 text-blue-600 font-medium group-hover:translate-x-0.5 transition-transform">
                            <span>Open</span>
                            <i data-lucide="arrow-right" class="w-3.5 h-3.5"></i>
                        </span>
                    </div>
                `;

                const deleteBtn = card.querySelector('.btn-delete-project');
                if (deleteBtn) {
                    deleteBtn.addEventListener('click', (e) => {
                        e.stopPropagation();
                        showDeleteProjectConfirm(project.id, project.name);
                    });
                }

                card.addEventListener('click', () => {
                    openProjectDetail(project.id);
                });

                cardsGrid.appendChild(card);
            });

            if (window.lucide) window.lucide.createIcons();
        }

        let _pendingDeleteProjectId = null;

        function showDeleteProjectConfirm(projectId, projectName) {
            _pendingDeleteProjectId = projectId;
            const modal = document.getElementById('project-delete-confirm-modal');
            const nameEl = document.getElementById('project-delete-confirm-name');
            if (nameEl) nameEl.textContent = projectName || 'this project';
            if (modal) {
                modal.classList.remove('hidden');
                modal.style.display = 'flex';
            }
        }

        function closeDeleteProjectConfirm() {
            _pendingDeleteProjectId = null;
            const modal = document.getElementById('project-delete-confirm-modal');
            if (modal) {
                modal.classList.add('hidden');
                modal.style.display = 'none';
            }
        }

        function confirmDeleteProject() {
            if (!_pendingDeleteProjectId) return;
            deleteProject(_pendingDeleteProjectId);
            closeDeleteProjectConfirm();
        }

        (function () {
            const cancelBtn = document.getElementById('project-delete-cancel-btn');
            const confirmBtn = document.getElementById('project-delete-confirm-btn');
            const modal = document.getElementById('project-delete-confirm-modal');
            if (cancelBtn) cancelBtn.addEventListener('click', closeDeleteProjectConfirm);
            if (confirmBtn) confirmBtn.addEventListener('click', confirmDeleteProject);
            if (modal) modal.addEventListener('click', (e) => {
                if (e.target === modal) closeDeleteProjectConfirm();
            });
            if (window.lucide) window.lucide.createIcons();
        })();

        window.showDeleteProjectConfirm = showDeleteProjectConfirm;
        window.closeDeleteProjectConfirm = closeDeleteProjectConfirm;
        window.confirmDeleteProject = confirmDeleteProject;

        function deleteProject(projectId) {
            let projects = loadProjectsFromStorage();
            projects = projects.filter(p => p.id !== projectId);
            saveProjectsToStorage(projects);
            if (currentActiveProjectId === projectId) {
                currentActiveProjectId = null;
                currentActiveChatId = null;
                if (typeof switchWorkspace === 'function' && currentWorkspace !== 'projects') {
                    switchWorkspace('projects');
                }
            }
            renderProjectsList();
            if (typeof showStudioToast === 'function') {
                showStudioToast('Project deleted');
            }
        }

        function openCreateProjectModal() {
            const modal = document.getElementById('project-create-modal');
            const nameInput = document.getElementById('project-modal-name');
            const instructionsInput = document.getElementById('project-modal-instructions');
            if (modal) {
                modal.classList.remove('hidden');
                if (nameInput) {
                    nameInput.value = '';
                    setTimeout(() => nameInput.focus(), 60);
                }
                if (instructionsInput) {
                    instructionsInput.value = '';
                }
            }
            if (window.lucide) window.lucide.createIcons();
        }

        function closeCreateProjectModal() {
            const modal = document.getElementById('project-create-modal');
            if (modal) modal.classList.add('hidden');
        }

        function handleCreateProjectSubmit(e) {
            e.preventDefault();
            const nameInput = document.getElementById('project-modal-name');
            const instructionsInput = document.getElementById('project-modal-instructions');
            const name = nameInput ? nameInput.value.trim() : '';
            const instructions = instructionsInput ? instructionsInput.value.trim() : '';

            if (!name) {
                if (nameInput) nameInput.focus();
                return;
            }

            const newProject = {
                id: 'proj_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7),
                name: name,
                instructions: instructions,
                createdAt: new Date().toISOString(),
                messages: []
            };

            const projects = loadProjectsFromStorage();
            projects.unshift(newProject);
            saveProjectsToStorage(projects);

            closeCreateProjectModal();
            renderProjectsList();

            if (typeof showStudioToast === 'function') {
                showStudioToast(`Project "${newProject.name}" created!`);
            }
        }

        // ── Project Workspace State ────────────────────────────────────
        // (currentActiveChatId declared at top-level state declarations block)

        // Get all chats for a project (Single Source of Truth: chatState.conversations)
        function loadProjectChats(projectId) {
            if (!projectId) return [];
            if (typeof chatState !== 'undefined' && Array.isArray(chatState.conversations)) {
                return chatState.conversations.filter(c => c.projectId === projectId);
            }
            try {
                const raw = localStorage.getItem('mestrio_platform_chats_v1');
                if (raw) {
                    const parsed = JSON.parse(raw);
                    if (parsed && Array.isArray(parsed.conversations)) {
                        return parsed.conversations.filter(c => c.projectId === projectId);
                    }
                }
            } catch (e) { }
            try {
                return JSON.parse(localStorage.getItem('proj_chats_' + projectId) || '[]');
            } catch (e) { return []; }
        }

        function saveProjectChats(projectId, chats) {
            if (typeof saveToLocalStorage === 'function') {
                saveToLocalStorage();
            }
            if (typeof renderRecentChats === 'function') {
                renderRecentChats();
            }
            try {
                if (projectId && Array.isArray(chats)) {
                    localStorage.setItem('proj_chats_' + projectId, JSON.stringify(chats));
                }
            } catch (e) { }
        }

        // Show the landing view for a project
        function showProjectLanding(projectId) {
            const landingView = document.getElementById('project-landing-view');
            const activeChatView = document.getElementById('project-active-chat-view');
            if (landingView) landingView.classList.remove('hidden');
            if (activeChatView) activeChatView.classList.add('hidden');
            currentActiveChatId = null;
            projectLandingAttachments = [];
            renderProjectComposerChips('landing');
            renderProjectChatsList(projectId);
            updateProjectModelUI(projectId);
            updateProjectToggleUI(projectId);
            renderProjectModelOptions(projectId);
            setProjectLandingSearchMode('search');
            updateProjectLandingSendBtn();
            const chatInput = document.getElementById('project-chat-input');
            if (chatInput) {
                chatInput.value = '';
                chatInput.style.height = '48px';
                setTimeout(() => chatInput.focus(), 60);
            }
            if (window.lucide) window.lucide.createIcons();
        }

        // Show a specific chat inside the project
        function showProjectActiveChat(projectId, chatId) {
            const landingView = document.getElementById('project-landing-view');
            const activeChatView = document.getElementById('project-active-chat-view');
            if (landingView) landingView.classList.add('hidden');
            if (activeChatView) activeChatView.classList.remove('hidden');
            currentActiveChatId = chatId;
            projectActiveAttachments = [];
            renderProjectComposerChips('active');

            const projects = loadProjectsFromStorage();
            const project = projects.find(p => p.id === projectId);

            // Retrieve that exact chat using its ID from the main chats list (Single Source of Truth)
            const allChats = (typeof chatState !== 'undefined' && Array.isArray(chatState.conversations))
                ? chatState.conversations
                : [];
            let activeChat = allChats.find(c => c.id === chatId);
            if (!activeChat) {
                activeChat = allChats.find(c =>
                    (chatId === 'demo-1' && c.id === 'seed_1') ||
                    (chatId === 'demo-2' && c.id === 'seed_2') ||
                    (chatId === 'demo-3' && c.id === 'seed_3') ||
                    (chatId === 'demo-4' && c.id === 'seed_4')
                );
            }
            if (!activeChat) {
                try {
                    const raw = localStorage.getItem('mestrio_platform_chats_v1');
                    if (raw) {
                        const parsed = JSON.parse(raw);
                        if (parsed && Array.isArray(parsed.conversations)) {
                            activeChat = parsed.conversations.find(c => c.id === chatId);
                            if (activeChat && typeof chatState !== 'undefined' && Array.isArray(chatState.conversations)) {
                                chatState.conversations.push(activeChat);
                            }
                        }
                    }
                } catch (e) { }
            }

            if (activeChat && activeChat.projectId !== projectId) {
                activeChat.projectId = projectId;
                saveToLocalStorage();
            }

            if (activeChat) {
                if (typeof chatState !== 'undefined') {
                    chatState.currentConversationId = activeChat.id;
                }
            }

            // Update breadcrumb
            const bcProject = document.getElementById('breadcrumb-project-name');
            const bcChat = document.getElementById('breadcrumb-chat-title');
            if (bcProject) bcProject.textContent = project ? project.name : 'Project';
            if (bcChat) bcChat.textContent = activeChat ? activeChat.title : 'Chat';

            // Pass that chat's real messages array directly to the active chat stream renderer
            renderChatMessages(activeChat ? (activeChat.messages || []) : []);

            updateProjectModelUI(projectId);
            updateProjectToggleUI(projectId);
            renderProjectModelOptions(projectId);
            if (typeof syncProjectActiveInputBarState === 'function') {
                syncProjectActiveInputBarState(projectId, chatId);
            }
            const activeInput = document.getElementById('project-active-chat-input');
            if (activeInput) { activeInput.value = ''; setTimeout(() => activeInput.focus(), 60); }
            if (window.lucide) window.lucide.createIcons();
        }

        function deleteProjectChat(projectId, chatId) {
            if (typeof chatState !== 'undefined' && Array.isArray(chatState.conversations)) {
                chatState.conversations = chatState.conversations.filter(c => c.id !== chatId);
                if (chatState.currentConversationId === chatId) {
                    chatState.currentConversationId = null;
                }
                saveToLocalStorage();
                renderRecentChats();
            }
            try {
                const key = 'proj_chats_' + projectId;
                let legacy = JSON.parse(localStorage.getItem(key) || '[]');
                legacy = legacy.filter(c => c.id !== chatId);
                localStorage.setItem(key, JSON.stringify(legacy));
            } catch (e) { }

            if (currentActiveChatId === chatId) {
                showProjectLanding(projectId);
            } else {
                renderProjectChatsList(projectId);
            }
        }

        function closeAllChatRowDropdowns() {
            document.querySelectorAll('.chat-row-dropdown').forEach(d => d.classList.add('hidden'));
        }

        // ── Custom Project Chat Modals State & Logic ───────────────────
        let pendingRenameProjectId = null;
        let pendingRenameChatId = null;
        let pendingDeleteChatProjectId = null;
        let pendingDeleteChatId = null;

        function openRenameChatModal(projectId, chat) {
            pendingRenameProjectId = projectId;
            pendingRenameChatId = chat.id;
            const modal = document.getElementById('project-rename-chat-modal');
            const input = document.getElementById('project-rename-chat-input');
            if (!modal || !input) return;
            input.value = chat.title || '';
            modal.classList.remove('hidden');
            setTimeout(() => {
                input.focus();
                input.select();
            }, 60);
            if (window.lucide) window.lucide.createIcons();
        }

        function closeRenameChatModal() {
            const modal = document.getElementById('project-rename-chat-modal');
            if (modal) modal.classList.add('hidden');
            pendingRenameProjectId = null;
            pendingRenameChatId = null;
        }

        function handleRenameChatSubmit(e) {
            if (e) e.preventDefault();
            if (!pendingRenameProjectId || !pendingRenameChatId) {
                closeRenameChatModal();
                return;
            }
            const input = document.getElementById('project-rename-chat-input');
            const newTitle = input ? input.value.trim() : '';
            if (newTitle) {
                const allChats = (typeof chatState !== 'undefined' && Array.isArray(chatState.conversations))
                    ? chatState.conversations
                    : [];
                const chat = allChats.find(c => c.id === pendingRenameChatId);
                if (chat && chat.title !== newTitle) {
                    chat.title = newTitle;
                    saveToLocalStorage();
                    renderRecentChats();
                    saveProjectChats(pendingRenameProjectId, loadProjectChats(pendingRenameProjectId));
                    renderProjectChatsList(pendingRenameProjectId);
                    const bcChat = document.getElementById('breadcrumb-chat-title');
                    if (bcChat && currentActiveChatId === chat.id) {
                        bcChat.textContent = chat.title;
                    }
                    if (typeof showStudioToast === 'function') {
                        showStudioToast('Chat renamed');
                    }
                }
            }
            closeRenameChatModal();
        }

        function openDeleteChatModal(projectId, chat) {
            pendingDeleteChatProjectId = projectId;
            pendingDeleteChatId = chat.id;
            const modal = document.getElementById('project-delete-chat-modal');
            if (!modal) return;
            modal.classList.remove('hidden');
            if (window.lucide) window.lucide.createIcons();
        }

        function closeDeleteChatModal() {
            const modal = document.getElementById('project-delete-chat-modal');
            if (modal) modal.classList.add('hidden');
            pendingDeleteChatProjectId = null;
            pendingDeleteChatId = null;
        }

        function confirmDeleteChat() {
            if (pendingDeleteChatProjectId && pendingDeleteChatId) {
                deleteProjectChat(pendingDeleteChatProjectId, pendingDeleteChatId);
                if (typeof showStudioToast === 'function') {
                    showStudioToast('Chat deleted');
                }
            }
            closeDeleteChatModal();
        }

        function initProjectChatModals() {
            const renameModal = document.getElementById('project-rename-chat-modal');
            const renameForm = document.getElementById('project-rename-chat-form');
            const renameCancelBtn = document.getElementById('project-rename-chat-cancel-btn');
            const renameCloseX = document.getElementById('project-rename-chat-close-x');

            const deleteModal = document.getElementById('project-delete-chat-modal');
            const deleteCancelBtn = document.getElementById('project-delete-chat-cancel-btn');
            const deleteConfirmBtn = document.getElementById('project-delete-chat-confirm-btn');
            const deleteCloseX = document.getElementById('project-delete-chat-close-x');

            renameForm?.addEventListener('submit', handleRenameChatSubmit);
            renameCancelBtn?.addEventListener('click', closeRenameChatModal);
            renameCloseX?.addEventListener('click', closeRenameChatModal);
            renameModal?.addEventListener('click', (e) => {
                if (e.target === renameModal) closeRenameChatModal();
            });

            deleteConfirmBtn?.addEventListener('click', confirmDeleteChat);
            deleteCancelBtn?.addEventListener('click', closeDeleteChatModal);
            deleteCloseX?.addEventListener('click', closeDeleteChatModal);
            deleteModal?.addEventListener('click', (e) => {
                if (e.target === deleteModal) closeDeleteChatModal();
            });

            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape') {
                    if (renameModal && !renameModal.classList.contains('hidden')) {
                        closeRenameChatModal();
                    }
                    if (deleteModal && !deleteModal.classList.contains('hidden')) {
                        closeDeleteChatModal();
                    }
                }
            });
        }
        initProjectChatModals();

        // Render "Your chats" list on the landing view (Requirement 3: Pinned chats + 3-dots dropdown)
        function renderProjectChatsList(projectId) {
            const container = document.getElementById('project-chats-list');
            const emptyEl = document.getElementById('project-chats-empty');
            if (!container) return;
            const chats = loadProjectChats(projectId);
            container.innerHTML = '';

            // Update message count
            const msgCountEl = document.getElementById('project-detail-msg-count');
            const totalMsgs = chats.reduce((sum, c) => sum + (c.messages ? c.messages.length : 0), 0);
            if (msgCountEl) msgCountEl.textContent = totalMsgs;

            if (!chats || chats.length === 0) {
                if (emptyEl) emptyEl.classList.remove('hidden');
                return;
            }
            if (emptyEl) emptyEl.classList.add('hidden');

            // Sort: pinned chats first, then newest first
            chats.sort((a, b) => {
                if (!!a.isPinned !== !!b.isPinned) {
                    return a.isPinned ? -1 : 1;
                }
                return new Date(b.createdAt || 0) - new Date(a.createdAt || 0);
            });

            chats.forEach(chat => {
                const row = document.createElement('div');
                const msgCount = chat.messages ? chat.messages.length : 0;
                row.className = 'w-full flex items-center justify-between p-3 bg-white border border-slate-100 hover:border-blue-200 hover:bg-blue-50/30 rounded-xl transition-all shadow-xs hover:shadow-sm cursor-pointer group relative';
                row.innerHTML = `
                    <div class="flex items-center gap-3 min-w-0 flex-1 mr-2">
                        <div class="w-8 h-8 rounded-lg ${chat.isPinned ? 'bg-blue-100 text-blue-700 border border-blue-200' : 'bg-blue-50 border border-blue-100/60 text-blue-600'} flex items-center justify-center shrink-0 group-hover:bg-blue-100 transition-colors">
                            <i data-lucide="${chat.isPinned ? 'pin' : 'message-circle'}" class="w-4 h-4 ${chat.isPinned ? 'fill-blue-700' : ''}"></i>
                        </div>
                        <div class="min-w-0 flex-1">
                            <div class="flex items-center gap-1.5">
                                <span class="text-xs font-semibold text-slate-800 group-hover:text-blue-900 transition-colors truncate">${escapeHtml(chat.title)}</span>
                                ${chat.isPinned ? '<span class="inline-flex items-center gap-0.5 px-1.5 py-0.2 rounded text-[10px] font-semibold bg-blue-50 text-blue-600 border border-blue-100/80 shrink-0">Pinned</span>' : ''}
                            </div>
                            <div class="text-[11px] text-slate-400 truncate mt-0.5">${msgCount} ${msgCount === 1 ? 'message' : 'messages'}</div>
                        </div>
                    </div>
                    <div class="flex items-center gap-2 shrink-0">
                        <span class="text-[10px] font-medium text-slate-400 bg-slate-50 px-2 py-0.5 rounded-md border border-slate-100 group-hover:bg-white group-hover:border-blue-100 group-hover:text-blue-600 transition-colors">${formatTimeAgo(chat.createdAt)}</span>
                        
                        <!-- 3-Dots Menu Dropdown (Requirement 3) -->
                        <div class="relative chat-item-menu-wrapper">
                            <button type="button" class="btn-chat-row-menu p-1.5 rounded-lg text-slate-400 hover:text-slate-700 hover:bg-slate-100 transition-all cursor-pointer opacity-70 group-hover:opacity-100" title="Chat options">
                                <i data-lucide="more-horizontal" class="w-4 h-4 pointer-events-none"></i>
                            </button>
                            <div class="chat-row-dropdown hidden absolute right-0 top-full mt-1 w-40 bg-white rounded-xl border border-neutral-200 shadow-lg py-1 z-30 text-xs">
                                <button type="button" class="btn-action-pin-chat w-full flex items-center gap-2 px-3 py-1.5 text-slate-700 hover:bg-slate-50 hover:text-slate-900 transition-colors text-left cursor-pointer">
                                    <i data-lucide="pin" class="w-3.5 h-3.5 ${chat.isPinned ? 'text-blue-600 fill-blue-600' : 'text-slate-400'} shrink-0"></i>
                                    <span>${chat.isPinned ? 'Unpin chat' : 'Pin chat'}</span>
                                </button>
                                <button type="button" class="btn-action-manage-chat w-full flex items-center gap-2 px-3 py-1.5 text-slate-700 hover:bg-slate-50 hover:text-slate-900 transition-colors text-left cursor-pointer">
                                    <i data-lucide="edit-2" class="w-3.5 h-3.5 text-slate-400 shrink-0"></i>
                                    <span>Manage chat</span>
                                </button>
                                <div class="my-0.5 border-t border-slate-100"></div>
                                <button type="button" class="btn-action-delete-chat flex items-center gap-2.5 px-3 py-1.5 text-xs text-red-600 hover:bg-red-50 rounded-lg cursor-pointer transition-colors w-full font-medium text-left">
                                    <i data-lucide="trash-2" class="w-3.5 h-3.5 text-red-500 shrink-0"></i>
                                    <span>Delete</span>
                                </button>
                            </div>
                        </div>
                    </div>
                `;

                row.addEventListener('click', (e) => {
                    if (e.target.closest('.chat-item-menu-wrapper')) return;
                    showProjectActiveChat(projectId, chat.id);
                });

                const menuBtn = row.querySelector('.btn-chat-row-menu');
                const dropdown = row.querySelector('.chat-row-dropdown');
                const pinActionBtn = row.querySelector('.btn-action-pin-chat');
                const manageActionBtn = row.querySelector('.btn-action-manage-chat');
                const deleteActionBtn = row.querySelector('.btn-action-delete-chat');

                menuBtn?.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const wasHidden = dropdown?.classList.contains('hidden');
                    closeAllChatRowDropdowns();
                    closeProjectHeaderDropdown();
                    if (wasHidden && dropdown) dropdown.classList.remove('hidden');
                });

                pinActionBtn?.addEventListener('click', (e) => {
                    e.stopPropagation();
                    closeAllChatRowDropdowns();
                    chat.isPinned = !chat.isPinned;
                    saveProjectChats(projectId, chats);
                    renderProjectChatsList(projectId);
                    if (typeof showStudioToast === 'function') {
                        showStudioToast(chat.isPinned ? 'Chat pinned to top' : 'Chat unpinned');
                    }
                });

                manageActionBtn?.addEventListener('click', (e) => {
                    e.stopPropagation();
                    closeAllChatRowDropdowns();
                    openRenameChatModal(projectId, chat);
                });

                deleteActionBtn?.addEventListener('click', (e) => {
                    e.stopPropagation();
                    closeAllChatRowDropdowns();
                    openDeleteChatModal(projectId, chat);
                });

                container.appendChild(row);
            });
            if (window.lucide) window.lucide.createIcons();
        }

        // Stream renderer for chat messages
        function renderChatMessages(messages) {
            renderActiveChatMessages(messages);
        }
        window.renderChatMessages = renderChatMessages;
        function renderActiveChatMessages(chatOrMessages) {
            const container = document.getElementById('project-chat-messages');
            if (!container) return;

            let conv = null;
            if (chatOrMessages && typeof chatOrMessages === 'object' && !Array.isArray(chatOrMessages) && chatOrMessages.messages) {
                conv = chatOrMessages;
            } else if (typeof currentActiveChatId !== 'undefined' && currentActiveChatId && typeof chatState !== 'undefined' && Array.isArray(chatState.conversations)) {
                conv = chatState.conversations.find(c => c.id === currentActiveChatId);
            }
            if (!conv && Array.isArray(chatOrMessages)) {
                conv = {
                    id: (typeof currentActiveChatId !== 'undefined' && currentActiveChatId) ? currentActiveChatId : 'project_chat',
                    messages: chatOrMessages,
                    pendingCount: 0
                };
            }
            if (!conv) {
                conv = { id: 'empty', messages: [], pendingCount: 0 };
            }
            renderConversationMessages(container, conv);
        }

        // Legacy: kept for back-compat but now delegates to landing/active views
        function renderProjectChatMessages(project) {
            // If we have an active chat, re-render it; otherwise show landing
            if (currentActiveChatId) {
                const allChats = (typeof chatState !== 'undefined' && Array.isArray(chatState.conversations))
                    ? chatState.conversations
                    : [];
                const chat = allChats.find(c => c.id === currentActiveChatId);
                renderChatMessages(chat ? (chat.messages || []) : []);
            }
        }

        function openProjectDetail(projectId) {
            const projects = loadProjectsFromStorage();
            const project = projects.find(p => p.id === projectId);
            if (!project) return;

            currentActiveProjectId = projectId;
            currentActiveChatId = null;

            const listView = document.getElementById('projects-list-view');
            const detailView = document.getElementById('project-detail-view');

            if (listView) listView.classList.add('hidden');
            if (detailView) detailView.classList.remove('hidden');

            // Update title in landing view
            const titleEl = document.getElementById('project-detail-title');
            if (titleEl) titleEl.textContent = project.name;

            // Update breadcrumb project name for active chat view
            const bcProject = document.getElementById('breadcrumb-project-name');
            if (bcProject) bcProject.textContent = project.name;

            // Load guidelines
            const instructionsTextarea = document.getElementById('project-instructions-textarea');
            if (instructionsTextarea) {
                instructionsTextarea.value = project.instructions || '';
                instructionsTextarea.setAttribute('readonly', 'true');
            }
            const editBtn = document.getElementById('btn-edit-instructions');
            const saveBtn = document.getElementById('btn-save-instructions');
            if (editBtn) editBtn.classList.remove('hidden');
            if (saveBtn) saveBtn.classList.add('hidden');

            // Render sidebar components
            renderProjectFiles(projectId);
            updateProjectMemoryUI(projectId);

            // Created date
            const createdDateEl = document.getElementById('project-detail-created-date');
            if (createdDateEl) {
                createdDateEl.textContent = new Date(project.createdAt).toLocaleDateString([], { month: 'short', day: 'numeric', year: 'numeric' });
            }

            // Clear chips
            const chipsContainer = document.getElementById('project-composer-chips');
            if (chipsContainer) { chipsContainer.innerHTML = ''; chipsContainer.classList.add('hidden'); }
            projectLandingAttachments = [];
            projectActiveAttachments = [];
            renderProjectComposerChips('landing');
            renderProjectComposerChips('active');

            closeProjectPlusDropdown();
            closeProjectModelDropdown();
            closeProjectHeaderDropdown();
            closeAllChatRowDropdowns();

            updateProjectPinUI(projectId);
            updateProjectModelUI(projectId);
            renderProjectModelOptions(projectId);
            updateProjectToggleUI(projectId);

            // Show the landing view by default
            showProjectLanding(projectId);

            if (window.lucide) window.lucide.createIcons();
        }

        // ─── PROJECT ACTIVE DOCKED FOLLOW-UP BAR LOGIC ───────────────────
        let projectActiveSearchMode = 'search'; // 'search' | 'deepResearch' | 'webSearch' | 'compare'

        function setProjectActiveSearchMode(modeKey) {
            projectActiveSearchMode = modeKey || 'search';
            const labelEl = document.getElementById('project-active-search-pill-label');
            const iconEl = document.getElementById('project-active-search-pill-icon');
            const modelWrapper = document.getElementById('project-active-model-selector-wrapper');
            const compareWrapper = document.getElementById('project-active-compare-dropdown-wrapper');
            const inputEl = document.getElementById('project-active-chat-input');

            const labels = {
                search: 'Search',
                deepResearch: 'Deep Research',
                webSearch: 'Web Search',
                compare: 'Compare'
            };

            const icons = {
                search: `<svg class="w-3 h-3" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>`,
                deepResearch: `<svg class="w-3 h-3" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m10.065 12.493-6.18 1.318a.934.934 0 0 1-1.108-.702l-.537-2.15a1.07 1.07 0 0 1 .691-1.265l13.504-4.44"></path><path d="m13.56 11.747 4.332-.924"></path><path d="m16 21-3.105-6.21"></path><path d="M16.485 5.94a2 2 0 0 1 1.455-2.425l1.09-.272a1 1 0 0 1 1.212.727l1.515 6.06a1 1 0 0 1-.727 1.213l-1.09.272a2 2 0 0 1-2.425-1.455z"></path><path d="m6.158 8.633 1.114 4.456"></path><path d="m8 21 3.105-6.21"></path><circle cx="12" cy="13" r="2"></circle></svg>`,
                webSearch: `<svg class="w-3 h-3" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="2" y1="12" x2="22" y2="12"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg>`,
                compare: `<svg class="w-3 h-3" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"></rect><path d="M12 3v18"></path></svg>`
            };

            if (labelEl) labelEl.textContent = labels[projectActiveSearchMode] || 'Search';
            if (iconEl) iconEl.innerHTML = icons[projectActiveSearchMode] || icons.search;

            // Update checkmark state inside dropdown
            document.querySelectorAll('.project-search-mode-opt').forEach(btn => {
                const mode = btn.getAttribute('data-mode');
                const checkIcon = btn.querySelector('.project-search-check-icon');
                if (checkIcon) {
                    if (mode === projectActiveSearchMode) {
                        checkIcon.classList.remove('hidden');
                    } else {
                        checkIcon.classList.add('hidden');
                    }
                }
            });

            if (projectActiveSearchMode === 'compare') {
                if (modelWrapper) modelWrapper.classList.add('hidden');
                if (compareWrapper) compareWrapper.classList.remove('hidden');
                if (!chatState.compareModels || chatState.compareModels.length < 2) {
                    const cur = chatState.selectedModel || 'mahi-engine';
                    const canonicalCur = getCanonicalModelId(cur) || 'mahi-engine';
                    const partner = (canonicalCur === 'claude-4-5-haiku') ? 'gpt-4o-mini' : 'claude-4-5-haiku';
                    chatState.compareModels = Array.from(new Set([canonicalCur, partner]));
                } else {
                    chatState.compareModels = Array.from(new Set(chatState.compareModels.map(getCanonicalModelId).filter(Boolean)));
                }
                renderCompareModelChips();
                if (inputEl) inputEl.placeholder = 'Ask multiple models...';
            } else {
                if (compareWrapper) compareWrapper.classList.add('hidden');
                if (modelWrapper) modelWrapper.classList.remove('hidden');
                if (inputEl) inputEl.placeholder = 'Ask a follow-up...';
            }

            closeProjectActiveSearchDropdown();
        }

        function toggleProjectActiveSearchDropdown() {
            const dropdown = document.getElementById('project-active-search-mode-dropdown');
            const chevron = document.getElementById('project-active-search-chevron');
            if (!dropdown) return;
            const isHidden = dropdown.classList.contains('hidden');
            closeProjectActiveModelDropdown();
            closeProjectActivePlusDropdown();
            if (isHidden) {
                dropdown.classList.remove('hidden');
                if (chevron) chevron.classList.add('rotate-180');
            } else {
                dropdown.classList.add('hidden');
                if (chevron) chevron.classList.remove('rotate-180');
            }
        }

        function closeProjectActiveSearchDropdown() {
            const dropdown = document.getElementById('project-active-search-mode-dropdown');
            const chevron = document.getElementById('project-active-search-chevron');
            if (dropdown && !dropdown.classList.contains('hidden')) {
                dropdown.classList.add('hidden');
            }
            if (chevron) chevron.classList.remove('rotate-180');
        }

        function getProjectActiveSelectedModel() {
            if (typeof currentActiveProjectId !== 'undefined' && currentActiveProjectId) {
                const projModel = getProjectSelectedModel(currentActiveProjectId);
                if (projModel) return projModel;
            }
            if (typeof chatState !== 'undefined' && chatState.selectedModel) {
                return chatState.selectedModel;
            }
            return 'mahi-engine';
        }

        function updateProjectActiveModelUI() {
            const modelNameEl = document.getElementById('project-active-model-name');
            const modelIconEl = document.getElementById('project-active-model-icon');
            if (!modelNameEl) return;

            const selectedId = getProjectActiveSelectedModel();
            const model = AVAILABLE_MODELS.find(m =>
                m.id === selectedId ||
                m.name === selectedId ||
                ((selectedId === 'mahi-engine' || selectedId === 'Auto' || selectedId === 'Mahi Engine (Standard)') && (m.id === 'mahi-engine' || m.isDefault))
            ) || AVAILABLE_MODELS[0];

            const isDefault = !model || model.id === 'mahi-engine' || model.name === 'Mahi Engine (Standard)' || Boolean(model.isDefault);

            if (isDefault) {
                modelNameEl.textContent = 'Mahi Engine';
                if (modelIconEl) {
                    modelIconEl.classList.remove('hidden');
                    modelIconEl.classList.add('flex', 'items-center', 'justify-center');
                    modelIconEl.innerHTML = getProviderIconSvg(model.provider, true, 'w-3.5 h-3.5', model.icon);
                }
            } else {
                modelNameEl.textContent = model.name;
                if (modelIconEl) {
                    modelIconEl.classList.remove('hidden');
                    modelIconEl.classList.add('flex', 'items-center', 'justify-center');
                    modelIconEl.innerHTML = getProviderIconSvg(model.provider, true, 'w-3.5 h-3.5', model.icon);
                }
            }

            renderProjectActiveModelOptions();
        }

        function renderProjectActiveModelOptions() {
            const optionsContainer = document.getElementById('project-active-model-options-list');
            if (!optionsContainer) return;

            const currentSelected = getProjectActiveSelectedModel();

            const proBanner = document.getElementById('project-active-model-dropdown-pro-banner');
            if (proBanner) {
                const innerBanner = proBanner.querySelector('div') || proBanner;
                innerBanner.onclick = (e) => {
                    e.stopPropagation();
                    if (typeof window.onOpenUpgradeModal === 'function') window.onOpenUpgradeModal();
                    else if (typeof window.openUpgradeModal === 'function') window.openUpgradeModal();
                };
            }

            renderUnifiedModelOptionsList(optionsContainer, currentSelected, (model) => {
                if (typeof chatState !== 'undefined') {
                    chatState.selectedModel = model.id;
                }
                if (currentActiveProjectId) {
                    setProjectSelectedModel(currentActiveProjectId, model.id);
                }
                updateProjectActiveModelUI();
                closeProjectActiveModelDropdown();
                saveToLocalStorage();
            });
        }

        function toggleProjectActiveModelDropdown() {
            const dropdown = document.getElementById('project-active-model-dropdown');
            const chevron = document.getElementById('project-active-model-chevron');
            if (!dropdown) return;
            const isHidden = dropdown.classList.contains('hidden');
            closeProjectActivePlusDropdown();
            closeProjectActiveSearchDropdown();
            if (isHidden) {
                dropdown.classList.remove('hidden');
                if (chevron) chevron.classList.add('rotate-180');
                renderProjectActiveModelOptions();
            } else {
                dropdown.classList.add('hidden');
                if (chevron) chevron.classList.remove('rotate-180');
            }
        }

        function closeProjectActiveModelDropdown() {
            const dropdown = document.getElementById('project-active-model-dropdown');
            const chevron = document.getElementById('project-active-model-chevron');
            if (dropdown && !dropdown.classList.contains('hidden')) {
                dropdown.classList.add('hidden');
            }
            if (chevron) chevron.classList.remove('rotate-180');
        }

        function syncProjectActiveInputBarState(projectId, chatId) {
            setProjectActiveSearchMode('search');
            updateProjectActiveModelUI();
            renderCompareModelChips();
            renderProjectComposerChips('active');
        }

        // Project Active Voice Controls
        let isProjectActiveRecording = false;
        let projectActiveStartText = '';

        function initProjectActiveVoiceControls() {
            const micBtn = document.getElementById('project-active-mic-btn');
            const voiceControls = document.getElementById('project-active-voice-active-controls');
            const cancelBtn = document.getElementById('project-active-voice-cancel-btn');
            const confirmBtn = document.getElementById('project-active-voice-confirm-btn');
            const input = document.getElementById('project-active-chat-input');

            function updateVoiceUI(listening) {
                if (listening) {
                    if (micBtn) micBtn.classList.add('hidden');
                    if (voiceControls) {
                        voiceControls.classList.remove('hidden');
                        voiceControls.classList.add('flex');
                    }
                    if (input) {
                        input.classList.add('listening-active');
                        if (!input.value.trim()) input.placeholder = 'Listening...';
                    }
                } else {
                    if (voiceControls) {
                        voiceControls.classList.add('hidden');
                        voiceControls.classList.remove('flex');
                    }
                    if (micBtn) micBtn.classList.remove('hidden');
                    if (input) {
                        input.classList.remove('listening-active');
                        input.placeholder = (projectActiveSearchMode === 'compare') ? 'Ask multiple models...' : 'Ask a follow-up...';
                    }
                }
            }

            micBtn?.addEventListener('click', (e) => {
                e.stopPropagation();
                const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
                if (!SpeechRecognition) {
                    if (typeof showStudioToast === 'function') showStudioToast('Voice input is not supported in this browser');
                    return;
                }
                projectActiveStartText = input ? input.value : '';
                isProjectActiveRecording = true;
                updateVoiceUI(true);

                if (!recognitionInstance) {
                    recognitionInstance = new SpeechRecognition();
                    recognitionInstance.continuous = true;
                    recognitionInstance.interimResults = true;
                    recognitionInstance.lang = navigator.language || 'en-US';
                }

                recognitionInstance.onresult = (evt) => {
                    let finalTranscript = '';
                    let interimTranscript = '';
                    for (let i = 0; i < evt.results.length; ++i) {
                        if (evt.results[i].isFinal) finalTranscript += evt.results[i][0].transcript;
                        else interimTranscript += evt.results[i][0].transcript;
                    }
                    const combined = finalTranscript + interimTranscript;
                    if (input) {
                        const prefix = projectActiveStartText ? (projectActiveStartText.trim() + ' ') : '';
                        input.value = prefix + combined.trimStart();
                        input.style.height = Math.min(input.scrollHeight, 160) + 'px';
                    }
                };

                recognitionInstance.onend = () => {
                    isProjectActiveRecording = false;
                    updateVoiceUI(false);
                };

                recognitionInstance.onerror = () => {
                    isProjectActiveRecording = false;
                    updateVoiceUI(false);
                };

                try { recognitionInstance.start(); } catch (err) { }
            });

            cancelBtn?.addEventListener('click', (e) => {
                e.stopPropagation();
                if (recognitionInstance) {
                    try { recognitionInstance.stop(); } catch (err) { }
                }
                if (input) {
                    input.value = projectActiveStartText;
                    input.style.height = '24px';
                }
                isProjectActiveRecording = false;
                updateVoiceUI(false);
            });

            confirmBtn?.addEventListener('click', (e) => {
                e.stopPropagation();
                if (recognitionInstance) {
                    try { recognitionInstance.stop(); } catch (err) { }
                }
                isProjectActiveRecording = false;
                updateVoiceUI(false);
                if (input && input.value.trim().length > 0) {
                    sendActiveChatMessage();
                }
            });

            input?.addEventListener('paste', (e) => {
                if (e.clipboardData && e.clipboardData.files && e.clipboardData.files.length > 0) {
                    processProjectFileInput('active', e.clipboardData.files, false);
                }
            });
        }

        // Send from landing view → creates a new chat → switches to active chat
        async function sendProjectMessage() {
            if (window.isGeneratingChatResponse) return;
            const input = document.getElementById('project-chat-input');
            if (!input || !currentActiveProjectId) return;
            const text = input.value.trim();
            const currentAttachments = [...projectLandingAttachments];

            const hasContent = text.length > 0 || currentAttachments.length > 0;
            if (!hasContent) return;

            // Await in-flight universal file extractions
            if (currentAttachments.some(a => a._loading && a._extractPromise)) {
                await Promise.all(currentAttachments.map(a => a._extractPromise || Promise.resolve()));
            }

            const projects = loadProjectsFromStorage();
            const project = projects.find(p => p.id === currentActiveProjectId);
            if (!project) return;

            const toggles = getProjectToggles(currentActiveProjectId);
            const selectedModel = getProjectSelectedModel(currentActiveProjectId);

            // Create new chat
            const chatId = 'chat_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6);
            let chatTitle = text.length > 0
                ? (text.length > 50 ? text.slice(0, 50) + '…' : text)
                : (currentAttachments[0]?.name || 'Attachment Chat');

            const newChat = {
                id: chatId,
                title: chatTitle,
                projectId: currentActiveProjectId,
                messages: [],
                createdAt: new Date().toISOString()
            };

            // Add user message to this chat
            newChat.messages.push({
                id: 'msg_' + Date.now(),
                role: 'user',
                content: text,
                attachments: currentAttachments,
                badge: toggles.webSearch ? 'Web Search' : (toggles.deepResearch ? 'Deep Research' : (projectLandingSearchMode === 'compare' ? 'Compare' : null)),
                webSearch: !!toggles.webSearch,
                deepResearch: !!toggles.deepResearch,
                model: selectedModel,
                projectId: currentActiveProjectId,
                createdAt: new Date().toISOString()
            });

            // Save the new chat to single source of truth (chatState.conversations)
            if (typeof chatState !== 'undefined' && Array.isArray(chatState.conversations)) {
                chatState.conversations.unshift(newChat);
                chatState.currentConversationId = chatId;
            }
            saveToLocalStorage();
            renderRecentChats();
            saveProjectChats(currentActiveProjectId, loadProjectChats(currentActiveProjectId));

            // Also update project.messages for backward compat (msg count)
            if (!project.messages) project.messages = [];
            project.messages.push({
                role: 'user',
                content: text,
                attachments: currentAttachments,
                createdAt: new Date().toISOString()
            });
            saveProjectsToStorage(projects);

            input.value = '';
            input.style.height = '48px';
            updateProjectLandingSendBtn();

            // Clear landing attachments state & chips
            projectLandingAttachments = [];
            renderProjectComposerChips('landing');

            // Switch to active chat view
            showProjectActiveChat(currentActiveProjectId, chatId);

            if (typeof window.incrementFreePlanUsage === 'function') window.incrementFreePlanUsage();

            if (toggles.deepResearch) {
                if (typeof startDeepResearchFlow === 'function') {
                    startDeepResearchFlow(newChat, text, currentAttachments);
                }
                saveProjectChats(currentActiveProjectId, loadProjectChats(currentActiveProjectId));
            } else if (projectLandingSearchMode === 'compare') {
                if (typeof startCompareFlow === 'function') {
                    startCompareFlow(newChat, text, currentAttachments);
                }
                saveProjectChats(currentActiveProjectId, loadProjectChats(currentActiveProjectId));
            } else if (toggles.webSearch) {
                newChat.pendingCount = (newChat.pendingCount || 0) + 1;
                renderCurrentConversation();
                renderChatMessages(newChat.messages);
                if (typeof executeLiveChatStream === 'function') {
                    executeLiveChatStream({
                        conv: newChat,
                        targetConvId: newChat.id,
                        selectedModel: selectedModel,
                        searchMode: 'web-search'
                    });
                }
            } else {
                newChat.pendingCount = (newChat.pendingCount || 0) + 1;
                renderCurrentConversation();
                renderChatMessages(newChat.messages);
                if (typeof executeLiveChatStream === 'function') {
                    executeLiveChatStream({
                        conv: newChat,
                        targetConvId: newChat.id,
                        selectedModel: selectedModel,
                        searchMode: 'none'
                    });
                }
            }
        }

        // Send from active chat view (continuing a conversation)
        async function sendActiveChatMessage() {
            if (window.isGeneratingChatResponse) return;
            const input = document.getElementById('project-active-chat-input');
            if (!input || !currentActiveProjectId || !currentActiveChatId) return;
            const text = input.value.trim();
            const currentAttachments = [...projectActiveAttachments];

            const hasContent = text.length > 0 || currentAttachments.length > 0;
            if (!hasContent) return;

            // Await in-flight universal file extractions
            if (currentAttachments.some(a => a._loading && a._extractPromise)) {
                await Promise.all(currentAttachments.map(a => a._extractPromise || Promise.resolve()));
            }

            const selectedModel = (typeof getProjectActiveSelectedModel === 'function')
                ? getProjectActiveSelectedModel()
                : getProjectSelectedModel(currentActiveProjectId);

            const allChats = (typeof chatState !== 'undefined' && Array.isArray(chatState.conversations))
                ? chatState.conversations
                : [];
            const chat = allChats.find(c => c.id === currentActiveChatId);
            if (!chat) return;

            if (typeof chatState !== 'undefined') {
                chatState.currentConversationId = chat.id;
            }

            const isWeb = projectActiveSearchMode === 'webSearch';
            const isDeep = projectActiveSearchMode === 'deepResearch';
            const isCmp = projectActiveSearchMode === 'compare';

            chat.messages.push({
                id: 'msg_' + Date.now(),
                role: 'user',
                content: text,
                attachments: currentAttachments,
                badge: isWeb ? 'Web Search' : (isDeep ? 'Deep Research' : null),
                webSearch: isWeb,
                deepResearch: isDeep,
                model: selectedModel,
                projectId: currentActiveProjectId,
                createdAt: new Date().toISOString()
            });
            saveToLocalStorage();
            renderRecentChats();
            saveProjectChats(currentActiveProjectId, loadProjectChats(currentActiveProjectId));

            input.value = '';
            input.style.height = '24px';

            // Clear active attachments state & chips
            projectActiveAttachments = [];
            renderProjectComposerChips('active');

            renderCurrentConversation();
            renderChatMessages(chat.messages);

            if (typeof window.incrementFreePlanUsage === 'function') window.incrementFreePlanUsage();

            if (isDeep) {
                if (typeof startDeepResearchFlow === 'function') {
                    startDeepResearchFlow(chat, text, currentAttachments);
                }
                saveProjectChats(currentActiveProjectId, loadProjectChats(currentActiveProjectId));
            } else if (isCmp) {
                if (typeof startCompareFlow === 'function') {
                    startCompareFlow(chat, text, currentAttachments);
                }
                saveProjectChats(currentActiveProjectId, loadProjectChats(currentActiveProjectId));
            } else if (isWeb) {
                chat.pendingCount = (chat.pendingCount || 0) + 1;
                renderCurrentConversation();
                renderChatMessages(chat.messages);
                if (typeof executeLiveChatStream === 'function') {
                    executeLiveChatStream({
                        conv: chat,
                        targetConvId: chat.id,
                        selectedModel: selectedModel,
                        searchMode: 'web-search'
                    });
                }
            } else {
                chat.pendingCount = (chat.pendingCount || 0) + 1;
                renderCurrentConversation();
                renderChatMessages(chat.messages);
                if (typeof executeLiveChatStream === 'function') {
                    executeLiveChatStream({
                        conv: chat,
                        targetConvId: chat.id,
                        selectedModel: selectedModel,
                        searchMode: 'none'
                    });
                }
            }
        }


