                if (genBtn) {
                    genBtn.className = 'py-2 px-3 rounded-lg text-xs font-medium text-neutral-600 hover:text-neutral-900 cursor-pointer';
                }
                if (ctaBtn) ctaBtn.textContent = 'Try with Photo';
